INSERT INTO content_unit (slug, bucket, title, kind, sort_order) VALUES ('al-anwaar-al-lateefah-vol-01', 'Islamic', 'Al-Anwaar al-Lateefah -- Volume 1: The Oneness (Tawheed)', 'book', 0) ON CONFLICT(slug) DO UPDATE SET bucket = excluded.bucket, title = excluded.title;
INSERT INTO unit_detail (slug, title_arabic, title_language, study_track, blurb_html, edition_note, cover_key, pdf_key, published_at, source_commit) VALUES ('al-anwaar-al-lateefah-vol-01', 'الأنوار اللطيفة', 'ar', 'reality', '<p>This is a treatise on the oneness of God — tawhid — and the first volume of a longer work. It does not argue by dry definition; it moves, chapter by chapter, as a road the soul is meant to walk: from a sealed lamp and the journey home toward a God whom no pointing can reach and no name can enclose.</p>', NULL, 'al-anwaar-al-lateefah-vol-01/cover.png', 'al-anwaar-al-lateefah-vol-01/book.pdf', '2026-08-14T21:48:48Z', 'a4a2752eb0aa5e7830bf350b75e9cd00add996f8');
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'introduction to the book', 1, 'Introduction to the Book', '<p>This is a treatise on the oneness of God — tawhid (<span class="ar-inline" dir="rtl" lang="ar">تَوْحِيد</span>) — and the first volume of a longer work. It does not argue by dry definition; it moves, chapter by chapter, as a road the soul is meant to walk: from a sealed lamp and the journey home toward a God whom no pointing can reach and no name can enclose.</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'the sealed lamp and the road home', 2, '1. The Sealed Lamp and the Road Home', '<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ، وَصَلَّى اللَّهُ عَلَىٰ رَسُولِهِ وَآلِهِ الطَّيِّبِينَ الطَّاهِرِينَ وَسَلَّمَ عَلَيْهِمْ أَجْمَعِينَ</span></p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'the god no pointing can reach', 3, '2. The God No Pointing Can Reach', '<p>A question has run beneath all of this without being named. What came before treated the seeking, the circle, and the far side reached only by those who bind themselves to the Imams. But the object of that seeking, the One toward whom every step is directed, has not yet been examined. Here the matter turns from the seeker to Him.</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'the sin of naming the unnameable', 4, '3. The Sin of Naming the Unnameable', '<p class="ar-block"><span class="ar-inline" dir="rtl" lang="ar">فَوَقَعَ لِنُوقِعَ عَلَى الْهُوِيَّةِ الْمُتَعَالِيَةِ لِعَجْزِنَا وَضِيقِ جَوْهَرِنَا وَحَصْرِنَا وَقُصُورِنَا</span></p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'what oneness actually means', 5, '4. What Oneness Actually Means', '<p>The realities this teaching unveils ascend by degrees, each standing a little higher than the one before. This matter opens with a saying handed down from the <span class="ar-inline" dir="rtl" lang="ar">حُدُود</span>, the ranks of the spiritual hierarchy, upon whom be peace:</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'the nearest rank: breaking the self to climb', 6, '5. The Nearest Rank: Breaking the Self to Climb', '<p>With the help of God, glory be to Him, and under the gaze of His friend upon His earth, peace be upon him — the price has been named and the reward has been named. Now the door opens, one foot after the other, for this is learned only by entering it.</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'every teacher a threshold, not a god', 7, '6. Every Teacher a Threshold, Not a God', '<p>The man who broke himself at the threshold climbed, and what became of him after the climb is quieter and stranger than the climb itself. It concerns not what he gained but what he became. The soul of the <span class="ar-inline" dir="rtl" lang="ar">مُكَثِّر</span> — the one who has outstripped the others and stands at the summit of the human ranks — was changed by the road he traveled.</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'out of nothing, and equal in justice', 8, '7. Out of Nothing, and Equal in Justice', '<p>The promised road runs on, and now it turns back behind the ranks themselves to ask after the act that made them. Before there was a first of the spiritual ranks for a soul to cross into, before there was any rank at all, there was an origination — a bringing-into-being out of which the ranks, the worlds, and the souls of all people came. That act is where the road turns now, drawing on a long exposition by Sayyidna Mohyuddin, whose argument follows here in summary, its bones kept whole — beginning where he begins, with the Name and then with the ground:</p>
INSERT INTO chapter (slug, anchor_key, idx, title, html, word_count) VALUES ('al-anwaar-al-lateefah-vol-01', 'the first to say there is no god but he', 9, '8. The First to Say There Is No God But He', '<p>One of those forms turned, and looked.</p>
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 1, 'Trust and the Science of Realities', 'Before a single doctrine of the Oneness is taught, the recorder of these lessons stops to say what they are and how they reached us: an inherited wisdom drawn not from speculation but from the sciences of the prophets and the Friends of Allah, recorded by explicit permission and deposited in the treasury of the sacred mission. He binds the listener with a covenant of safekeeping — and names a punishment of cold iron for those who break it — then lays out the book''s symmetrical fivefold architecture and its method: to state pure reality directly, with no interpretation and no symbol. From there the doctrine opens, declaring that the Oneness of Allah is reached by two things only, loving allegiance and lawful action, and that this is the road by which the exiled soul returns to the homeland of spirits from which it first came.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 2, 'The Unknowable Originator', 'The opening lesson laid the road home; this one turns to face what waits at its end — and finds the One toward whom the whole return is directed beyond every reach we have. No indication falls upon the Originator, no thought can bridge the gap to Him, and the names and attributes we use slide off Him entirely, since a created name can only characterize its like and never its own maker. Those names land instead upon the First Intellect, the first thing He brought forth; and the incapacity to know Him is shown to be universal, shared by the highest intelligence and the lowest body alike. The episode closes on the strangest teaching of all — that our very word "Allah" is not a description but the cry of a bewildered creation circling a center it cannot comprehend, lit up through the famous exchange in which the Commander of the Faithful says he saw God not with the eye but with insight.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 3, 'Naming the Unnameable', 'The previous lesson closed on a paradox: the First Intellect cannot know the Originator, yet it is the First Intellect that first speaks of Him. This episode follows that speaking to its strange conclusion. It opens with the primal act in which the First Intellect negated divinity from itself and affirmed it for Allah alone — the act the Qur''an records as "Allah testifies that there is no god but He." It shows why we name Him only out of compelled inadequacy, having been given knowledge of life but never knowledge of His essence; why the existence He grants is never reclaimed, so that His refusal to do injustice is the perfection of His power; and why naming the Unnameable is a sin that arrives already joined to the asking of forgiveness — excused, like the woman judged before Umar, because it is compelled. It closes with the ten ascending ranks of the spiritual ladder, whose summit is the bare "He," and the hidden meanings folded into the pairings of prayer.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 4, 'What Tawhid Really Is', 'The volume''s boldest move: the teaching overturns the most common answer to the most basic question. Asked what it means to affirm the Oneness of Allah, almost everyone says it means to consider Him one — and the hudud reply that this, taken as a definition, is shirk, because it subjects the One to number. Tawhid is something else entirely: the gnosis of the ranks, the recognition that each rank of the spiritual hierarchy is unique in its place, and the knowledge of where each stands and how high it rises. Because the beings are innumerable, this is the highest and most inexhaustible of all knowledge, and a soul''s own station is set by how much of it he attains — through his effort meeting the grace from above. The episode closes on the three branches of the full saying: Tawhid, the gnosis of the ranks; tanzih, the denial that any rank can originate; and tajrid, the stripping of every name and attribute from Allah.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 5, 'The Two Gnoses and the Mukathir', 'How can a saint''s most devoted disciple and his sworn enemy know him equally well? Because the gnosis of the ranks comes in two kinds. The outer gnosis knows a rank''s person and station — and in it the friend and the foe stand on exactly the same footing, for both see the same outward man. The inner gnosis reaches the beginning, the level, and the return of a rank''s essence, and is reserved for the disciplined and the verifying among the people of truth; without it, the teaching warns, a man may have no Tawhid at all. The episode then maps the approach to the hierarchy: two thresholds that are not yet ranks — the Mustajib who binds himself by the tongue and the Mu''min who joins tongue, heart, and limb, each with ten levels — and the first true rank, the Mukathir, entered by breaking one''s own self against the command of Allah and the Prophet, which is why knowledge is indispensable to him.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 6, 'The Mukathir, House of Allah', 'What if the holiest man you ever met looked, to the eye, exactly like everyone else — and the whole difference lay in something no inspection could detect? The Mukathir and the ordinary man are made of the same flesh and blood, gathered within the same bodily bounds, and yet they are not the same: the Mukathir''s temperament has been refined and his essence purified through an ascent that reaches even into his outward composition, though no eye can see it. Standing at the summit of the human — which is the threshold of the spiritual world — and holding the command of Allah and the Prophet before him in every thought, word, and deed, he becomes a house from the houses of Allah, a place on which revelation descends; the Qur''an''s houses, and the men whom no commerce diverts, are these very ranks. Their "establishing of prayer" is, in its depth, the establishing of the divine summons — and beneath every pillar of the religion there lies just such an inner meaning, the whole law one continuous training of the soul in knowledge and allegiance.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 7, 'Ascent, Decline, and a God', 'Two men stand on the same platform, made of the same flesh, born into the same world — and one is rising toward Allah while the other is sinking below the level of cattle. What separates them is nothing in their composition but only the establishing of prayer in its inner sense. The same logic is written into the animal kingdom, where lawful and forbidden creatures of one created stuff part ways by their nearness or aversion to man, and the obedient and disobedient among men are separated by a distance greater still. The Mukathir''s sensory soul, meanwhile, has been dyed luminous by the divine sciences flowing into it; and where such purity is genuinely present, a true rank is genuinely present, though it rests hidden with Allah. At the heart of the episode stands the bewildered disciple, for whom his overwhelming teacher has become a "god" — not a creator, but the center of the circle around which his astonishment turns.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 8, 'The Ladder of Tawhid', 'If the guide leading you to Allah is himself bewildered before someone greater, is he still your god — or is that bewilderment the thing that points past him? The disciple who was left circling his teacher looks upward and sees that the teacher is himself bewildered before the rank above him, and that one before the next, rank upon rank to the First Intellect bewildered before the Originator. Recognizing that bewilderment as the universal condition — and as the first step of all knowledge, which is the confession that one does not know — he negates divinity from every rank and affirms it for Allah alone, completing tanzih above both the limited and the unlimited ranks and tajrid of every name, before returning to his own station and obedience. The linked circles of the divine summons, and the very letters of the word for "god," carry this same structure; the created gods are told apart from the one true God by their need of a nourisher above them; and the tranquil soul is sent home to its Lord, its serenity the fruit of its gnosis — the whole matter summarized, the teaching says, in the Qur''an''s opening chapter and its three classes of men.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 9, 'Origination From Nothing', 'Before anything existed, where was the world that was about to be made? The answer is stranger than "nowhere": there was no "where" at all. The teaching turns from the gnosis of the ranks to the act that produced them, summarizing a long exposition of Sayyidna Mohyuddin. The Originator brought the world of origination into being in a single instant, from no prior matter, no concurrent matter, and no underlying place — an act utterly unlike the making we know, which only reshapes what already exists. He created not from need, for a god who needed his creation would be a god in lack, but from pure favor, drawing the existents out of a nothingness that was no place at all. What He brought forth were luminous imaginal forms on which the human body was later patterned — the soul a fallen copy of the form, the body a fallen copy of the soul, so that salvation is a return from dark density toward luminous subtlety. And He created all the forms perfectly equal in their first perfection, as an act of the justice that gives to none more and to none less.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 10, 'Equal but Not Infallible', 'If every being was created perfectly equal, with nothing to separate the first from the last, how did anything ever go wrong? The teaching answers by drawing out what follows from the absence of any obstacle in the abode of origination: the whole order came into being not in time but in a single instant — sunlight flooding the air, fire filling a dark room — with the potential and the actual intellects existing together and no interval between the first perfection and the second. The equal forms, though created without the slightest disparity, were not yet infallible; and error, the teaching makes precise, is exactly the failure to attain the second perfection — whether by one''s own slipping or by making others slip. From that trial-state of free equality, one form looked at its own essence, recognized an Originator unlike it and its kind, and negated, affirmed, and bore witness in a single act — becoming the first Possessor of Tawhid, and reaching toward the Originator through the means of His own unreachable greatness.
INSERT INTO episode (slug, number, title, blurb, style, audio_key, transcript_key, duration_s, session_number) VALUES ('al-anwaar-al-lateefah-vol-01', 11, 'The Word and the Greatest Name', 'What single sentence could contain everything that has ever happened and everything that ever will — and end, by design, at the number seven? In answer to the first form''s seeking of means, the divine supports descended, and there connected with him the Word of Allah — the testimony of Oneness, above the intellect and below the Originator, the link through which all knowledge and light flow for as long as creation endures. Through that Word the First Intellect came to encompass all that was and will be, but only after first negating himself, for self-negation always precedes the gift. The Word''s numbered composition — two, three, five, four, seven, twelve, nineteen — is the skeleton showing through scripture, the opening formula of the Qur''an, the seven Imams and their twelve deputies, and the originated world itself; and knowledge was seen to deepen reverence, so that it is the learned who most fear Allah. The First Intellect was raised to be Allah''s veil, gate, and Greatest Name — the sole means to the seeking, the discourse, and the declaring of Oneness, which is why allegiance to the wali is the only door to Tawhid. Against his success stands the second emanation, undone not by denial but by the delusion that his vision equaled the First Intellect''s, while above them all stands the circle of oneness that belongs to the Originator alone. So the first canopy of this book of lights is brought to its close.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'blurb', NULL, 'Al-Anwaar al-Lateefah -- Volume 1: The Oneness (Tawheed)', 0, NULL, 'This is a treatise on the oneness of God — tawhid — and the first volume of a longer work. It does not argue by dry definition; it moves, chapter by chapter, as a road the soul is meant to walk: from a sealed lamp and the journey home toward a God whom no pointing can reach and no name can enclose.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed', 'this is a treatise on the oneness of god tawhid and the first volume of a longer work it does not argue by dry definition it moves chapter by chapter as a road the soul is meant to walk from a sealed lamp and the journey home toward a god whom no pointing can reach and no name can enclose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'introduction to the book', 'Introduction to the Book', 0, NULL, 'This is a treatise on the oneness of God — tawhid (تَوْحِيد) — and the first volume of a longer work. It does not argue by dry definition; it moves, chapter by chapter, as a road the soul is meant to walk: from a sealed lamp and the journey home toward a God whom no pointing can reach and no name can enclose.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed introduction to the book', 'this is a treatise on the oneness of god tawhid توحيد and the first volume of a longer work it does not argue by dry definition it moves chapter by chapter as a road the soul is meant to walk from a sealed lamp and the journey home toward a god whom no pointing can reach and no name can enclose', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'introduction to the book', 'Introduction to the Book', 1, NULL, 'Its central claim is that the oneness of God is not a number but a purity. To speak of Him at all, the book holds, one must strip away every attribute that would liken Him to a created thing — for to name the unnameable is itself a kind of transgression. From there it turns to what oneness actually means, and to the ranks by which a person climbs toward it: the breaking of the self at the nearest rank, and the recognition that every teacher is a threshold to be crossed, not a god to be worshipped in place of God.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed introduction to the book', 'its central claim is that the oneness of god is not a number but a purity to speak of him at all the book holds one must strip away every attribute that would liken him to a created thing for to name the unnameable is itself a kind of transgression from there it turns to what oneness actually means and to the ranks by which a person climbs toward it the breaking of the self at the nearest rank and the recognition that every teacher is a threshold to be crossed not a god to be worshipped in place of god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'introduction to the book', 'Introduction to the Book', 2, NULL, 'The later chapters treat of creation out of nothing and of a justice in which all stand equal, closing with the first who declared that there is no god but He.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed introduction to the book', 'the later chapters treat of creation out of nothing and of a justice in which all stand equal closing with the first who declared that there is no god but he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'introduction to the book', 'Introduction to the Book', 3, NULL, 'No author is named within the volume itself. It speaks throughout not in one man''s voice but as a transmitted report, handing down what it teaches rather than claiming it as its own.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed introduction to the book', 'no author is named within the volume itself it speaks throughout not in one mans voice but as a transmitted report handing down what it teaches rather than claiming it as its own', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 0, NULL, 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ، وَصَلَّى اللَّهُ عَلَىٰ رَسُولِهِ وَآلِهِ الطَّيِّبِينَ الطَّاهِرِينَ وَسَلَّمَ عَلَيْهِمْ أَجْمَعِينَ', '', 'أَعُوذُ بِاللَّهِ مِنَ الشَّيْطَانِ الرَّجِيمِ، بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ، وَصَلَّى اللَّهُ عَلَىٰ رَسُولِهِ وَآلِهِ الطَّيِّبِينَ الطَّاهِرِينَ وَسَلَّمَ عَلَيْهِمْ أَجْمَعِينَ', NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم وصلي الله علي رسوله واله الطيبين الطاهرين وسلم عليهم اجمعين', 'اعوذ بالله من الشيطان الرجيم بسم الله الرحمن الرحيم وصلي الله علي رسوله واله الطيبين الطاهرين وسلم عليهم اجمعين');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 1, NULL, '"I seek refuge in Allah from the accursed Satan. In the name of Allah, the Most Gracious, the Most Merciful. And may Allah''s blessings be upon His Messenger and his pure and purified family, and may peace be upon them all."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'i seek refuge in allah from the accursed satan in the name of allah the most gracious the most merciful and may allahs blessings be upon his messenger and his pure and purified family and may peace be upon them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 2, NULL, 'So the book begins. Its opening section announces what the entire enterprise is for. It begins:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'so the book begins its opening section announces what the entire enterprise is for it begins', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 3, NULL, 'Sayingنَقُولُ: وَلَمَّا كَانَ مَا هُوَ المَقْصُودُ، وَالكَلَامُ عَلَى المَوَدَّةِ الشَّرِيفَةِ المُؤَدِّيَةِ إِلَى الوَاجِبَاتِ الشَّرِيفَةِ حَقِيقَةً مَحْضَةً"We say: and since that which is intended — and the discourse here — concerns the noble affections that lead to the noble obligations, taken as a pure reality,"', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingنقول ولما كان ما هو المقصود والكلام علي الموده الشريفه الموديه الي الواجبات الشريفه حقيقه محضه we say and since that which is intended and the discourse here concerns the noble affections that lead to the noble obligations taken as a pure reality', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 4, NULL, 'Sayingلَا تَأْوِيلَ فِيهَا وَلَا رَمْزَ مِنْهَا"in which there is no interpretation and no symbol."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingلا تاويل فيها ولا رمز منها in which there is no interpretation and no symbol', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 5, NULL, 'The aim is declared at the door. It is to treat of the noble affections — the mawaddah — that carry the soul toward the noble obligations, and to treat of them as a pure reality, haqiqatan mahdatan. That phrase carries weight. The book does not set out to explain the zahir (الظَّاهِر), the outer exoteric sense, nor does it climb into taweel, the esoteric interpretation. It sets out to lay the pure, unmixed reality of these matters plainly out.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'the aim is declared at the door it is to treat of the noble affections the mawaddah that carry the soul toward the noble obligations and to treat of them as a pure reality haqiqatan mahdatan that phrase carries weight the book does not set out to explain the zahir الظاهر the outer exoteric sense nor does it climb into taweel the esoteric interpretation it sets out to lay the pure unmixed reality of these matters plainly out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 6, NULL, 'The denial itself is phrased with force, and the grammar sharpens the claim. The words لَا تَأْوِيلَ are read with what the grammarians call nafi al-jins, the negation of the genus, an absolute and categorical denial. Had the text said merely لَا تَأْوِيلٌ فِيهِ, it would mean only that some particular interpretation is absent. But لَا تَأْوِيلَ means that there is no interpretation whatsoever — none of the kind, not a trace of the genus. The same holds for what follows: وَلَا رَمْزَ مِنْهَا — and no symbol, no ramz, from it, and no ishara, no allusion either. The intention, then, is pure reality, stripped alike of veiling interpretation, of symbol, and of allusion. That is the declared method, and the book does no more.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'the denial itself is phrased with force and the grammar sharpens the claim the words لا تاويل are read with what the grammarians call nafi al jins the negation of the genus an absolute and categorical denial had the text said merely لا تاويل فيه it would mean only that some particular interpretation is absent but لا تاويل means that there is no interpretation whatsoever none of the kind not a trace of the genus the same holds for what follows ولا رمز منها and no symbol no ramz from it and no ishara no allusion either the intention then is pure reality stripped alike of veiling interpretation of symbol and of allusion that is the declared method and the book does no more', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 7, NULL, 'From there the discourse opens outward to take in everything that exists. The text goes on:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'from there the discourse opens outward to take in everything that exists the text goes on', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 8, NULL, 'Sayingثُمَّ الكَلَامُ عَلَى كَافَّةِ المَوْجُودَاتِ"Then the discourse is upon all existing things."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingثم الكلام علي كافه الموجودات then the discourse is upon all existing things', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 9, NULL, 'The book proposes to take as its subject all the existents that appeared before our own existence. And it states at once why it must:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'the book proposes to take as its subject all the existents that appeared before our own existence and it states at once why it must', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 10, NULL, 'Sayingإِذْ بِمَعْرِفَةِ ذَٰلِكَ وَالِاطِّلَاعِ عَلَيْهِ، وَطَاعَةِ أَوْلِيَاءِ اللَّهِ وَمَحَبَّتِهِمْ، وَالتَّقَرُّبِ إِلَى اللَّهِ بِهِمْ، وَبِلُزُومِ حُدُودِهِمُ المَنْسُوبِينَ مِنْ قِبَلِ القَائِمِ، بِالعِلْمِ وَالعَمَلِ بِمَا وَرَدَ مِنَ الشَّرَائِعِ، يُهْتَدَىٰ إِلَىٰ تَوْحِيدِ اللَّهِ تَعَالَىٰ وَتَكَبَّرَ"For by the gnosis of that, and the acquaintance with it, and obedience to the Friends of Allah and love for them, and drawing near to Allah through them, and adhering to their appointed Hudud from the direction of the Qaim — with the knowledge and the action that have come through the religious laws — one is guided to the Oneness of Allah, the Exalted and the Supreme."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingاذ بمعرفه ذلك والاطلاع عليه وطاعه اولياء الله ومحبتهم والتقرب الي الله بهم وبلزوم حدودهم المنسوبين من قبل القايم بالعلم والعمل بما ورد من الشرايع يهتدي الي توحيد الله تعالي وتكبر for by the gnosis of that and the acquaintance with it and obedience to the friends of allah and love for them and drawing near to allah through them and adhering to their appointed hudud from the direction of the qaim with the knowledge and the action that have come through the religious laws one is guided to the oneness of allah the exalted and the supreme', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 11, NULL, 'It is through the marifah (الْمَعْرِفَة) — the gnosis — of all those existing things that came into being before us, through truly knowing them and gaining acquaintance with them, that the soul is first set on the road. It is through obedience to the Awliya Allah, the Friends of Allah, and through love of them, and through drawing near to Allah by their means, that the road is actually traveled. Bound up with this is adherence to their حُدُود, the ranks and bounds appointed for the believer, for these حُدُود are mansubin, appointed and assigned, from the direction of the Qaim himself, the way a sealed letter is handed down through ordained bearers, each in his place, before it can reach the one for whom it was written. And it is through the action, the عَمَل, laid down in the shariah, the religious law, that the road is at last completed. By the whole of this together — gnosis, obedience, love, nearness, adherence to the appointed حُدُود, and lawful action — one is guided toward the تَوْحِيد of Allah, the Most High. This is the only road by which the تَوْحِيد of Allah is reached.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'it is through the marifah المعرفه the gnosis of all those existing things that came into being before us through truly knowing them and gaining acquaintance with them that the soul is first set on the road it is through obedience to the awliya allah the friends of allah and through love of them and through drawing near to allah by their means that the road is actually traveled bound up with this is adherence to their حدود the ranks and bounds appointed for the believer for these حدود are mansubin appointed and assigned from the direction of the qaim himself the way a sealed letter is handed down through ordained bearers each in his place before it can reach the one for whom it was written and it is through the action the عمل laid down in the shariah the religious law that the road is at last completed by the whole of this together gnosis obedience love nearness adherence to the appointed حدود and lawful action one is guided toward the توحيد of allah the most high this is the only road by which the توحيد of allah is reached', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 12, NULL, 'Two pillars carry the whole access. Access to the تَوْحِيد of Allah is attained through two things, and through two things only: وِلَايَة and عَمَل — allegiance and action. Wilayah is named here also as muwalat, loyal allegiance, and as muhabbah, love; it is the bond of devotion to the Friends of Allah. And عَمَل is the deed, the action the law lays down. By these two together — by loving allegiance and by righteous action — access is gained. There is no third way through. And the fruit of that attainment is itself twofold, as the text declares:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'two pillars carry the whole access access to the توحيد of allah is attained through two things and through two things only ولايه and عمل allegiance and action wilayah is named here also as muwalat loyal allegiance and as muhabbah love it is the bond of devotion to the friends of allah and عمل is the deed the action the law lays down by these two together by loving allegiance and by righteous action access is gained there is no third way through and the fruit of that attainment is itself twofold as the text declares', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 13, NULL, 'Sayingوَبِذَٰلِكَ تَعْلُو دَرَجَةُ المَعَادِ"And by that, the ranks of the afterlife are elevated,"', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingوبذلك تعلو درجه المعاد and by that the ranks of the afterlife are elevated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 14, NULL, 'Sayingوَيَكُونُ الخَلَاصُ مِنْ هَٰذَا العَالَمِ الكَوْنِ وَالفَسَادِ"and salvation comes from this world of being and corruption."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingويكون الخلاص من هذا العالم الكون والفساد and salvation comes from this world of being and corruption', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 15, NULL, 'By treading this path the ranks of the maad, the afterlife, are raised up for the soul, and salvation is won from this lower world of being and corruption — this realm of generation and decay in which, for now, we are held.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'by treading this path the ranks of the maad the afterlife are raised up for the soul and salvation is won from this lower world of being and corruption this realm of generation and decay in which for now we are held', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 16, NULL, 'That salvation, understood at its deepest, is a homecoming. The text continues:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'that salvation understood at its deepest is a homecoming the text continues', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 17, NULL, 'Sayingوَيُمْكِنُ القَوْدُ إِلَى المَبْدَإِ الَّذِي مِنْهُ الِابْتِدَاءَاتُ الشَّرِيفَةُ"And it becomes possible to return to the origin from which the noble beginnings came,"', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingويمكن القود الي المبدا الذي منه الابتداءات الشريفه and it becomes possible to return to the origin from which the noble beginnings came', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 18, NULL, 'Sayingوَالكَوْنُ مَعَهُمْ فِي دَارِ القُدْسِ"and to dwell with them in the Abode of Sanctity."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingوالكون معهم في دار القدس and to dwell with them in the abode of sanctity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 19, NULL, 'Here the doctrine of return is laid open. Qawd is the leading-back, the return, toward the mabda, the origin — back to that source from which the noble beginnings, the ibtidaat, first issued, the way a river finds its channel before it can ever reach the field it was meant to water. The soul does not belong to this lower world; this is not its native country. Our original homeland — our watan-e-asli — is the world of spirits, the عَالَمُ اَلرُّوح. That is the land we came from, and the whole movement of the religious life is nothing but a turning back toward it. The goal is to make our way home to that origin, and there — وَالكَوْنُ مَعَهُمْ فِي دَارِ القُدْسِ — to dwell together with the Friends of Allah in dar al-quds, the Abode of Sanctity. As the text prays:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'here the doctrine of return is laid open qawd is the leading back the return toward the mabda the origin back to that source from which the noble beginnings the ibtidaat first issued the way a river finds its channel before it can ever reach the field it was meant to water the soul does not belong to this lower world this is not its native country our original homeland our watan e asli is the world of spirits the عالم الروح that is the land we came from and the whole movement of the religious life is nothing but a turning back toward it the goal is to make our way home to that origin and there والكون معهم في دار القدس to dwell together with the friends of allah in dar al quds the abode of sanctity as the text prays', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 20, NULL, 'Sayingبَلَّغَنَا اللَّهُ إِلَيْهِمْ، وَأَعَانَنَا عَلَى الِارْتِقَاءِ وَالوُصُولِ إِلَيْهِمْ، بِحَقِّ مُحَمَّدٍ وَآلِهِ الطَّاهِرِينَ، صَلَوَاتُ اللَّهِ عَلَيْهِمْ أَجْمَعِينَ"May Allah cause us to reach them, and aid us in the ascent and the arrival to them — by the right of Muhammad and his pure progeny, the blessings of Allah be upon them all."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingبلغنا الله اليهم واعاننا علي الارتقاء والوصول اليهم بحق محمد واله الطاهرين صلوات الله عليهم اجمعين may allah cause us to reach them and aid us in the ascent and the arrival to them by the right of muhammad and his pure progeny the blessings of allah be upon them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 21, NULL, 'The text then names this knowledge of the origin with an image:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'the text then names this knowledge of the origin with an image', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 22, NULL, 'Sayingوَهَٰذَا هُوَ العِلْمُ الَّذِي يَدُورُونَ عَلَيْهِ وَيَجُورُونَ لَدَيْهِ"And this is the knowledge around which they revolve, and toward which they incline."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingوهذا هو العلم الذي يدورون عليه ويجورون لديه and this is the knowledge around which they revolve and toward which they incline', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 23, NULL, 'This is the knowledge every creature circles. Each person, each created thing, longs to move toward it and to take hold of it; it is the knowledge of the asl, the root — the knowledge of the mabda, the origin — the answer to the oldest question we carry: where did we come from, what was our beginning. All the creatures, the khalaiq, are wheeling around this knowledge, making their endless rounds about it, aching to know where their origin lies. And yet, for all that circling, they cannot reach it:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'this is the knowledge every creature circles each person each created thing longs to move toward it and to take hold of it it is the knowledge of the asl the root the knowledge of the mabda the origin the answer to the oldest question we carry where did we come from what was our beginning all the creatures the khalaiq are wheeling around this knowledge making their endless rounds about it aching to know where their origin lies and yet for all that circling they cannot reach it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 24, NULL, 'Sayingوَلَا سَبِيلَ لِأَحَدٍ مِنْهُمْ إِلَيْهِ"And there is no path for any of them to it."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingولا سبيل لاحد منهم اليه and there is no path for any of them to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 25, NULL, 'For the generality of creatures there is no path at all to this knowledge. They revolve forever about a center they will never touch.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'for the generality of creatures there is no path at all to this knowledge they revolve forever about a center they will never touch', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 26, NULL, 'There is, however, one exception, and it decides everything:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'there is however one exception and it decides everything', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 27, NULL, 'Sayingإِلَّا القَلِيلَ"Except for a few —"', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingالا القليل except for a few', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 28, NULL, 'Sayingمِمَّنِ اعْتَصَمَ بِالأَئِمَّةِ مِنْ آلِ مُحَمَّدٍ، سَلَامُ اللَّهِ عَلَيْهِمْ أَجْمَعِينَ، وَالْتَزَمَ حُدُودَهُمُ المَيَامِنَ"from among those who held fast to the Imams from the progeny of Muhammad, the peace of Allah be upon them all, and bound themselves to their blessed Hudud."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'sayingممن اعتصم بالايمه من ال محمد سلام الله عليهم اجمعين والتزم حدودهم الميامن from among those who held fast to the imams from the progeny of muhammad the peace of allah be upon them all and bound themselves to their blessed hudud', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sealed lamp and the road home', '1. The Sealed Lamp and the Road Home', 29, NULL, 'The few who reach the knowledge of the origin are precisely those who held fast to the aimma (أَئِمَّة), the Imams from the household of Muhammad, and who bound themselves to the true and blessed حُدُود of those Imams. Only these reach the far side. Only these break out of the circle. The rest go on revolving, lifetime after lifetime, around a goal they cannot attain. And so the matter stands plainly: the knowledge of the origin is not yielded to bare seeking, however fierce the seeking grows. It is granted only to the hand that holds fast to the Imams and submits to their appointed ranks.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 1 the sealed lamp and the road home', 'the few who reach the knowledge of the origin are precisely those who held fast to the aimma ايمه the imams from the household of muhammad and who bound themselves to the true and blessed حدود of those imams only these reach the far side only these break out of the circle the rest go on revolving lifetime after lifetime around a goal they cannot attain and so the matter stands plainly the knowledge of the origin is not yielded to bare seeking however fierce the seeking grows it is granted only to the hand that holds fast to the imams and submits to their appointed ranks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 0, NULL, 'A question has run beneath all of this without being named. What came before treated the seeking, the circle, and the far side reached only by those who bind themselves to the Imams. But the object of that seeking, the One toward whom every step is directed, has not yet been examined. Here the matter turns from the seeker to Him.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'a question has run beneath all of this without being named what came before treated the seeking the circle and the far side reached only by those who bind themselves to the imams but the object of that seeking the one toward whom every step is directed has not yet been examined here the matter turns from the seeker to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 1, NULL, 'The text opens:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the text opens', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 2, NULL, 'Sayingوَكَانَ لَا دَلِيلَ عَلَىٰ ذِكْرِ ذَٰلِكَ إِلَّا بِذِكْرِ اللَّهِ تَعَالَىٰ وَتَكَبَّرَ، الَّذِي بِذِكْرِهِ فِي كُلِّ شَيْءٍ يُسْتَفْتَحُ، وَبِأَسْمَائِهِ الْحُسْنَىٰ يُتَوَسَّلُ إِلَيْهِ فِي كُلِّ مَطْلُوبٍ وَيُسْتَنْجَحُ"And there was no guide to the mention of that except by the mention of Allah, the Exalted and Supreme — by whose mention every thing is opened, and by whose most beautiful names a means is sought to Him in every request, and success is attained."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوكان لا دليل علي ذكر ذلك الا بذكر الله تعالي وتكبر الذي بذكره في كل شيء يستفتح وباسمايه الحسني يتوسل اليه في كل مطلوب ويستنجح and there was no guide to the mention of that except by the mention of allah the exalted and supreme by whose mention every thing is opened and by whose most beautiful names a means is sought to him in every request and success is attained', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 3, NULL, 'There is no path to the mention of these realities except by first mentioning Allah. Without His mention, nothing opens. The word opened — yustaftahu — comes from fataha, to open, yet it has taken the istifal shape, the shape of seeking. Istiftah, also called iftitah, does not merely mean to open; it means to seek the opening, to make the request that a thing be begun at all. So the verse says that by the mention of Allah every thing is not merely unlocked — its very unlocking is asked for and granted. Then wa bi-asmaihi al-husna — by His most beautiful names, the asma al-husna (الْأَسْمَاءُ الْحُسْنَى) — yutawassalu ilayhi, a means is taken to Him. That word too has a root: wasala, to connect, to arrive. A tawassul is the cord thrown to bridge a distance. Through His names, fi kulli matlubin — in every object of seeking, every matlub, the thing sought, as against the talib, the one who does the seeking — yustanjahu, success is granted, from najaha. Through His names, in every request, the request lands.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'there is no path to the mention of these realities except by first mentioning allah without his mention nothing opens the word opened yustaftahu comes from fataha to open yet it has taken the istifal shape the shape of seeking istiftah also called iftitah does not merely mean to open it means to seek the opening to make the request that a thing be begun at all so the verse says that by the mention of allah every thing is not merely unlocked its very unlocking is asked for and granted then wa bi asmaihi al husna by his most beautiful names the asma al husna الاسماء الحسني yutawassalu ilayhi a means is taken to him that word too has a root wasala to connect to arrive a tawassul is the cord thrown to bridge a distance through his names fi kulli matlubin in every object of seeking every matlub the thing sought as against the talib the one who does the seeking yustanjahu success is granted from najaha through his names in every request the request lands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 4, NULL, 'The text now lays down the cornerstone, the stone on which the whole house of belief rests:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the text now lays down the cornerstone the stone on which the whole house of belief rests', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 5, NULL, 'Sayingوَكَانَ مُسَبَّحًا مُتَعَالِيًا عَنْ أَنْ يَقَعَ عَلَيْهِ إِشَارَةُ مُشِيرٍ، أَوْ يَتَجَاسَرَ نَحْوَهُ خَاطِرُ خَاطِرٍ بِتَوَهُّمٍ أَوْ تَفْكِيرٍ"And He is the One glorified, exalted far above that any indicator''s indication should fall upon Him, or that the thought of any thinker should dare toward Him by imagination or by contemplation."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوكان مسبحا متعاليا عن ان يقع عليه اشاره مشير او يتجاسر نحوه خاطر خاطر بتوهم او تفكير and he is the one glorified exalted far above that any indicators indication should fall upon him or that the thought of any thinker should dare toward him by imagination or by contemplation', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 6, NULL, 'He is musabbah — the One whose glorification is performed — in the form musabbah, not musabbih, the glorifier. Human beings are the glorifiers; the tasbih (تَسْبِيح) is theirs to offer, never His to perform. He is mutaali, the One lifted on high, from the root uluww, height. He is lifted so high that no ishara — no pointing of any pointer — can fall upon Him so as to indicate Him. This is the true statement of the matter, the very foundation on which correct doctrine stands: no indication reaches Him. And no thought can cross over to Him either. The verb yatajasaru comes from jisr, a bridge. The khatir, the passing thought of the heart, tries to throw a bridge toward Him and cannot complete the span — not by tawahhum, imagination, and not by tafkir, reasoning. No imagining arrives; no argument arrives. Human beings can know this much and only this much: that since they were made, there is One who made them. But what He is in Himself, what His nature is — of this they know nothing whatever.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'he is musabbah the one whose glorification is performed in the form musabbah not musabbih the glorifier human beings are the glorifiers the tasbih تسبيح is theirs to offer never his to perform he is mutaali the one lifted on high from the root uluww height he is lifted so high that no ishara no pointing of any pointer can fall upon him so as to indicate him this is the true statement of the matter the very foundation on which correct doctrine stands no indication reaches him and no thought can cross over to him either the verb yatajasaru comes from jisr a bridge the khatir the passing thought of the heart tries to throw a bridge toward him and cannot complete the span not by tawahhum imagination and not by tafkir reasoning no imagining arrives no argument arrives human beings can know this much and only this much that since they were made there is one who made them but what he is in himself what his nature is of this they know nothing whatever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 7, NULL, 'This truth lives in a single exchange. In the days of the Commander of the Faithful, a man named Ibn al-Kawwa came to him, meaning to trap him with a question he was sure could not be answered. He asked:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'this truth lives in a single exchange in the days of the commander of the faithful a man named ibn al kawwa came to him meaning to trap him with a question he was sure could not be answered he asked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 8, NULL, 'Sayingهَلْ رَأَيْتَ رَبَّكَ؟"Have you seen your God? Have you seen Allah?"', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingهل رايت ربك have you seen your god have you seen allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 9, NULL, 'And Imam Ali answered him:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'and imam ali answered him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 10, NULL, 'Sayingوَيْلَكَ، أَفَأَعْبُدُ رَبًّا لَمْ أَرَهُ؟"Woe to you — could I worship a God I had not seen? How could I worship a God without having seen Him?"', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingويلك افاعبد ربا لم اره woe to you could i worship a god i had not seen how could i worship a god without having seen him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 11, NULL, 'The man pressed him further: how, then, had he seen Him? And the Mawla replied:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the man pressed him further how then had he seen him and the mawla replied', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 12, NULL, 'Sayingلَمْ تَرَهُ الْعُيُونُ بِمُشَاهَدَةِ الْعِيَانِ، وَلَٰكِنْ رَأَتْهُ الْقُلُوبُ بِحَقَائِقِ الْإِيمَانِ"The eyes did not see Him by the witnessing of sight; rather the hearts saw Him by the realities of faith."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingلم تره العيون بمشاهده العيان ولكن راته القلوب بحقايق الايمان the eyes did not see him by the witnessing of sight rather the hearts saw him by the realities of faith', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 13, NULL, 'The meaning is that he saw Him not with the eyes but with the basirah, with insight. It is a mighty saying. The vision of Allah is not the vision of the physical eye, which can no more fall upon Him than indication or thought can. It is the vision of insight, the inner perception of the heart that affirms Him without ever closing a hand around His essence.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the meaning is that he saw him not with the eyes but with the basirah with insight it is a mighty saying the vision of allah is not the vision of the physical eye which can no more fall upon him than indication or thought can it is the vision of insight the inner perception of the heart that affirms him without ever closing a hand around his essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 14, NULL, 'From this height, something hard and exact follows about His names and His attributes. The text:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'from this height something hard and exact follows about his names and his attributes the text', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 15, NULL, 'Sayingوَكَانَ الْإِعْرَابُ عَنْهُ بِاللَّهِ تَعَالَىٰ وَبِالْمُبْدِعِ بِالْهُوِيَّةِ الْمُتَعَالِيَةِ، غَيْرَ وَاقِعٍ عَلَيْهِ هَذَانِ الِاسْمَانِ وَالصِّفَةُ"And the expression about Him by Allah, the Exalted, and by the Originator, with the exalted Ipseity — these two names and the attribute do not fall upon Him."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوكان الاعراب عنه بالله تعالي وبالمبدع بالهويه المتعاليه غير واقع عليه هذان الاسمان والصفه and the expression about him by allah the exalted and by the originator with the exalted ipseity these two names and the attribute do not fall upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 16, NULL, 'When a name is said of Him — when He is called Allah Taala, or Mubdi (المُبدِع), the Originator, or reached for by the exalted huwiyyah, the Ipseity, the bare "He," the naked huwa — none of these names lands on Him. No attribute lands on Him. The reason is given with a knife''s precision:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'when a name is said of him when he is called allah taala or mubdi المبدع the originator or reached for by the exalted huwiyyah the ipseity the bare he the naked huwa none of these names lands on him no attribute lands on him the reason is given with a knifes precision', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 17, NULL, 'Sayingإِذِ الْأَسْمَاءُ وَالصِّفَاتُ لَا تَقَعُ إِلَّا عَلَىٰ مِثْلِهَا"For names and attributes do not fall except upon their like."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingاذ الاسماء والصفات لا تقع الا علي مثلها for names and attributes do not fall except upon their like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 18, NULL, 'A name reaches only what is of its own kind; an attribute clings only to something like itself. Naming Him works like this. A person, wanting to recognize and know Him, assigns Him a name, and assigns it from his own tongue. But he is the one who made that tongue; he is the one who minted those names. The very instrument by which a person tries to interpret Allah is a thing of his own manufacture. As the Commander of the Faithful said:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'a name reaches only what is of its own kind an attribute clings only to something like itself naming him works like this a person wanting to recognize and know him assigns him a name and assigns it from his own tongue but he is the one who made that tongue he is the one who minted those names the very instrument by which a person tries to interpret allah is a thing of his own manufacture as the commander of the faithful said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 19, NULL, 'Sayingالْأَسْمَاءُ وَالصِّفَاتُ دَلَالَةٌ عَلَى الْمُسَمَّى"Names and attributes are an indication pointing to the named one."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingالاسماء والصفات دلاله علي المسمي names and attributes are an indication pointing to the named one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 20, NULL, 'And they point only to their like. Mercy was seen in some creature, and so the word "Merciful" was lifted and laid upon that creature; the attribute fell upon its like — upon a knowledge and an arrangement, ala al-ilmi wa al-tadbir, of exactly the kind the senses could take in.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'and they point only to their like mercy was seen in some creature and so the word merciful was lifted and laid upon that creature the attribute fell upon its like upon a knowledge and an arrangement ala al ilmi wa al tadbir of exactly the kind the senses could take in', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 21, NULL, 'One step further on the names themselves, and the ground gives way. These names and attributes are muhdathah — originated, brought-into-being things. Everything turns on the distinction: muhdith is the one who originates; muhdath is the thing originated. The names are muhdath. They are made; they are not their own makers. And they are made by a very particular maker — by a human being. A human mouth pronounces a name, a human will assigns it. A person names a child; that person is the one who gave the name. These, then, are names given by human beings, muhdathah, brought into being by them. The crux follows:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'one step further on the names themselves and the ground gives way these names and attributes are muhdathah originated brought into being things everything turns on the distinction muhdith is the one who originates muhdath is the thing originated the names are muhdath they are made they are not their own makers and they are made by a very particular maker by a human being a human mouth pronounces a name a human will assigns it a person names a child that person is the one who gave the name these then are names given by human beings muhdathah brought into being by them the crux follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 22, NULL, 'Sayingوَالْمُحْدَثُ لَا يَقَعُ عَلَى الْمُحْدِثِ مِثْلُهُ"And the originated thing does not fall upon its originator as its like."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوالمحدث لا يقع علي المحدث مثله and the originated thing does not fall upon its originator as its like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 23, NULL, 'A made thing cannot land on its maker as though they were equals. The fashioned cannot characterize the Fashioner as though they shared a single kind. Sayyidna Muayyad al-Din said exactly this — no minor voice; he lived in the time of Mawlana Mustansir Billah and held the rank of Bab al-Abwab (بَابُ الْأَبْوَاب), the Gate of Gates:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'a made thing cannot land on its maker as though they were equals the fashioned cannot characterize the fashioner as though they shared a single kind sayyidna muayyad al din said exactly this no minor voice he lived in the time of mawlana mustansir billah and held the rank of bab al abwab باب الابواب the gate of gates', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 24, NULL, 'Sayingوَلَمَّا كَانَتِ الْحُرُوفُ الْمُعْجَمَةُ مُحْدَثَةً، لَمْ تَكُنْ تَدُلُّ عَلَى الْمُبْدِعِ الصَّانِعِ لَهَا دَلَالَةً مُحَقِّقَةً مُصَدِّقَةً عَلَىٰ مِثْلِهَا"And since the letters of the alphabet are originated things, they could not indicate the originating Maker who made them with a true and verifying indication upon His like."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingولما كانت الحروف المعجمه محدثه لم تكن تدل علي المبدع الصانع لها دلاله محققه مصدقه علي مثلها and since the letters of the alphabet are originated things they could not indicate the originating maker who made them with a true and verifying indication upon his like', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 25, NULL, 'The letters cannot turn around and truly point at the One who originated the letters.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the letters cannot turn around and truly point at the one who originated the letters', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 26, NULL, 'Here a fair objection rises, and the text does not dodge it. Someone will say: it is a clean argument that human beings make their own words — but they are limited creatures, and many things run on by His command long before any word leaves their mouths; are they really the makers of these things? The answer holds to the precise point in dispute. The words a person speaks now — these he does indeed make; of these spoken words, he is the maker. The whole argument rests on the small but real faculty of choice and making that human beings do possess. With their own handiwork — this tongue, these names that are theirs — they are trying to characterize their own Creator. That, and only that, is what cannot be done. The choice they have is genuine; it simply does not reach far enough to recognize Him. Human beings have no power of choice by which to know Him. He dwells in such a ghayb, such an unseen, that its curtains cannot so much as be lifted. Only this can be said: to establish that they themselves exist, human beings affirm that there must be an Originator for them. Who He is, what He is — that stays on the other side of the veil.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'here a fair objection rises and the text does not dodge it someone will say it is a clean argument that human beings make their own words but they are limited creatures and many things run on by his command long before any word leaves their mouths are they really the makers of these things the answer holds to the precise point in dispute the words a person speaks now these he does indeed make of these spoken words he is the maker the whole argument rests on the small but real faculty of choice and making that human beings do possess with their own handiwork this tongue these names that are theirs they are trying to characterize their own creator that and only that is what cannot be done the choice they have is genuine it simply does not reach far enough to recognize him human beings have no power of choice by which to know him he dwells in such a ghayb such an unseen that its curtains cannot so much as be lifted only this can be said to establish that they themselves exist human beings affirm that there must be an originator for them who he is what he is that stays on the other side of the veil', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 27, NULL, 'Then the question becomes unavoidable. If the names and the attributes do not fall on Allah, then upon what do they fall? The text answers:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'then the question becomes unavoidable if the names and the attributes do not fall on allah then upon what do they fall the text answers', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 28, NULL, 'Sayingوَإِذْ كَانَ الْقَوْلُ كَذَٰلِكَ، كَانَتْ هَذِهِ الْأَسْمَاءُ وَالصِّفَاتُ مَنْفِيَّةً عَنِ اللَّهِ تَعَالَىٰ وَتَكَبَّرَ، وَكَانَتْ وَاقِعَةً عَلَىٰ إِبْدَاعِهِ الَّذِي هُوَ الْعَقْلُ الْأَوَّلُ"And since the matter is thus, these names and attributes are negated from Allah, the Exalted and Supreme, and they fall instead upon His origination, which is the First Intellect."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingواذ كان القول كذلك كانت هذه الاسماء والصفات منفيه عن الله تعالي وتكبر وكانت واقعه علي ابداعه الذي هو العقل الاول and since the matter is thus these names and attributes are negated from allah the exalted and supreme and they fall instead upon his origination which is the first intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 29, NULL, 'Every one of these names, every attribute, is manfiyyah — negated, lifted off — from Allah Taala. None is predicated of Him at all. They come to rest instead on His ibda (إبداع), His origination. And that origination is the aql al-awwal, the First Intellect, which carries other names too: the mawjud al-awwal, the first existent, and the sadir al-awwal, the first thing to issue forth. The image is of a sealed letter passing through several hands before it reaches the one to whom it is addressed: the names and attributes are delivered as far as this first recipient and no further — negated from Allah and descending upon this first origination, this First Intellect that is at once the first to exist and the first to emanate.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'every one of these names every attribute is manfiyyah negated lifted off from allah taala none is predicated of him at all they come to rest instead on his ibda ابداع his origination and that origination is the aql al awwal the first intellect which carries other names too the mawjud al awwal the first existent and the sadir al awwal the first thing to issue forth the image is of a sealed letter passing through several hands before it reaches the one to whom it is addressed the names and attributes are delivered as far as this first recipient and no further negated from allah and descending upon this first origination this first intellect that is at once the first to exist and the first to emanate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 30, NULL, 'The text drives the blade further:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the text drives the blade further', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 31, NULL, 'Sayingوَمَا ظَهَرَ مِنْ فِعْلِهِ فِي اخْتِرَاعِهِ، لَا مِنْ جِهَةِ اسْمٍ وَلَا صِفَةٍ يَخْتَرِعَانِ عَلَيْهِ، لِأَنَّ ذَٰلِكَ مَسْلُوبٌ عَنْهُ، وَاقِعٌ عَلَىٰ إِبْدَاعِهِ"And what appeared from His act in His creation — not from the aspect of any name or attribute that would be applied specifically to Him — for that is stripped from Him, and falls rather upon His origination."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوما ظهر من فعله في اختراعه لا من جهه اسم ولا صفه يخترعان عليه لان ذلك مسلوب عنه واقع علي ابداعه and what appeared from his act in his creation not from the aspect of any name or attribute that would be applied specifically to him for that is stripped from him and falls rather upon his origination', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 32, NULL, 'All that can ever be spoken of is what appeared from His act in His creating — never a name or an attribute pinned directly onto Him. Every such predication is maslub: stripped off, severed clean away from Him. The names applied fall upon what He created, upon His ibda. And here the matter grows subtler still, and the subtlety cuts deep: if these names and attributes do not even rest fully upon His origination, how could they ever rest upon Allah, the Mubdi Most High?', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'all that can ever be spoken of is what appeared from his act in his creating never a name or an attribute pinned directly onto him every such predication is maslub stripped off severed clean away from him the names applied fall upon what he created upon his ibda and here the matter grows subtler still and the subtlety cuts deep if these names and attributes do not even rest fully upon his origination how could they ever rest upon allah the mubdi most high', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 33, NULL, 'The teaching now opens its arms to the whole of creation and gathers all of it into a single incapacity:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the teaching now opens its arms to the whole of creation and gathers all of it into a single incapacity', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 34, NULL, 'Sayingوَالْعَجْزُ شَامِلٌ لِجَمِيعِ عَالَمِ الْعَقْلِ وَعَالَمِ الْحِسِّ"And inadequacy is comprehensive over the entire world of intellect and the world of sense."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوالعجز شامل لجميع عالم العقل وعالم الحس and inadequacy is comprehensive over the entire world of intellect and the world of sense', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 35, NULL, 'Ijz — inadequacy, the sheer inability to know the Originator — is comprehensive. It covers everything, taking in the alam al-aql, the world of intellect, and the alam al-hiss, the world of the senses, both together. The First Intellect itself — the highest of all created things — shares in this incapacity, and so does the lowest creature. In this one thing all stand level. As the text says:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'ijz inadequacy the sheer inability to know the originator is comprehensive it covers everything taking in the alam al aql the world of intellect and the alam al hiss the world of the senses both together the first intellect itself the highest of all created things shares in this incapacity and so does the lowest creature in this one thing all stand level as the text says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 36, NULL, 'Sayingيَتَسَاوَىٰ فِي ذَٰلِكَ الْقَادِرُ وَالْمَقْدُورُ وَالْمَحْسُوسُ وَالْمَعْقُولُ مِنَ الْعَالَمَيْنِ جَمِيعًا"In that, they are equal — the powerful and the overpowered, the sensed and the intelligible, from both worlds together."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingيتساوي في ذلك القادر والمقدور والمحسوس والمعقول من العالمين جميعا in that they are equal the powerful and the overpowered the sensed and the intelligible from both worlds together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 37, NULL, 'The verb is yatasawa, from sawa, equal, in the form that carries mutual leveling: it declares them all equal to one another in this single respect. The powerful and the powerless, the sensed thing and the thing grasped by intellect, the world of mind and the world of body — every one of them stands on perfectly flat ground before the unknowability of the Originator. No one is closer than another. No rank lifts its bearer one inch nearer to comprehending Him.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the verb is yatasawa from sawa equal in the form that carries mutual leveling it declares them all equal to one another in this single respect the powerful and the powerless the sensed thing and the thing grasped by intellect the world of mind and the world of body every one of them stands on perfectly flat ground before the unknowability of the originator no one is closer than another no rank lifts its bearer one inch nearer to comprehending him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 38, NULL, 'What, then, happens when the word "Allah" is said? The text gives an answer of startling depth:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'what then happens when the word allah is said the text gives an answer of startling depth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 39, NULL, 'Sayingوَقَوْلُنَا اللَّهُ إِعْرَابٌ بِهَذَا الِاسْمِ لِإِلْهَانِ الْعَقْلِ الْأَوَّلِ"And our saying Allah is an expression by this name on account of the bewilderment of the First Intellect."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوقولنا الله اعراب بهذا الاسم لالهان العقل الاول and our saying allah is an expression by this name on account of the bewilderment of the first intellect', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 40, NULL, 'The saying of "Allah" — the reaching for Him through this name — rises out of ilhan, bewilderment, walah, the stunned standing-still of the First Intellect before the Originator. The Intellect is bewildered before Him, and out of that bewilderment the word "Allah" breaks from it. And in this, once more, everyone is equal. The Imam is equal in it; the ardent lover, the ashiq, is equal in it. Whoever stands bewildered before Him reaches for the same word: "Allah."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the saying of allah the reaching for him through this name rises out of ilhan bewilderment walah the stunned standing still of the first intellect before the originator the intellect is bewildered before him and out of that bewilderment the word allah breaks from it and in this once more everyone is equal the imam is equal in it the ardent lover the ashiq is equal in it whoever stands bewildered before him reaches for the same word allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 41, NULL, 'The image the matter itself reaches for is the circle. Allah is the markaz, the center, the single central point; and around that center the bewildered circle turns. The circle turns because it is bewildered about its center. One circle revolves around its center in bewilderment. Then another circle comes, bewildered about its own center, and it too revolves. Every circle turns around its center, and the reason for the turning is always the one same reason: bewilderment. The very energy by which a circle goes round is, in truth, nothing but its perplexity. The whole created order wheels eternally about a center it cannot comprehend, and the motion of that wheeling is the unceasing bewilderment of the creature before the One who made it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the image the matter itself reaches for is the circle allah is the markaz the center the single central point and around that center the bewildered circle turns the circle turns because it is bewildered about its center one circle revolves around its center in bewilderment then another circle comes bewildered about its own center and it too revolves every circle turns around its center and the reason for the turning is always the one same reason bewilderment the very energy by which a circle goes round is in truth nothing but its perplexity the whole created order wheels eternally about a center it cannot comprehend and the motion of that wheeling is the unceasing bewilderment of the creature before the one who made it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 42, NULL, 'The text now recounts the first act of all — the primal moment in which the First Intellect first denied divinity, then affirmed it:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the text now recounts the first act of all the primal moment in which the first intellect first denied divinity then affirmed it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 43, NULL, 'Sayingوَقَوْلُنَا الْهُوِيَّةُ الْمُتَعَالِيَةُ: لَمَّا نَفَىٰ عَنْهُ وَعَنْ أَبْنَاءِ جِنْسِهِ الْإِلَٰهِيَّةَ، وَأَثْبَتَهَا لَهُ تَعَالَىٰ وَتَكَبَّرَ، كَمَا أَخْبَرَ عَنْهُ الْكِتَابُ الْكَرِيمُ بِقَوْلِهِ: شَهِدَ اللَّهُ أَنَّهُ لَا إِلَٰهَ إِلَّا هُوَ"And our saying the exalted Ipseity — when he negated from himself and from the members of his genus the divinity, and affirmed it for Him, the Exalted and Supreme, as the Noble Book informed concerning him in His saying: Allah testifies that there is no god but He."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوقولنا الهويه المتعاليه لما نفي عنه وعن ابناء جنسه الالهيه واثبتها له تعالي وتكبر كما اخبر عنه الكتاب الكريم بقوله شهد الله انه لا اله الا هو and our saying the exalted ipseity when he negated from himself and from the members of his genus the divinity and affirmed it for him the exalted and supreme as the noble book informed concerning him in his saying allah testifies that there is no god but he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 44, NULL, 'The First Intellect did this. Contemplating the Originator, it first performed a negation, declaring in effect that it was not the maker of itself. It pronounced la ilaha — there is no god — and pushed divinity away from itself: it had no power to create itself, nor did its genus, the whole order of beings like it, have any power to create. It stripped al-ilahiyyah, divinity, off itself and off its own kind. And then it affirmed that divinity for Allah Taala alone — illa Hu, except He.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the first intellect did this contemplating the originator it first performed a negation declaring in effect that it was not the maker of itself it pronounced la ilaha there is no god and pushed divinity away from itself it had no power to create itself nor did its genus the whole order of beings like it have any power to create it stripped al ilahiyyah divinity off itself and off its own kind and then it affirmed that divinity for allah taala alone illa hu except he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 45, NULL, 'This is the very pattern the Noble Book has set down:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'this is the very pattern the noble book has set down', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 46, NULL, 'شَهِدَ اللَّهُ أَنَّهُ لَا إِلَٰهَ إِلَّا هُوَ"Allah testifies that there is no god but He."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'شهد الله انه لا اله الا هو allah testifies that there is no god but he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 47, NULL, 'The deep sense is this: the "Allah" who testifies in this verse is the First Intellect. It is the First Intellect that bears witness annahu la ilaha illa Hu — that there is no god but He, the Mubdi Most High. The First Intellect, and with it the entire order of created being, first confessed that it could not create itself or its kind, and then pointed past itself with illa Hu — He alone — toward the Originator, who can be indicated by nothing more than the bare pronoun "He."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the deep sense is this the allah who testifies in this verse is the first intellect it is the first intellect that bears witness annahu la ilaha illa hu that there is no god but he the mubdi most high the first intellect and with it the entire order of created being first confessed that it could not create itself or its kind and then pointed past itself with illa hu he alone toward the originator who can be indicated by nothing more than the bare pronoun he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 48, NULL, 'The text closes the thought:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the text closes the thought', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 49, NULL, 'Sayingوَلَيْسَ يَقَعُ عَلَيْهِ شَيْءٌ مِنْ ذَٰلِكَ إِلَّا كَبِيرًا مِنْ قَوْلِهِ هُوَ، وَسَنُبَيِّنُ حَقِيقَةَ ذَٰلِكَ إِنْ شَاءَ اللَّهُ تَعَالَىٰ"And nothing of that falls upon Him save, perhaps, His saying He — and we shall clarify the reality of that matter, if Allah the Exalted wills."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingوليس يقع عليه شيء من ذلك الا كبيرا من قوله هو وسنبين حقيقه ذلك ان شاء الله تعالي and nothing of that falls upon him save perhaps his saying he and we shall clarify the reality of that matter if allah the exalted wills', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 50, NULL, 'Sayingفَأَعْرَبَ عَنْهُ بِمَا كَانَ مِنْ صِفَةِ إِبْدَاعِهِ وَفِعْلِهِ"So he expressed about Him by what belonged to the attributes of His origination and His act."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'sayingفاعرب عنه بما كان من صفه ابداعه وفعله so he expressed about him by what belonged to the attributes of his origination and his act', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 51, NULL, 'The Intellect could express Him only through what showed itself in the origination, saying, in effect, that He had created and fashioned it so. The creature cannot praise the Creator as He deserves, not knowing Him. But from the plain fact of its own existence, from the very manner in which He shaped it, the creature can say something true: He gave it life, He gave it knowledge, He gave it power. That much may be said, because that much the creature itself holds and knows. But the true tamjid, the real glorification, the highest praise that would actually befit Him — that lies past its reach entirely. The very highest word that can be lifted toward Him is "Allah," and one step above that, "Huwa" — He. Beyond those two words nothing remains in human hands with which to interpret Him.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'the intellect could express him only through what showed itself in the origination saying in effect that he had created and fashioned it so the creature cannot praise the creator as he deserves not knowing him but from the plain fact of its own existence from the very manner in which he shaped it the creature can say something true he gave it life he gave it knowledge he gave it power that much may be said because that much the creature itself holds and knows but the true tamjid the real glorification the highest praise that would actually befit him that lies past its reach entirely the very highest word that can be lifted toward him is allah and one step above that huwa he beyond those two words nothing remains in human hands with which to interpret him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the god no pointing can reach', '2. The God No Pointing Can Reach', 52, NULL, 'So the seeking treated earlier, and the holding fast to the Imams, now have their true horizon in view. The whole endeavor has strained toward a center that no eye reaches, no name lands on, no thought bridges — One whom even the First Intellect could only stand bewildered before and confess with a single pronoun. The word "He" has been left standing alone at the end, deliberately, like a door not yet opened. The text has promised to clarify its reality — and that bare "Huwa," that last and highest thing the tongue can say, is exactly where the matter goes next.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 2 the god no pointing can reach', 'so the seeking treated earlier and the holding fast to the imams now have their true horizon in view the whole endeavor has strained toward a center that no eye reaches no name lands on no thought bridges one whom even the first intellect could only stand bewildered before and confess with a single pronoun the word he has been left standing alone at the end deliberately like a door not yet opened the text has promised to clarify its reality and that bare huwa that last and highest thing the tongue can say is exactly where the matter goes next', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 0, NULL, 'فَوَقَعَ لِنُوقِعَ عَلَى الْهُوِيَّةِ الْمُتَعَالِيَةِ لِعَجْزِنَا وَضِيقِ جَوْهَرِنَا وَحَصْرِنَا وَقُصُورِنَا', '', 'فَوَقَعَ لِنُوقِعَ عَلَى الْهُوِيَّةِ الْمُتَعَالِيَةِ لِعَجْزِنَا وَضِيقِ جَوْهَرِنَا وَحَصْرِنَا وَقُصُورِنَا', NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'فوقع لنوقع علي الهويه المتعاليه لعجزنا وضيق جوهرنا وحصرنا وقصورنا', 'فوقع لنوقع علي الهويه المتعاليه لعجزنا وضيق جوهرنا وحصرنا وقصورنا');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 1, NULL, '"And so it came about that we should let the name fall upon the exalted Ipseity — because of our inadequacy, the narrowness of our essence, our confinement, and our deficiency."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'and so it came about that we should let the name fall upon the exalted ipseity because of our inadequacy the narrowness of our essence our confinement and our deficiency', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 2, NULL, 'At the bare "He," a sharp question waits. If no name lands on Him, why name Him at all? Why reach for words already known to miss?', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'at the bare he a sharp question waits if no name lands on him why name him at all why reach for words already known to miss', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 3, NULL, 'The answer is not flattering, and it is not meant to be. He is named out of poverty. That last word — He, the Ipseity, the huwiyyah — is let fall upon Him not because it fits, but because there is nothing left. The reasons the text gives stand one beside the next. There is our ijz, our sheer inadequacy, the inability of a created thing to hold its Creator in thought. There is the diq, the narrowness, of our jawhar (الْجَوْهَر) — and jawhar here is the very substance of us, the essence out of which our speech and our articulation, our nutq, are made. The instrument we would measure Him with is too small for the measuring. Our hiss, our faculty of sense, is hemmed in on every side. We are deficient, and we are constrained, and the name laid upon Him is simply the last syllable our minds can reach before the ground gives out. Beyond it there is nothing further to say. The naming is not a triumph of language. It is the sound a confined creature makes at the edge of its confinement.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'the answer is not flattering and it is not meant to be he is named out of poverty that last word he the ipseity the huwiyyah is let fall upon him not because it fits but because there is nothing left the reasons the text gives stand one beside the next there is our ijz our sheer inadequacy the inability of a created thing to hold its creator in thought there is the diq the narrowness of our jawhar الجوهر and jawhar here is the very substance of us the essence out of which our speech and our articulation our nutq are made the instrument we would measure him with is too small for the measuring our hiss our faculty of sense is hemmed in on every side we are deficient and we are constrained and the name laid upon him is simply the last syllable our minds can reach before the ground gives out beyond it there is nothing further to say the naming is not a triumph of language it is the sound a confined creature makes at the edge of its confinement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 4, NULL, 'The precision of this turns on a distinction between what was given and what was not. The created intellects — the high spiritual realities through which everything descends — were given ilm al-kulli, total knowledge. That phrase can mislead. Total knowledge does not mean knowledge of God. It means, as Sayyidna Muayyad explains, ilm al-hayat, the knowledge of life: a complete grasp of what powers and faculties live inside life itself. He sets them out plainly — hayat, life; ilm, knowledge; quwwah, power; ikhtiyar (اَلْاِخْتِيَار), choice — and then expounds each one at length, what life is, what knowledge is, what power is, what choice is. The intellects know all of that, top to bottom, with nothing left over. But the knowledge by which one would know Allah was never handed to them. It was withheld. It was withheld because it cannot even be comprehended — there is no faculty into which it could be poured. The image is of a house whose every room one has walked, whose wiring and beams and foundations one could draw from memory; the structure of the dwelling is known entirely, and still the One who built it has never been met. That is the position of the created intellects. They know the architecture of life in its fullness. The essence of the One who gave the life stays sealed.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'the precision of this turns on a distinction between what was given and what was not the created intellects the high spiritual realities through which everything descends were given ilm al kulli total knowledge that phrase can mislead total knowledge does not mean knowledge of god it means as sayyidna muayyad explains ilm al hayat the knowledge of life a complete grasp of what powers and faculties live inside life itself he sets them out plainly hayat life ilm knowledge quwwah power ikhtiyar الاختيار choice and then expounds each one at length what life is what knowledge is what power is what choice is the intellects know all of that top to bottom with nothing left over but the knowledge by which one would know allah was never handed to them it was withheld it was withheld because it cannot even be comprehended there is no faculty into which it could be poured the image is of a house whose every room one has walked whose wiring and beams and foundations one could draw from memory the structure of the dwelling is known entirely and still the one who built it has never been met that is the position of the created intellects they know the architecture of life in its fullness the essence of the one who gave the life stays sealed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 5, NULL, 'There is a companion teaching from Sayyidna Muayyad here, about the permanence of what Allah bestows. Once He has given existence, He does not take it back. A man who gives a thing to another does not afterward snatch it out of his hands; and so too, having granted existence, Allah does not withdraw it. This sounds at first like a gentle observation. It opens, in fact, onto a hard question about divine power — the kind of question raised to corner a believer.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'there is a companion teaching from sayyidna muayyad here about the permanence of what allah bestows once he has given existence he does not take it back a man who gives a thing to another does not afterward snatch it out of his hands and so too having granted existence allah does not withdraw it this sounds at first like a gentle observation it opens in fact onto a hard question about divine power the kind of question raised to corner a believer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 6, NULL, 'There was once a debate between an Arya Samaji and the Muslims, and the man set his trap carefully. "Your Allah can do everything?" he asked. The Muslims said, "Yes." "Then can He do zulm, injustice? If He can do all things, He can do injustice too. And if you say He cannot, then you have just put a limit on His power." It is a clever knot. The Muslims did not argue it; they answered it with a question of their own. "Can you eat everything? You have the power to eat — so eat this filth set before you." The man could not, of course. Possessing the capacity to eat lays no obligation on one to swallow what is vile. Capacity is one thing; the swallowing is another. In just the same way, Allah is capable of all things, and He does not do injustice — and His not doing it takes nothing away from His power. It is not a wall around His ability. It is the perfection of His justice. He can do everything, and He does not do wrong, and He does not reclaim the existence He has given. The two hold together: total capacity, and a will that does no injustice. They do not contradict.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'there was once a debate between an arya samaji and the muslims and the man set his trap carefully your allah can do everything he asked the muslims said yes then can he do zulm injustice if he can do all things he can do injustice too and if you say he cannot then you have just put a limit on his power it is a clever knot the muslims did not argue it they answered it with a question of their own can you eat everything you have the power to eat so eat this filth set before you the man could not of course possessing the capacity to eat lays no obligation on one to swallow what is vile capacity is one thing the swallowing is another in just the same way allah is capable of all things and he does not do injustice and his not doing it takes nothing away from his power it is not a wall around his ability it is the perfection of his justice he can do everything and he does not do wrong and he does not reclaim the existence he has given the two hold together total capacity and a will that does no injustice they do not contradict', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 7, NULL, 'A prayer now exposes a paradox sitting at the root of all this naming. Sayyidna Muayyad — here meaning Hibatullah ibn Musa al-Shirazi, the spiritual son of Mawlana Sayyidna Muayyad al-Din, the author of the Mabda wa Maad — says in some of his words:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'a prayer now exposes a paradox sitting at the root of all this naming sayyidna muayyad here meaning hibatullah ibn musa al shirazi the spiritual son of mawlana sayyidna muayyad al din the author of the mabda wa maad says in some of his words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 8, NULL, 'اللَّهُمَّ يَا مَنْ وَقَعَ اعْتِرَافُنَا بِصِدْقِ مَا قَالَهُ فِي حَكِيمِ ذِكْرِهِ، إِذْ يَقُولُ وَقَوْلُهُ الْحَقُّ: وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ', '', 'اللَّهُمَّ يَا مَنْ وَقَعَ اعْتِرَافُنَا بِصِدْقِ مَا قَالَهُ فِي حَكِيمِ ذِكْرِهِ، إِذْ يَقُولُ وَقَوْلُهُ الْحَقُّ وَمَا قَدَرُوا اللَّهَ حَقَّ قَدْرِهِ', NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'اللهم يا من وقع اعترافنا بصدق ما قاله في حكيم ذكره اذ يقول وقوله الحق وما قدروا الله حق قدره', 'اللهم يا من وقع اعترافنا بصدق ما قاله في حكيم ذكره اذ يقول وقوله الحق وما قدروا الله حق قدره');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 9, NULL, '"O Allah, O You to whom our confession is rendered, attesting the truth of what He said in His wise remembrance, when He says — and His word is the truth — And they have not appraised Allah with His true appraisal."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'o allah o you to whom our confession is rendered attesting the truth of what he said in his wise remembrance when he says and his word is the truth and they have not appraised allah with his true appraisal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 10, NULL, 'What is confessed here is the truth of His own verdict on us: that they have not measured the worth of Allah with His true worth. We cannot appraise Him as He deserves, and we never will, because we do not know Him. The most we can say is what we say from inside our own existence — that, judging by the goodness of what we ourselves are, He has made something good. That is the ceiling of our praise. It is a praise of the gift, offered by someone who has never seen the Giver.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'what is confessed here is the truth of his own verdict on us that they have not measured the worth of allah with his true worth we cannot appraise him as he deserves and we never will because we do not know him the most we can say is what we say from inside our own existence that judging by the goodness of what we ourselves are he has made something good that is the ceiling of our praise it is a praise of the gift offered by someone who has never seen the giver', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 11, NULL, 'And so the prayer turns, in the same breath, to asking pardon:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'and so the prayer turns in the same breath to asking pardon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 12, NULL, 'إِنَّا نَسْأَلُكَ الْمُسَامَحَةَ لِمَنْ هُوَ مِنْ رِبْقِ الْعُبُودِيَّةِ فِي مَضِيقِ الْحِصَارِ وَالتَّضْيِيقِ، إِذَا أَرَدْنَا تَنَاوُلَ ذِكْرِكَ بِغَيْرِ مَا أَنْتَ أَهْلُهُ', '', 'إِنَّا نَسْأَلُكَ الْمُسَامَحَةَ لِمَنْ هُوَ مِنْ رِبْقِ الْعُبُودِيَّةِ فِي مَضِيقِ الْحِصَارِ وَالتَّضْيِيقِ، إِذَا أَرَدْنَا تَنَاوُلَ ذِكْرِكَ بِغَيْرِ مَا أَنْتَ أَهْلُهُ', NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'انا نسالك المسامحه لمن هو من ربق العبوديه في مضيق الحصار والتضييق اذا اردنا تناول ذكرك بغير ما انت اهله', 'انا نسالك المسامحه لمن هو من ربق العبوديه في مضيق الحصار والتضييق اذا اردنا تناول ذكرك بغير ما انت اهله');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 13, NULL, '"Indeed we ask You for forbearance toward one who is in the noose of servitude, in the narrow straits of confinement and constraint, when we set ourselves to undertake Your remembrance by that which You are not worthy of."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'indeed we ask you for forbearance toward one who is in the noose of servitude in the narrow straits of confinement and constraint when we set ourselves to undertake your remembrance by that which you are not worthy of', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 14, NULL, 'We are asking for musamahah — forbearance, pardon; the word comes from samaha, to forgive. And for whom is it asked? For the one caught in the rubq, the snare, of servitude, of ubudiyyah. We are bound servants, drawn tight in the noose of our own creaturehood, hemmed in by the narrow straits of confinement — hisar — with limits set around us that we cannot step past. And when we rise to undertake His remembrance, we are forced to do it by means unworthy of Him, because the only means worthy of Him is the one we cannot reach. We say as much as our strength allows. And exactly where our strength fails and the words fall short of Him, there we ask His pardon.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'we are asking for musamahah forbearance pardon the word comes from samaha to forgive and for whom is it asked for the one caught in the rubq the snare of servitude of ubudiyyah we are bound servants drawn tight in the noose of our own creaturehood hemmed in by the narrow straits of confinement hisar with limits set around us that we cannot step past and when we rise to undertake his remembrance we are forced to do it by means unworthy of him because the only means worthy of him is the one we cannot reach we say as much as our strength allows and exactly where our strength fails and the words fall short of him there we ask his pardon', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 15, NULL, 'The prayer then gives the reason the pardon is needed, and it gives it without softening:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'the prayer then gives the reason the pardon is needed and it gives it without softening', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 16, NULL, 'لِأَنَّ تَنَاوُلَ ذِكْرِكَ بِغَيْرِ مَا أَنْتَ أَهْلُهُ بِحُكْمِ الِاضْطِرَارِ فَإِنَّمَا هُوَ ذَنْبٌ مَشْفُوعٌ بِالِاسْتِغْفَارِ', '', 'لِأَنَّ تَنَاوُلَ ذِكْرِكَ بِغَيْرِ مَا أَنْتَ أَهْلُهُ بِحُكْمِ الِاضْطِرَارِ فَإِنَّمَا هُوَ ذَنْبٌ مَشْفُوعٌ بِالِاسْتِغْفَارِ', NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'لان تناول ذكرك بغير ما انت اهله بحكم الاضطرار فانما هو ذنب مشفوع بالاستغفار', 'لان تناول ذكرك بغير ما انت اهله بحكم الاضطرار فانما هو ذنب مشفوع بالاستغفار');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 17, NULL, '"Because to undertake Your remembrance by that which You are not worthy of, under the rule of compulsion, is only a sin coupled with the seeking of forgiveness."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'because to undertake your remembrance by that which you are not worthy of under the rule of compulsion is only a sin coupled with the seeking of forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 18, NULL, 'The phrase is built with care. To take up His remembrance with our inadequate words is done bi-hukmi al-idtirar — by the rule of compulsion, of necessity. We are compelled. Out of idtirar we have no other word to offer, so we offer the only one we have. And therefore the act is dhanbun mashfuun bi-al-istighfar — a sin coupled with the seeking of forgiveness. This is a term the دُعَاة established with precision: a dhanb, a sin, that is mashfu — paired, joined — with istighfar (اِسْتِغْفَار), the asking of pardon. The word mashfu is from shafaa, to make a pair. So this is a sin that never travels alone. It comes already wedded to the plea for forgiveness, and because it arose out of compulsion, it is accepted — for compulsion is excusable. There is no arrogance in it. There is the utmost humility in it, the humility of a creature who speaks of his Lord knowing every word is too small, and asks pardon for the smallness in the very act of speaking.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'the phrase is built with care to take up his remembrance with our inadequate words is done bi hukmi al idtirar by the rule of compulsion of necessity we are compelled out of idtirar we have no other word to offer so we offer the only one we have and therefore the act is dhanbun mashfuun bi al istighfar a sin coupled with the seeking of forgiveness this is a term the دعاه established with precision a dhanb a sin that is mashfu paired joined with istighfar استغفار the asking of pardon the word mashfu is from shafaa to make a pair so this is a sin that never travels alone it comes already wedded to the plea for forgiveness and because it arose out of compulsion it is accepted for compulsion is excusable there is no arrogance in it there is the utmost humility in it the humility of a creature who speaks of his lord knowing every word is too small and asks pardon for the smallness in the very act of speaking', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 19, NULL, 'Care is needed on one further point: this does not apply to the physical world alone. It applies to every world equally. The istighfar is required of all — and the First Intellect, the Mubda al-Awwal itself, is included with everyone else. The claim is arresting. The First Intellect committed no transgression; there is no moral crime here. So the "sin" cannot be a sin in the ordinary sense. Rather — even the First Intellect''s own act carries this character within it. When it says that You are the Mubdi (المُبدِع), the Originator, Most High; when it bears its witness —', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'care is needed on one further point this does not apply to the physical world alone it applies to every world equally the istighfar is required of all and the first intellect the mubda al awwal itself is included with everyone else the claim is arresting the first intellect committed no transgression there is no moral crime here so the sin cannot be a sin in the ordinary sense rather even the first intellects own act carries this character within it when it says that you are the mubdi المبدع the originator most high when it bears its witness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'verse', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 20, NULL, 'شَهِدَ اللَّهُ أَنَّهُ لَا إِلَٰهَ إِلَّا هُوَ', '', 'شَهِدَ اللَّهُ أَنَّهُ لَا إِلَٰهَ إِلَّا هُوَ', NULL, 3, 18, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'شهد الله انه لا اله الا هو', 'شهد الله انه لا اله الا هو');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 21, NULL, '"Allah bears witness that there is no god but He" —', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'allah bears witness that there is no god but he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 22, NULL, 'and indicates Him by nothing more than illa Huwa, by the bare pronoun He, because there is simply nothing beyond that to point with — even this, the highest utterance in all of creation, falls short of His true majesty. And because it falls short, it too is coupled with istighfar. From the First Intellect down to the tenth, not one of them can do a hair more than this. All are compelled. All stand equal before the Creator, the Originator, whom none of them can recognize. The rank does not change the position. The first intellect and the tenth are level on this single point: the One above them is unknowable to every one of them.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'and indicates him by nothing more than illa huwa by the bare pronoun he because there is simply nothing beyond that to point with even this the highest utterance in all of creation falls short of his true majesty and because it falls short it too is coupled with istighfar from the first intellect down to the tenth not one of them can do a hair more than this all are compelled all stand equal before the creator the originator whom none of them can recognize the rank does not change the position the first intellect and the tenth are level on this single point the one above them is unknowable to every one of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 23, NULL, 'How compulsion changes the weight of an act appears in a case judged in the time of Umar. A woman was brought before him carrying a child, and she said she had no husband. Asked how this had happened, she told them: she had been crossing the desert, dying of thirst, three days without water, when she came upon a shepherd. He said he would give her water on one condition — that she give herself to him. At the edge of death, for the sake of the water, she yielded; and afterward she bore the child. Umar said, "Stone her." A child, no marriage, no husband. But the Mawla of all creation, Imam Ali, arrived and asked what the matter was, and when he heard it he said: "She is mustarr — compelled, helpless. Let her go. This happened under idtirar, under compulsion." Idtirar is helplessness itself, and where there is true helplessness the act does not carry the full weight of a sin.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'how compulsion changes the weight of an act appears in a case judged in the time of umar a woman was brought before him carrying a child and she said she had no husband asked how this had happened she told them she had been crossing the desert dying of thirst three days without water when she came upon a shepherd he said he would give her water on one condition that she give herself to him at the edge of death for the sake of the water she yielded and afterward she bore the child umar said stone her a child no marriage no husband but the mawla of all creation imam ali arrived and asked what the matter was and when he heard it he said she is mustarr compelled helpless let her go this happened under idtirar under compulsion idtirar is helplessness itself and where there is true helplessness the act does not carry the full weight of a sin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 24, NULL, 'So it is with the soul that names the Unnameable. In its helplessness it sins, in a manner of speaking, by speaking inadequately of Him. But because it is compelled, that sin comes paired with the asking of forgiveness, and it is excused. A strange paradox lingers — that even in the pure world of the spirits, where everything is illumined except His essence, there could be any possibility of "sin" at all. The paradox is resolved exactly in the coupling. Nothing more than this can be done. It is compulsion. And so neither the first intellect nor the tenth can do otherwise; and in the matter of the Creator, the Originator, every one of them is equal, because not one of them can recognize Him.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'so it is with the soul that names the unnameable in its helplessness it sins in a manner of speaking by speaking inadequately of him but because it is compelled that sin comes paired with the asking of forgiveness and it is excused a strange paradox lingers that even in the pure world of the spirits where everything is illumined except his essence there could be any possibility of sin at all the paradox is resolved exactly in the coupling nothing more than this can be done it is compulsion and so neither the first intellect nor the tenth can do otherwise and in the matter of the creator the originator every one of them is equal because not one of them can recognize him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 25, NULL, 'The ladder itself now stands out — the maratib, the ascending ranks of spirituality through which the soul mounts toward its origin. The way the channel of a river is cut before any water can run through it, these ranks are the channel of the ascent. The lowest of those named is the Imamate of spirituality, the rank of Rutbat al-Ilahiyyah in its rising order; and from there the stations climb in sequence — حُجِّيَّة, then حِجَابِيَّة, then خَيَالِيَّة, then فَتْحِيَّة, then جِدِّيَّة, then أَنْزَعِيَّة, then قَائِمِيَّة, then جُسِّيَّة, then أَحَدِيَّة, then صَمَدِيَّة — and so up to إِلَهِيَّة, and at the very top, هُوِيَّة. The last and highest rank is the Ipseity, the rank of the bare "He." Ten ranks in all are set out this way, ascending from the Imamate of spirituality up to the Ipseity, mapping the whole ladder of stations by which the soul climbs back toward where it came from.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'the ladder itself now stands out the maratib the ascending ranks of spirituality through which the soul mounts toward its origin the way the channel of a river is cut before any water can run through it these ranks are the channel of the ascent the lowest of those named is the imamate of spirituality the rank of rutbat al ilahiyyah in its rising order and from there the stations climb in sequence حجيه then حجابيه then خياليه then فتحيه then جديه then انزعيه then قايميه then جسيه then احديه then صمديه and so up to الهيه and at the very top هويه the last and highest rank is the ipseity the rank of the bare he ten ranks in all are set out this way ascending from the imamate of spirituality up to the ipseity mapping the whole ladder of stations by which the soul climbs back toward where it came from', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 26, NULL, 'One thing remains, and it grows straight out of the word at the center of all this — mashfu, the "paired" or "coupled" sin. That word shafa, which means a pairing, carries among the دُعَاة a hidden referent, and so do its two companions, witr and julus. All three are borrowed from the language of prayer. The shafa prayer is the paired one, of two rakat (رَكْعَات). The witr is the single, odd rakat. The julus is the prayer of two rakat performed sitting. And each of these has its inner meaning, its taweel. The referent of shafa, the paired prayer, is the Prophet — peace and blessings be upon him — together with Lady Fatima, for they are the noble pair. The referent of witr, the single prayer, is Imam Ali, peace be upon him, the odd and singular one. And the referent of julus, the sitting prayer of two rakat, is Imam Hasan and Imam Husayn together. It is told that Imam Husayn himself, at Karbala, would name these very correspondences — that the referent of shafa is the Prophet, that the referent of witr was his own father, and so on — and the text affirms:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'one thing remains and it grows straight out of the word at the center of all this mashfu the paired or coupled sin that word shafa which means a pairing carries among the دعاه a hidden referent and so do its two companions witr and julus all three are borrowed from the language of prayer the shafa prayer is the paired one of two rakat ركعات the witr is the single odd rakat the julus is the prayer of two rakat performed sitting and each of these has its inner meaning its taweel the referent of shafa the paired prayer is the prophet peace and blessings be upon him together with lady fatima for they are the noble pair the referent of witr the single prayer is imam ali peace be upon him the odd and singular one and the referent of julus the sitting prayer of two rakat is imam hasan and imam husayn together it is told that imam husayn himself at karbala would name these very correspondences that the referent of shafa is the prophet that the referent of witr was his own father and so on and the text affirms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 27, NULL, 'وَتِلْكَ آيَةٌ وَاحِدَةٌ', '', 'وَتِلْكَ آيَةٌ وَاحِدَةٌ', NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'وتلك ايه واحده', 'وتلك ايه واحده');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 28, NULL, '"And these together are one sign."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'and these together are one sign', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the sin of naming the unnameable', '3. The Sin of Naming the Unnameable', 29, NULL, 'So the very terminology by which the دُعَاة name this "coupled sin" of inadequate speech opens, in its own turn, onto the hidden ranks of the Prophet and his pure household. The word reached for to confess our poverty before God turns out to carry, folded inside it, the names of the ones through whom He is approached. The matter does not rest here. What has been shown is this: why He is named and why the naming must be pardoned; the ladder climbed to its highest rung, with the bare "He" waiting at the top; and now this last word has handed over, almost unnoticed, the household by which the ascent is actually made. The pronoun pointed us upward. These names tell us by what hands the letter is carried.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 3 the sin of naming the unnameable', 'so the very terminology by which the دعاه name this coupled sin of inadequate speech opens in its own turn onto the hidden ranks of the prophet and his pure household the word reached for to confess our poverty before god turns out to carry folded inside it the names of the ones through whom he is approached the matter does not rest here what has been shown is this why he is named and why the naming must be pardoned the ladder climbed to its highest rung with the bare he waiting at the top and now this last word has handed over almost unnoticed the household by which the ascent is actually made the pronoun pointed us upward these names tell us by what hands the letter is carried', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 0, NULL, 'The realities this teaching unveils ascend by degrees, each standing a little higher than the one before. This matter opens with a saying handed down from the حُدُود, the ranks of the spiritual hierarchy, upon whom be peace:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the realities this teaching unveils ascend by degrees each standing a little higher than the one before this matter opens with a saying handed down from the حدود the ranks of the spiritual hierarchy upon whom be peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 1, NULL, 'Sayingإِنَّ التَّوْحِيدَ هُوَ مَعْرِفَةُ الْحُدُودِ، وَالتَّنْزِيهَ نَفْيُ الْإِلَهِيَّةِ عَنْهُمْ، وَالتَّجْرِيدَ سَلْبُ الْأَسْمَاءِ وَالصِّفَاتِ عَنِ اللَّهِ تَعَالَى"Verily, Tawhid is the gnosis of the ranks; and tanzih is the negation of divinity from them; and tajrid is the divestment of the names and attributes from God the Exalted."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'sayingان التوحيد هو معرفه الحدود والتنزيه نفي الالهيه عنهم والتجريد سلب الاسماء والصفات عن الله تعالي verily tawhid is the gnosis of the ranks and tanzih is the negation of divinity from them and tajrid is the divestment of the names and attributes from god the exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 2, NULL, 'And at once he adds that this is a summarized statement.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'and at once he adds that this is a summarized statement', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 3, NULL, 'Something is being corrected here, at the very floor of everything. Asked what Tawhid is, most answer almost before the question is finished: it means to consider God as one. But that is not what the حُدُود teach, and on reflection it cannot be. To count God as one is already to have placed Him under number — and whatever can be numbered as one can in principle be numbered as two, as three, or reckoned as a part of one. So to declare God "one" in that sense is not Tawhid at all. It is shirk (الشِّرْك), the gravest of all errors, because it lays a definition and a measure across the One who admits of no definition and no measure. He cannot be called one. He cannot be called two. He cannot be called three. He cannot be called a part of one. No number reaches Him. No boundary can be drawn around Him.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'something is being corrected here at the very floor of everything asked what tawhid is most answer almost before the question is finished it means to consider god as one but that is not what the حدود teach and on reflection it cannot be to count god as one is already to have placed him under number and whatever can be numbered as one can in principle be numbered as two as three or reckoned as a part of one so to declare god one in that sense is not tawhid at all it is shirk الشرك the gravest of all errors because it lays a definition and a measure across the one who admits of no definition and no measure he cannot be called one he cannot be called two he cannot be called three he cannot be called a part of one no number reaches him no boundary can be drawn around him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 4, NULL, 'What, then, is Tawhid? It is marifat al-hudud — the gnosis of the ranks. This is the cornerstone of the entire teaching. To affirm the divine unity is to recognize each had, each rank of the spiritual hierarchy, as utterly unique — yekta — in its own place. It is not to declare God unique. It is to know that every rank is unique in its proper station, and to attain the gnosis of exactly where that rank stands: at what level, in what station, in what relation to the ranks above it and below it. God is not the one being called unique here. Rather, every had is singular in its own place, and the gnosis of that singularity — of that whole ordered hierarchy of distinct ranks — is what the word Tawhid actually carries. This is the greatest thing a person can know: the Tawhid of the حُدُود, the recognition that every rank is singular and irreplaceable in its own degree.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'what then is tawhid it is marifat al hudud the gnosis of the ranks this is the cornerstone of the entire teaching to affirm the divine unity is to recognize each had each rank of the spiritual hierarchy as utterly unique yekta in its own place it is not to declare god unique it is to know that every rank is unique in its proper station and to attain the gnosis of exactly where that rank stands at what level in what station in what relation to the ranks above it and below it god is not the one being called unique here rather every had is singular in its own place and the gnosis of that singularity of that whole ordered hierarchy of distinct ranks is what the word tawhid actually carries this is the greatest thing a person can know the tawhid of the حدود the recognition that every rank is singular and irreplaceable in its own degree', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 5, NULL, 'These ranks did not drift into their positions by accident. God created the حُدُود and granted each of them authority — ikhtiyar — and said, in effect: use your powers. Each had, according to its own nature and likeness, was given a share of power and the freedom to exercise it. From the differences that grew out of how each one used that share, the whole arrangement, the tartib of the hierarchy, settled into place. It is the way the load-bearing walls of a building, once set, decide where every room and doorway can fall. To know that arrangement — to understand by what gradation one rank stands above or below another — is Tawhid. The hierarchy is not pressed down on the ranks from outside. It is the very expression of how each one used the authority entrusted to it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'these ranks did not drift into their positions by accident god created the حدود and granted each of them authority ikhtiyar and said in effect use your powers each had according to its own nature and likeness was given a share of power and the freedom to exercise it from the differences that grew out of how each one used that share the whole arrangement the tartib of the hierarchy settled into place it is the way the load bearing walls of a building once set decide where every room and doorway can fall to know that arrangement to understand by what gradation one rank stands above or below another is tawhid the hierarchy is not pressed down on the ranks from outside it is the very expression of how each one used the authority entrusted to it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 6, NULL, 'It follows that Tawhid has levels, because not everyone can take in the whole of it at once. The Prophet himself, peace and blessings upon him, pointed to this when he said:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'it follows that tawhid has levels because not everyone can take in the whole of it at once the prophet himself peace and blessings upon him pointed to this when he said', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 7, NULL, 'Sayingمَا عَرَفَنِي إِلَّا اللَّهُ وَأَنَا"None has known me except God, and I myself."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'sayingما عرفني الا الله وانا none has known me except god and i myself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 8, NULL, 'As a person''s own station — his martaba — rises, the depth of his Tawhid rises with it. There are many stations of Tawhid, each answering to the elevation of the one who knows. A question then opens: how many beings'' Tawhid can a single person actually perform across the whole span of a life? The answer is what fixes the rank of this science above every other. The knowledge of Tawhid is ajall al-ilm — the highest knowledge of all. To recognize the station of each and every rank, to know precisely where each one stands, is the most exalted of all knowing.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'as a persons own station his martaba rises the depth of his tawhid rises with it there are many stations of tawhid each answering to the elevation of the one who knows a question then opens how many beings tawhid can a single person actually perform across the whole span of a life the answer is what fixes the rank of this science above every other the knowledge of tawhid is ajall al ilm the highest knowledge of all to recognize the station of each and every rank to know precisely where each one stands is the most exalted of all knowing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 9, NULL, 'The reason it is the highest follows from how boundless its object is. The body offers a way in. Within it there are some three hundred and sixty parts, and each organ, each member, has its own quality and its own degree of excellence — one finer than another. To have full gnosis of the body would mean knowing each of these parts in its proper rank and worth. That same demand, lifted to the whole order of existence, is what the true Tawhid asks. Every being — every zawat — that God the Exalted created, and they are beyond counting, passed through its stages until it reached kamal-e insani, human perfection. The real marifat, the true Tawhid, is to know each of these beings: when and how it arrived at its human perfection, at what station it now stands, and how it stands in relation to all the rest. That is the very limit of gnosis. Because God created innumerable beings, the gnosis that answers to them is likewise innumerable, and the intellect is simply left staggered before the immensity of what there is to know. As much as one is able to attain, one attains — and no more.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the reason it is the highest follows from how boundless its object is the body offers a way in within it there are some three hundred and sixty parts and each organ each member has its own quality and its own degree of excellence one finer than another to have full gnosis of the body would mean knowing each of these parts in its proper rank and worth that same demand lifted to the whole order of existence is what the true tawhid asks every being every zawat that god the exalted created and they are beyond counting passed through its stages until it reached kamal e insani human perfection the real marifat the true tawhid is to know each of these beings when and how it arrived at its human perfection at what station it now stands and how it stands in relation to all the rest that is the very limit of gnosis because god created innumerable beings the gnosis that answers to them is likewise innumerable and the intellect is simply left staggered before the immensity of what there is to know as much as one is able to attain one attains and no more', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 10, NULL, 'Out of that immensity comes something sober and entirely practical for anyone walking this road. For salvation — najat — the question is exactly this: which of the ranks'' gnosis does a person manage to acquire, and how much of it? As much gnosis as a person attains within a lifetime, by that measure his station, his martaba, will be established. And according to that station, the corresponding hierarchy will be set in place within his هَيْكَل, his spiritual form. It is through knowledge — ilm — and action — عَمَل — working together that the arrangement inside the هَيْكَل is built. A person''s eventual rank in the spiritual world is not handed to him arbitrarily. It is the precise measure of the gnosis he attained and enacted in this life. And what, in the end, is salvation itself? It is khatima bil-khair, a good end. To finish well, to close one''s life upon the good — that is salvation, and that good end is itself the fruit of the gnosis and the action gathered along the way.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'out of that immensity comes something sober and entirely practical for anyone walking this road for salvation najat the question is exactly this which of the ranks gnosis does a person manage to acquire and how much of it as much gnosis as a person attains within a lifetime by that measure his station his martaba will be established and according to that station the corresponding hierarchy will be set in place within his هيكل his spiritual form it is through knowledge ilm and action عمل working together that the arrangement inside the هيكل is built a persons eventual rank in the spiritual world is not handed to him arbitrarily it is the precise measure of the gnosis he attained and enacted in this life and what in the end is salvation itself it is khatima bil khair a good end to finish well to close ones life upon the good that is salvation and that good end is itself the fruit of the gnosis and the action gathered along the way', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 11, NULL, 'Here a delicate question presses in. Is gnosis attained by one''s own doing, or is it made to happen to a person? The teaching holds both at once and refuses to let go of either. The effort a person expends — his juhd — genuinely earns him gnosis; he really does strive, and he really does acquire. But onto that effort there also descends the grace — the fazl — of those who stand above him, so that gnosis is also made to happen to him, bestowed from a higher hand. Neither one is enough by itself. There is the labor that is a person''s to perform, and there is the grace that is given from above, and gnosis is the place where the two meet.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'here a delicate question presses in is gnosis attained by ones own doing or is it made to happen to a person the teaching holds both at once and refuses to let go of either the effort a person expends his juhd genuinely earns him gnosis he really does strive and he really does acquire but onto that effort there also descends the grace the fazl of those who stand above him so that gnosis is also made to happen to him bestowed from a higher hand neither one is enough by itself there is the labor that is a persons to perform and there is the grace that is given from above and gnosis is the place where the two meet', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 12, NULL, 'The word حُدُود itself carries something more. A had is a limit. Every rank has its limit, a boundary it cannot pass beyond, and to know that limit — the final point of ascent, the nuqta-e irtifa to which a given rank rises — is itself part of the gnosis of the ranks. So the limit of the Prophet''s ascent, peace and blessings upon him, is Hijabiyyat, the station of being a veil. The limit of Lady Fatimah is Hujjiyyat, the station of the Hujjah, the proof. The final point of Abd al-Muttalib is Jaddiyyat, the station of the Jadd — and Jaddiyyat is not a single point but comprises ten stations, ten maratib, so that one must know further at which of those ten degrees a particular individual is found, the seventh standing lower and the higher being something other than it. To attain the gnosis of these limits, and of the gradations folded inside each one, is a very great science indeed. This is Tawhid.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the word حدود itself carries something more a had is a limit every rank has its limit a boundary it cannot pass beyond and to know that limit the final point of ascent the nuqta e irtifa to which a given rank rises is itself part of the gnosis of the ranks so the limit of the prophets ascent peace and blessings upon him is hijabiyyat the station of being a veil the limit of lady fatimah is hujjiyyat the station of the hujjah the proof the final point of abd al muttalib is jaddiyyat the station of the jadd and jaddiyyat is not a single point but comprises ten stations ten maratib so that one must know further at which of those ten degrees a particular individual is found the seventh standing lower and the higher being something other than it to attain the gnosis of these limits and of the gradations folded inside each one is a very great science indeed this is tawhid', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 13, NULL, 'The opening saying named three things, not one, and each must be taken in turn, for Tawhid in its full statement has three branches. The first is Tawhid itself, already laid down: marifat al-hudud, the gnosis of the ranks.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the opening saying named three things not one and each must be taken in turn for tawhid in its full statement has three branches the first is tawhid itself already laid down marifat al hudud the gnosis of the ranks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 14, NULL, 'The second branch is تَنْزِيه. The saying defines it as nafyi al-ilahiyyat anhum — the negation of divinity from the ranks. To perform تَنْزِيه is to declare transcendent, to declare pure, and specifically to deny that divinity resides in the حُدُود. There is no divinity in the ranks; the attribute of creating, of bringing beings into existence, is not theirs. But exactness about what ilahiyyat, divinity, means here matters, because the word ilah carries more than one sense. What is intended in this place is ibda (إبداع) al-zawat, the origination of beings — the power to bring a being into existence out of nothing. Tanzih strips that power away from the ranks: not one of them, the saying insists, possesses the power of ibda-e zawat, the origination of a being. Not even the First Intellect, the Aql al-Awwal, possesses it. Every one of them, without a single exception, is itself created — paida kiye hue — and the created cannot originate. A second meaning of ilah — the sense in which a higher rank becomes, for the one who stands bewildered before it, a kind of "god" — is set aside for the present. For now the sense that تَنْزِيه needs is this: the creating power belongs to none of the ranks, and so divinity, in the sense of origination, must be negated from them all.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the second branch is تنزيه the saying defines it as nafyi al ilahiyyat anhum the negation of divinity from the ranks to perform تنزيه is to declare transcendent to declare pure and specifically to deny that divinity resides in the حدود there is no divinity in the ranks the attribute of creating of bringing beings into existence is not theirs but exactness about what ilahiyyat divinity means here matters because the word ilah carries more than one sense what is intended in this place is ibda ابداع al zawat the origination of beings the power to bring a being into existence out of nothing tanzih strips that power away from the ranks not one of them the saying insists possesses the power of ibda e zawat the origination of a being not even the first intellect the aql al awwal possesses it every one of them without a single exception is itself created paida kiye hue and the created cannot originate a second meaning of ilah the sense in which a higher rank becomes for the one who stands bewildered before it a kind of god is set aside for the present for now the sense that تنزيه needs is this the creating power belongs to none of the ranks and so divinity in the sense of origination must be negated from them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 15, NULL, 'The third branch is تَجْرِيد, defined as salb al-asmai wa al-sifati an Allah Taala — the divestment of the names and the attributes from God the Exalted. The root of تَجْرِيد is the stripping of bark from a tree, and that is precisely the image: to strip away from God every name and every attribute, because no name can truly be predicated of Him. Even the name "Allah" cannot, in the strictest sense, truly be His — for it too is a name, and He is beyond all names. So out of sheer necessity one is reduced to calling Him "Hu," "He" — and even in saying "Hu" a person confesses his own helplessness. O God, we have no words. To affirm even our own existence we are forced to address You somehow — but by what name shall we call You? This is the predicament caught in the phrase:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the third branch is تجريد defined as salb al asmai wa al sifati an allah taala the divestment of the names and the attributes from god the exalted the root of تجريد is the stripping of bark from a tree and that is precisely the image to strip away from god every name and every attribute because no name can truly be predicated of him even the name allah cannot in the strictest sense truly be his for it too is a name and he is beyond all names so out of sheer necessity one is reduced to calling him hu he and even in saying hu a person confesses his own helplessness o god we have no words to affirm even our own existence we are forced to address you somehow but by what name shall we call you this is the predicament caught in the phrase', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 16, NULL, 'Sayingذَنْبٌ مَشْفُوعٌ بِالِاسْتِغْفَارِ"A sin coupled with a plea for forgiveness."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'sayingذنب مشفوع بالاستغفار a sin coupled with a plea for forgiveness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 17, NULL, 'The very act of naming Him is a kind of sin — and yet it is a sin that arrives already accompanied by its own forgiveness. For man is helpless. He must call upon God by some name, because if he did not, he would in effect be denying that the Existent exists at all. To turn toward the existence of God he must address Him; to address Him he must name Him; and in naming Him he commits the fault. But the istighfar (اِسْتِغْفَار), the plea for pardon, is built into the act itself — because God the Exalted understands the helplessness of His servant. He knows the servant owns no word adequate to call upon Him, and that by whatever name the servant calls, that calling will be accepted, and the forgiveness granted along with it. So تَجْرِيد is the negation, from God the Exalted, of all the names and all the attributes whatsoever that might be ascribed to Him.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the very act of naming him is a kind of sin and yet it is a sin that arrives already accompanied by its own forgiveness for man is helpless he must call upon god by some name because if he did not he would in effect be denying that the existent exists at all to turn toward the existence of god he must address him to address him he must name him and in naming him he commits the fault but the istighfar استغفار the plea for pardon is built into the act itself because god the exalted understands the helplessness of his servant he knows the servant owns no word adequate to call upon him and that by whatever name the servant calls that calling will be accepted and the forgiveness granted along with it so تجريد is the negation from god the exalted of all the names and all the attributes whatsoever that might be ascribed to him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 18, NULL, 'This whole three-branched saying is qawlun mujmalun — a summary, an encompassing statement that now stands in need of detailed exposition. The exposition begins by opening a division within the gnosis of the ranks itself:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'this whole three branched saying is qawlun mujmalun a summary an encompassing statement that now stands in need of detailed exposition the exposition begins by opening a division within the gnosis of the ranks itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 19, NULL, 'Sayingلِأَنَّ الْمَعْرِفَةَ بِالْحُدُودِ مَعْرِفَتَانِ: مَعْرِفَةٌ ظَاهِرَةٌ يُعْرَفُ بِهَا شَخْصُ الْحَدِّ وَمَقَامُهُ، وَهَذِهِ الْمَعْرِفَةُ يَتَسَاوَى فِيهَا الْوَلِيُّ وَغَيْرُهُ مِنَ الْأَضْدَادِ وَالطُّغَاةِ؛ وَمَعْرِفَةٌ بَاطِنَةٌ يَخْتَصُّ بِهَا أَهْلُ الْمَعَارِفِ مِنْ أَهْلِ الْحَقِّ، وَهُوَ ابْتِدَاءُ وُجُودِ الْحَدِّ"Because the gnosis of the ranks is of two kinds of gnosis: an outer gnosis, by which the person of the rank and his station are known, and in which the friend and others among the adversaries and the tyrants stand equal; and an inner gnosis, special to the people of gnosis from among the people of truth — and it is the beginning of the existence of the rank."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'sayingلان المعرفه بالحدود معرفتان معرفه ظاهره يعرف بها شخص الحد ومقامه وهذه المعرفه يتساوي فيها الولي وغيره من الاضداد والطغاه ومعرفه باطنه يختص بها اهل المعارف من اهل الحق وهو ابتداء وجود الحد because the gnosis of the ranks is of two kinds of gnosis an outer gnosis by which the person of the rank and his station are known and in which the friend and others among the adversaries and the tyrants stand equal and an inner gnosis special to the people of gnosis from among the people of truth and it is the beginning of the existence of the rank', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 20, NULL, 'So the gnosis of the ranks is of two kinds. The first is the outer gnosis, the marifah zahirah, by which the person of a rank and his station are recognized — the knowledge of who a given rank is and where he stands. Its distinguishing mark is this: in the outer gnosis the friend, the wali (وَلِيّ), and the adversary stand on perfectly equal footing. The lover, the enemy, and the indifferent stranger all perceive the same outward person. All of them see how tall he is, how many feet in height; whether his face is round, whether he wears a beard; what his hands are like, what his feet are like. The devoted disciple sees exactly this, and the bitter enemy sees exactly this, and in that respect there is no difference between them at all. The outer gnosis is not trivial — it too is hard to attain in its fullness. But its mark is that in it friend and foe are made equal, because it reaches only the outward person and his station.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'so the gnosis of the ranks is of two kinds the first is the outer gnosis the marifah zahirah by which the person of a rank and his station are recognized the knowledge of who a given rank is and where he stands its distinguishing mark is this in the outer gnosis the friend the wali ولي and the adversary stand on perfectly equal footing the lover the enemy and the indifferent stranger all perceive the same outward person all of them see how tall he is how many feet in height whether his face is round whether he wears a beard what his hands are like what his feet are like the devoted disciple sees exactly this and the bitter enemy sees exactly this and in that respect there is no difference between them at all the outer gnosis is not trivial it too is hard to attain in its fullness but its mark is that in it friend and foe are made equal because it reaches only the outward person and his station', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 21, NULL, 'The second kind, far higher, is the inner gnosis — the marifah batinah — and this one is reserved to the people of gnosis, the ahl al-maarif, from among the people of truth, the ahl al-haqq. What is its object? It is ibtida wujud al-had — the very beginning of the existence of the rank. When did the existence of a given had begin? These ranks that were created — where were they created, and from whom? Here, in compressed form, opens the long and difficult account of how the ranks came to be. The حُدُود were brought into being where the fatahun were — those whose sins were few — and then they were called. A first call went out, and at that first call they did not confess; a second call was made, and a third, and a fourth; in each room they were summoned in turn, the way a sealed message is carried from chamber to chamber before it is finally opened — and one must know in which room each rank finally made its confession. This is a very long account, and its full telling lies beyond the present matter. But the point that matters now is this: the gnosis of that beginning — of where, and from whom, and through how many summons a rank came into being — is precisely the inner gnosis, and the gnosis of such a thing belongs to the Imam of the Age, the إِمَام الزَّمَان, upon him be peace.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the second kind far higher is the inner gnosis the marifah batinah and this one is reserved to the people of gnosis the ahl al maarif from among the people of truth the ahl al haqq what is its object it is ibtida wujud al had the very beginning of the existence of the rank when did the existence of a given had begin these ranks that were created where were they created and from whom here in compressed form opens the long and difficult account of how the ranks came to be the حدود were brought into being where the fatahun were those whose sins were few and then they were called a first call went out and at that first call they did not confess a second call was made and a third and a fourth in each room they were summoned in turn the way a sealed message is carried from chamber to chamber before it is finally opened and one must know in which room each rank finally made its confession this is a very long account and its full telling lies beyond the present matter but the point that matters now is this the gnosis of that beginning of where and from whom and through how many summons a rank came into being is precisely the inner gnosis and the gnosis of such a thing belongs to the imam of the age the امام الزمان upon him be peace', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 22, NULL, 'The inner gnosis does not stop at the beginning. It comprises also ghayatuhu, the rank''s end, and ila ayna maaduhu wa nihayatuhu — where its return, its maad, and its final terminus lie. To know the inner reality of a had is to know the entire arc of its essence, its khamira: at what point that essence was first established, and at what level a person was standing when he passed out of this world. Was he in the ninth degree of the Mumin, or the eighth, or the seventh? Did he climb from Mumin to become a مُكَثِّر, and from مُكَثِّر to become a Madhun? At precisely which station did his existence come to rest, and to what return is it bound? This is a gnosis of extreme difficulty, and neither its steepness nor its stakes are to be softened. It cannot be reached except by the murtazin, the disciplined ones, and the muhiqqin, the verifiers — those who have purified themselves and proven the truth within themselves. And then comes a word of the utmost severity: for one whose gnosis of this inner reality is deficient, there is no Tawhid at all. Without the inner knowledge of the beginning, the level, and the return of a rank''s essence, a man may hold no true Tawhid whatsoever.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'the inner gnosis does not stop at the beginning it comprises also ghayatuhu the ranks end and ila ayna maaduhu wa nihayatuhu where its return its maad and its final terminus lie to know the inner reality of a had is to know the entire arc of its essence its khamira at what point that essence was first established and at what level a person was standing when he passed out of this world was he in the ninth degree of the mumin or the eighth or the seventh did he climb from mumin to become a مكثر and from مكثر to become a madhun at precisely which station did his existence come to rest and to what return is it bound this is a gnosis of extreme difficulty and neither its steepness nor its stakes are to be softened it cannot be reached except by the murtazin the disciplined ones and the muhiqqin the verifiers those who have purified themselves and proven the truth within themselves and then comes a word of the utmost severity for one whose gnosis of this inner reality is deficient there is no tawhid at all without the inner knowledge of the beginning the level and the return of a ranks essence a man may hold no true tawhid whatsoever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'what oneness actually means', '4. What Oneness Actually Means', 23, NULL, 'So something of this matter is set down here — opened, as far as it can be opened — as a help to the brethren in the gnosis of the Tawhid of God the Exalted. The inner gnosis has named its price and named its reward; what remains is to begin, carefully, to enter it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 4 what oneness actually means', 'so something of this matter is set down here opened as far as it can be opened as a help to the brethren in the gnosis of the tawhid of god the exalted the inner gnosis has named its price and named its reward what remains is to begin carefully to enter it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 0, NULL, 'With the help of God, glory be to Him, and under the gaze of His friend upon His earth, peace be upon him — the price has been named and the reward has been named. Now the door opens, one foot after the other, for this is learned only by entering it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'with the help of god glory be to him and under the gaze of his friend upon his earth peace be upon him the price has been named and the reward has been named now the door opens one foot after the other for this is learned only by entering it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 1, NULL, 'Sayingفَأَقُولُ بِعَوْنِ اللَّهِ سُبْحَانَهُ وَلَحَظَاتِ وَلِيِّهِ فِي أَرْضِهِ، سَلَامُ اللَّهِ عَلَيْهِ، إِنَّ أَقْرَبَ الْحُدُودِ إِلَيْنَا هُوَ الْمُكَاثِرُ وَمَا ثَبَتَ مِنَ الْقَوْلِ فِي الدَّانِي مِنَ الْحُدُودِ ثَبَتَ فِي الْعَالِي."So I say, with the help of God, glory be to Him, and the glances of His Wali upon His earth, peace of God be upon him: verily the closest of the ranks to us is the Mukathir, and what is established of the saying regarding the lower of the ranks is established for the higher."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingفاقول بعون الله سبحانه ولحظات وليه في ارضه سلام الله عليه ان اقرب الحدود الينا هو المكاثر وما ثبت من القول في الداني من الحدود ثبت في العالي so i say with the help of god glory be to him and the glances of his wali upon his earth peace of god be upon him verily the closest of the ranks to us is the mukathir and what is established of the saying regarding the lower of the ranks is established for the higher', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 2, NULL, 'That single breath carries two things, and everything that follows rests on them. The first: the rank nearest to a person — the one through which an ordinary man makes his first true contact with the spiritual order — is the Mukathir (مُكَثِّر). The second is a rule of proportion that governs all that follows. Whatever is established for the lower rank is established, in its own measure, for the higher. What holds of the Mukathir holds, raised to its degree, of the Madhun, the Dai Mutlaq, the Dai Mahsur, and every rank above him. A single law of load-bearing runs through every floor of a building: proven for the ground floor, it is proven, in proportion, for the floors that rest upon it. And it runs in both directions, for a higher rank carries the lower one within himself. A Madhun is also a Mukathir in his own place — and was a Mukathir before he was ever a Madhun.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'that single breath carries two things and everything that follows rests on them the first the rank nearest to a person the one through which an ordinary man makes his first true contact with the spiritual order is the mukathir مكثر the second is a rule of proportion that governs all that follows whatever is established for the lower rank is established in its own measure for the higher what holds of the mukathir holds raised to its degree of the madhun the dai mutlaq the dai mahsur and every rank above him a single law of load bearing runs through every floor of a building proven for the ground floor it is proven in proportion for the floors that rest upon it and it runs in both directions for a higher rank carries the lower one within himself a madhun is also a mukathir in his own place and was a mukathir before he was ever a madhun', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 3, NULL, 'But the Mukathir cannot be reached in a single step. Below the ranks proper lie two thresholds that must first be crossed. The first is the Mustajib, the responder — literally, the one who accepts. The Mustajib is the one who takes the noble pledge, the ahd sharif, saying with his tongue, "I accept the noble pledge," whether or not his heart and his deeds have yet caught up with his tongue. That is his defining mark: the profession on the tongue. He affirms, "the Imam of this time is such," and binds himself by that word. The Mustajib has ten levels, graded by hiddat — the intensity, the sharpness, the keenness of gaze with which the pledge is taken. Some come to the pledge the way a man drifts into a marriage, casually, half-attending. Others take it with the burning intensity of a Sayyidna Jafar. The Imam himself takes the pledge. According to the intensity of the one pledging, his level is fixed — and so there are ten degrees of the noble pledge.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'but the mukathir cannot be reached in a single step below the ranks proper lie two thresholds that must first be crossed the first is the mustajib the responder literally the one who accepts the mustajib is the one who takes the noble pledge the ahd sharif saying with his tongue i accept the noble pledge whether or not his heart and his deeds have yet caught up with his tongue that is his defining mark the profession on the tongue he affirms the imam of this time is such and binds himself by that word the mustajib has ten levels graded by hiddat the intensity the sharpness the keenness of gaze with which the pledge is taken some come to the pledge the way a man drifts into a marriage casually half attending others take it with the burning intensity of a sayyidna jafar the imam himself takes the pledge according to the intensity of the one pledging his level is fixed and so there are ten degrees of the noble pledge', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 4, NULL, 'The second threshold is the Mumin, the believer. The classical definition holds its three parts together:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the second threshold is the mumin the believer the classical definition holds its three parts together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 5, NULL, 'Sayingالْقَوْلُ بِاللِّسَانِ وَالتَّصْدِيقُ بِالْجَنَانِ وَالْعَمَلُ بِالْأَرْكَانِ"Profession with the tongue, affirmation with the heart, and action with the limbs."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingالقول باللسان والتصديق بالجنان والعمل بالاركان profession with the tongue affirmation with the heart and action with the limbs', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 6, NULL, 'The Mumin is the one in whom all three have joined: he professes with his tongue, he affirms inwardly in his heart, and he acts outwardly with his limbs. He too has ten levels of his own. Here a distinction holds firm: neither the Mustajib nor the Mumin belongs to the hudud (حُدُود). They stand below the ranks proper — the necessary thresholds crossed on the approach to the hierarchy, but not yet part of it. Only after these, only with the Mukathir, does one truly step inside.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the mumin is the one in whom all three have joined he professes with his tongue he affirms inwardly in his heart and he acts outwardly with his limbs he too has ten levels of his own here a distinction holds firm neither the mustajib nor the mumin belongs to the hudud حدود they stand below the ranks proper the necessary thresholds crossed on the approach to the hierarchy but not yet part of it only after these only with the mukathir does one truly step inside', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 7, NULL, 'With the Mukathir the threshold is crossed. He is the first rank within the hudud, the first degree of the spiritual order, and it is exactly this rank that the Prophet''s transmitted saying placed nearest. The word itself reveals what he is. Mukathir comes from kasr, breaking — for the Mukathir is the one who breaks his opponent with his proofs, his hujjat. But whom does he break first? Not the man before him. He must first break his own self. This is kasr-e nafs, the breaking of the self, and there is no beginning without it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'with the mukathir the threshold is crossed he is the first rank within the hudud the first degree of the spiritual order and it is exactly this rank that the prophets transmitted saying placed nearest the word itself reveals what he is mukathir comes from kasr breaking for the mukathir is the one who breaks his opponent with his proofs his hujjat but whom does he break first not the man before him he must first break his own self this is kasr e nafs the breaking of the self and there is no beginning without it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 8, NULL, 'To perform kasr-e nafs is to put every word, every deed, and every intention through one relentless examination. The self must ask: Is what I am about to say in line with the command of God and His Prophet? Is the deed I am about to do in line with their command? Is the very thought now crossing my mind in line with the command of God and His Prophet? To bind oneself entirely to that single measure — to become a captive of the command in speech, in action, and in thought alike — that is what it means to be a Mukathir.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'to perform kasr e nafs is to put every word every deed and every intention through one relentless examination the self must ask is what i am about to say in line with the command of god and his prophet is the deed i am about to do in line with their command is the very thought now crossing my mind in line with the command of god and his prophet to bind oneself entirely to that single measure to become a captive of the command in speech in action and in thought alike that is what it means to be a mukathir', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 9, NULL, 'The logic is exacting. Only the man who has broken his own self can break another. If he has set himself in order in this matter, his proofs can break the one who stands before him. But if he could not break his own self — indulging it instead, telling it this is allowed and that is allowed, handing himself a license here and an excuse there — then how is he to break anyone else? He has no standing to do it. From this comes a hard requirement. For the Mukathir, the acquisition of the sciences, the ulum, is not optional; it is indispensable. Without knowledge no Mukathir is ever formed, for he must first know the command of God and His Prophet in order to test himself against it. Only once he knows the command can he recognize that some word of his fell short of it, that some deed of his swerved from it, that some thought of his strayed from it. Having judged and broken himself by that knowledge, he is then fit to break the man before him with his proofs. And by the rule already set down — what is fixed for the lower is fixed for the higher — this same description holds, each at his proper degree, for the Mukathir, the Madhun, the Dai Mutlaq, the Dai Mahsur, and every rank of the hudud above.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the logic is exacting only the man who has broken his own self can break another if he has set himself in order in this matter his proofs can break the one who stands before him but if he could not break his own self indulging it instead telling it this is allowed and that is allowed handing himself a license here and an excuse there then how is he to break anyone else he has no standing to do it from this comes a hard requirement for the mukathir the acquisition of the sciences the ulum is not optional it is indispensable without knowledge no mukathir is ever formed for he must first know the command of god and his prophet in order to test himself against it only once he knows the command can he recognize that some word of his fell short of it that some deed of his swerved from it that some thought of his strayed from it having judged and broken himself by that knowledge he is then fit to break the man before him with his proofs and by the rule already set down what is fixed for the lower is fixed for the higher this same description holds each at his proper degree for the mukathir the madhun the dai mutlaq the dai mahsur and every rank of the hudud above', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 10, NULL, 'A real difficulty rises here. If the Mukathir is flesh and bone like everyone else, what actually separates him from the ordinary man beside him? The matter is stated thus:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'a real difficulty rises here if the mukathir is flesh and bone like everyone else what actually separates him from the ordinary man beside him the matter is stated thus', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 11, NULL, 'Sayingوَذَلِكَ أَنَّهُ وَإِنْ كَانَ يَجْمَعُهُ وَغَيْرَهُ مِنَ الْأَشْخَاصِ الْإِنْسَانِيَّةِ الْحُدُودُ وَالْأَقْطَارُ وَكَوْنُهُمَا جَمِيعًا مِنْ لَحْمٍ وَدَمٍ وَعِظَامٍ وَأَعْصَابٍ وَعُرُوقٍ وَغَيْرِ ذَلِكَ فَلَيْسَ بِسَوَاءٍ."And that is because, although he and others from among the human persons are gathered by the limits and the regions, and although both of them are entirely of flesh and blood and bones and nerves and veins and other than that, yet they are not the same."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingوذلك انه وان كان يجمعه وغيره من الاشخاص الانسانيه الحدود والاقطار وكونهما جميعا من لحم ودم وعظام واعصاب وعروق وغير ذلك فليس بسواء and that is because although he and others from among the human persons are gathered by the limits and the regions and although both of them are entirely of flesh and blood and bones and nerves and veins and other than that yet they are not the same', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 12, NULL, 'The Mukathir and the ordinary man are gathered inside the same limits, the same hudud, the same regions, the same aqtar — the same boundaries of body and place hold them both. Both are made of flesh, both of blood, both of bones, nerves, veins, and all the rest. Set side by side and inspected from the outside, they show no difference: this one is flesh and bone, that one is flesh and bone. And yet they are not the same. Beneath an identical outward composition lies an immense difference. The matter is resolved thus:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the mukathir and the ordinary man are gathered inside the same limits the same hudud the same regions the same aqtar the same boundaries of body and place hold them both both are made of flesh both of blood both of bones nerves veins and all the rest set side by side and inspected from the outside they show no difference this one is flesh and bone that one is flesh and bone and yet they are not the same beneath an identical outward composition lies an immense difference the matter is resolved thus', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 13, NULL, 'Sayingلِأَنَّ هَذَا الْحَدَّ الَّذِي هُوَ الْمُكَاثِرُ قَدْ تَلَطَّفَ مِزَاجُهُ وَصَفَا جَوْهَرُهُ وَهَذَا صُعُودًا مَرَاتِبَ جُمَّةً."Because this rank, which is the Mukathir, his temperament has become refined and his essence has become pure, and this through ascending many stations."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingلان هذا الحد الذي هو المكاثر قد تلطف مزاجه وصفا جوهره وهذا صعودا مراتب جمه because this rank which is the mukathir his temperament has become refined and his essence has become pure and this through ascending many stations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 14, NULL, 'The difference is not merely inward; it reaches even into the outward. The Mukathir''s temperament has been refined — talattafa mizajuhu — and his essence made pure — safa jawharuhu. His flesh is no longer common flesh, his blood no longer common blood. Everything of his has been transformed, and transformed even outwardly, though no one around him perceived it and the ignorant could not begin to discern it. And how did this come about? He climbed through stations upon stations that others never reached. The passage continues:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the difference is not merely inward it reaches even into the outward the mukathirs temperament has been refined talattafa mizajuhu and his essence made pure safa jawharuhu his flesh is no longer common flesh his blood no longer common blood everything of his has been transformed and transformed even outwardly though no one around him perceived it and the ignorant could not begin to discern it and how did this come about he climbed through stations upon stations that others never reached the passage continues', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 15, NULL, 'Sayingوَتَقَرَّبَ بِهَا فَتَقَرَّبَ بِهَا مِنَ الْمَبْدَإِ الْأَوَّلِ حَتَّى صَارَ فِي أَعْلَى مَرَاتِبِ الْإِنْسَانِيَّةِ الَّتِي هِيَ أَوَّلُ رُتَبِ الْمَلَكُوتِيَّةِ."And he drew near through that, drawing near through it to the first principle, until he reached the highest stations of humanity, which are the first of the spiritual ranks."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingوتقرب بها فتقرب بها من المبدا الاول حتي صار في اعلي مراتب الانسانيه التي هي اول رتب الملكوتيه and he drew near through that drawing near through it to the first principle until he reached the highest stations of humanity which are the first of the spiritual ranks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 16, NULL, 'Through that refinement and that ascent he has drawn close to the first principle, al-mabda al-awwal — close, that is, to the very source his creation came out of, so that he now stands near to returning to it. He has reached the highest stations of the human, and those highest human stations are themselves the first of the spiritual ranks, awwalu rutab al-malakutiyya. The image is of a staircase between two floors: the topmost stair of the lower floor is, at the same time, the first stair of the floor above. The summit of the human is the threshold of the malakut, the spiritual world, and the Mukathir stands exactly on that joining-stair — where the highest rung of the human order is also the lowest rung of the angelic.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'through that refinement and that ascent he has drawn close to the first principle al mabda al awwal close that is to the very source his creation came out of so that he now stands near to returning to it he has reached the highest stations of the human and those highest human stations are themselves the first of the spiritual ranks awwalu rutab al malakutiyya the image is of a staircase between two floors the topmost stair of the lower floor is at the same time the first stair of the floor above the summit of the human is the threshold of the malakut the spiritual world and the mukathir stands exactly on that joining stair where the highest rung of the human order is also the lowest rung of the angelic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 17, NULL, 'From that height comes the most exalted thing said of him:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'from that height comes the most exalted thing said of him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 18, NULL, 'Sayingوَهُوَ مَهْبِطٌ لِوَحْيِ اللَّهِ وَبَيْتٌ مِنْ بُيُوتِهِ."And he is a place of descent for the revelation of God, and a house from His houses."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingوهو مهبط لوحي الله وبيت من بيوته and he is a place of descent for the revelation of god and a house from his houses', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 19, NULL, 'He is the mahbat — the landing-place — for the wahy, the revelation of God; the very ground upon which revelation alights. And he is a bayt, a house, from among the houses of God. Why is he so? Because in his every thought he kept the command of God and His Prophet before him; in his every word he kept that command before him; in his every deed he kept it before him. Having made that command the standing presence of his thinking, his speaking, and his acting, he became a house from the houses of God, a place fit for revelation to descend upon. This is anchored in the Book itself:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'he is the mahbat the landing place for the wahy the revelation of god the very ground upon which revelation alights and he is a bayt a house from among the houses of god why is he so because in his every thought he kept the command of god and his prophet before him in his every word he kept that command before him in his every deed he kept it before him having made that command the standing presence of his thinking his speaking and his acting he became a house from the houses of god a place fit for revelation to descend upon this is anchored in the book itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 20, NULL, 'فِي بُيُوتٍ أَذِنَ اللَّهُ أَن تُرْفَعَ وَيُذْكَرَ فِيهَا اسْمُهُ يُسَبِّحُ لَهُ فِيهَا بِالْغُدُوِّ وَالْآصَالِ"In houses which God has permitted to be exalted and His name to be remembered therein; in them He is glorified in the mornings and the evenings."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'في بيوت اذن الله ان ترفع ويذكر فيها اسمه يسبح له فيها بالغدو والاصال in houses which god has permitted to be exalted and his name to be remembered therein in them he is glorified in the mornings and the evenings', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 21, NULL, 'Sayingثُمَّ حَقَّقَ فِي الْآيَةِ أَنَّ الْبُيُوتَ هُمُ الْحُدُودُ."Then He established in the verse that the houses are the ranks."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingثم حقق في الايه ان البيوت هم الحدود then he established in the verse that the houses are the ranks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 22, NULL, 'So the "houses" of the verse — the ones God permitted to be exalted, within which His name is remembered and glorified morning and evening — are, in their inner meaning, the hudud, the ranks of the hierarchy, of whom the Mukathir is the first. And the verse continues:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'so the houses of the verse the ones god permitted to be exalted within which his name is remembered and glorified morning and evening are in their inner meaning the hudud the ranks of the hierarchy of whom the mukathir is the first and the verse continues', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 23, NULL, 'رِجَالٌ لَّا تُلْهِيهِمْ تِجَارَةٌ وَلَا بَيْعٌ عَن ذِكْرِ اللَّهِ وَإِقَامِ الصَّلَاةِ وَإِيتَاءِ الزَّكَاةِ"Men whom neither commerce nor sale diverts from the remembrance of God and the establishing of prayer and the giving of zakat."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'رجال لا تلهيهم تجاره ولا بيع عن ذكر الله واقام الصلاه وايتاء الزكاه men whom neither commerce nor sale diverts from the remembrance of god and the establishing of prayer and the giving of zakat', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 24, NULL, 'Sayingيُرِيدُ إِقَامَةَ الدَّعْوَةِ"By which He intends the establishing of the dawah."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingيريد اقامه الدعوه by which he intends the establishing of the dawah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 25, NULL, 'Those "men whom neither commerce nor sale diverts from the remembrance of God, the establishing of prayer, and the giving of zakat" are these same ranks. And what is meant here by their establishing of prayer is, in its inner sense, iqamat al-dawah — the establishing of the divine summons, the dawah. The verse''s outward language of trade and selling is illuminated by the parallel passage in Surah al-Jumuah:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'those men whom neither commerce nor sale diverts from the remembrance of god the establishing of prayer and the giving of zakat are these same ranks and what is meant here by their establishing of prayer is in its inner sense iqamat al dawah the establishing of the divine summons the dawah the verses outward language of trade and selling is illuminated by the parallel passage in surah al jumuah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 26, NULL, 'Sayingيَا أَيُّهَا الَّذِينَ آمَنُوا إِذَا نُودِيَ لِلصَّلَاةِ مِن يَوْمِ الْجُمُعَةِ فَاسْعَوْا إِلَىٰ ذِكْرِ اللَّهِ وَذَرُوا الْبَيْعَ ۚ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ ۝ فَإِذَا قُضِيَتِ الصَّلَاةُ فَانتَشِرُوا فِي الْأَرْضِ وَابْتَغُوا مِن فَضْلِ اللَّهِ وَاذْكُرُوا اللَّهَ كَثِيرًا لَّعَلَّكُمْ تُفْلِحُونَ"O you who believe, when the call is proclaimed for the prayer on the day of Jumuah, hasten to the remembrance of God and leave off trade. That is better for you, if you only knew. And when the prayer is concluded, disperse in the land and seek of the bounty of God, and remember God much, that you may be successful."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingيا ايها الذين امنوا اذا نودي للصلاه من يوم الجمعه فاسعوا الي ذكر الله وذروا البيع ذلكم خير لكم ان كنتم تعلمون فاذا قضيت الصلاه فانتشروا في الارض وابتغوا من فضل الله واذكروا الله كثيرا لعلكم تفلحون o you who believe when the call is proclaimed for the prayer on the day of jumuah hasten to the remembrance of god and leave off trade that is better for you if you only knew and when the prayer is concluded disperse in the land and seek of the bounty of god and remember god much that you may be successful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 27, NULL, 'Those whom the commerce and the buying and selling of the world cannot divert from the remembrance of God, from the establishing of prayer, from the giving of zakat — they are the very ones who, in the inner sense, establish the dawah.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'those whom the commerce and the buying and selling of the world cannot divert from the remembrance of god from the establishing of prayer from the giving of zakat they are the very ones who in the inner sense establish the dawah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 28, NULL, 'Once the establishing of prayer is seen to mean the establishing of the dawah, a wider door opens. Every pillar, every obligation of the religion carries an inner meaning, a taweel, beneath its outward form — the way a sealed letter passes through several hands before it reaches the one it was written for, each outward act delivering an inner sense to those fit to read it. These may be set out one by one.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'once the establishing of prayer is seen to mean the establishing of the dawah a wider door opens every pillar every obligation of the religion carries an inner meaning a taweel beneath its outward form the way a sealed letter passes through several hands before it reaches the one it was written for each outward act delivering an inner sense to those fit to read it these may be set out one by one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 29, NULL, 'Wilayat, in its inner sense, is to repent in the world of motes — to turn back in repentance in that primordial world of the smallest particles of being. Taharat, purity, is to cleanse oneself of the filth of Iblis through the knowledge of the Tenth. Salat, prayer, is to act upon the commands of the Tenth — or of whichever Imam in whose sphere one has arrived and whose dawah has reached him — to carry out the commands he has given. This is exactly why, when the prayer is established, the announcement is "the prayer has stood," qad qamat al-salah, for qiyam means to stand, and the standing of the prayer is the standing-up to enact the command. Zakat is to give out a portion of the knowledge one has been given: once the knowledge received reaches a certain measure, a small portion of it becomes obligatory to dispense. This mirrors material zakat exactly. In the outward law there is zakat al-fitra, owed by every single person, and there is zakat al-mal, which falls due only when wealth has piled up to its threshold. So it is with the zakat of knowledge. Some sciences are owed by nature to every person and must be explained to all, like the fitra. Others, like the zakat on accumulated wealth, are owed only once one''s store of knowledge has grown to the level that makes a portion of it obligatory to give out.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'wilayat in its inner sense is to repent in the world of motes to turn back in repentance in that primordial world of the smallest particles of being taharat purity is to cleanse oneself of the filth of iblis through the knowledge of the tenth salat prayer is to act upon the commands of the tenth or of whichever imam in whose sphere one has arrived and whose dawah has reached him to carry out the commands he has given this is exactly why when the prayer is established the announcement is the prayer has stood qad qamat al salah for qiyam means to stand and the standing of the prayer is the standing up to enact the command zakat is to give out a portion of the knowledge one has been given once the knowledge received reaches a certain measure a small portion of it becomes obligatory to dispense this mirrors material zakat exactly in the outward law there is zakat al fitra owed by every single person and there is zakat al mal which falls due only when wealth has piled up to its threshold so it is with the zakat of knowledge some sciences are owed by nature to every person and must be explained to all like the fitra others like the zakat on accumulated wealth are owed only once ones store of knowledge has grown to the level that makes a portion of it obligatory to give out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 30, NULL, 'The inner meanings continue. Sawm, fasting, is to conceal knowledge — to withhold it from the undeserving, to keep it hidden from those unfit to receive it. Khums, the fifth, is to give out a fifth part of any knowledge that comes unexpectedly. In the outward law, when some windfall or booty reaches a man that he was not expecting, a fifth of it is due. Hazrat Imam Husayn, peace be upon him, used every month to set aside the khums even of his own salary, reasoning that he had not expected such money to come to him, and so he gave out its fifth. It is the same with knowledge. If some knowledge descends unexpectedly, from the saints of God, its fifth part must be given out. When knowledge and virtues descended upon Imam Husayn, what did he do with their fifth? He propagated it, he made the matter plain, he gave the fifth away; the remaining four parts were his own by right, but the fifth he dispensed. Hajj is al-qasdu ila bayt Allah, the setting-out toward the House of God — and the House of God, inwardly, is the Imam al-Zaman (إِمَام الزَّمَان), peace be upon him, who is the place of God; the "house" is the bab al-batin, the inner gate, and hajj is to ready one''s whole form and bearing, with a true heart, and set out toward that inner gate. And jihad is to take one''s own self — no, not merely to take it, but to sacrifice it, to slay it — in the way of God, when the command comes from the Imam al-Zaman to offer up the self. The greatest jihad is the slaying of the commanding self, the nafs, so that the true hero, the lion of the field, is the man who has killed within himself that great beast which is his own commanding soul.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the inner meanings continue sawm fasting is to conceal knowledge to withhold it from the undeserving to keep it hidden from those unfit to receive it khums the fifth is to give out a fifth part of any knowledge that comes unexpectedly in the outward law when some windfall or booty reaches a man that he was not expecting a fifth of it is due hazrat imam husayn peace be upon him used every month to set aside the khums even of his own salary reasoning that he had not expected such money to come to him and so he gave out its fifth it is the same with knowledge if some knowledge descends unexpectedly from the saints of god its fifth part must be given out when knowledge and virtues descended upon imam husayn what did he do with their fifth he propagated it he made the matter plain he gave the fifth away the remaining four parts were his own by right but the fifth he dispensed hajj is al qasdu ila bayt allah the setting out toward the house of god and the house of god inwardly is the imam al zaman امام الزمان peace be upon him who is the place of god the house is the bab al batin the inner gate and hajj is to ready ones whole form and bearing with a true heart and set out toward that inner gate and jihad is to take ones own self no not merely to take it but to sacrifice it to slay it in the way of god when the command comes from the imam al zaman to offer up the self the greatest jihad is the slaying of the commanding self the nafs so that the true hero the lion of the field is the man who has killed within himself that great beast which is his own commanding soul', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 31, NULL, 'Then the verse is sealed:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'then the verse is sealed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 32, NULL, 'Sayingيُرِيدُ إِقَامَةَ الدَّعْوَةِ الَّتِي هِيَ مَنْصُورُ الصَّلَاةِ الظَّاهِرَةِ وَلَا قِوَامَ لَهَا إِلَّا بِهَا."He intends the establishing of the dawah, which is the object supported by the outward prayer, and the dawah has no standing except through it."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingيريد اقامه الدعوه التي هي منصور الصلاه الظاهره ولا قوام لها الا بها he intends the establishing of the dawah which is the object supported by the outward prayer and the dawah has no standing except through it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 33, NULL, 'What God intends by the verse is the establishing of the dawah — the very object that the outward prayer serves and holds up. And the dawah itself has no strength, no standing, except through that prayer. The outer prayer and the inner dawah are bound to each other, each holding the other upright, the way a river first finds its channel before it can carry water to the field: were the channel cut, the water would have nowhere to run.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'what god intends by the verse is the establishing of the dawah the very object that the outward prayer serves and holds up and the dawah itself has no strength no standing except through that prayer the outer prayer and the inner dawah are bound to each other each holding the other upright the way a river first finds its channel before it can carry water to the field were the channel cut the water would have nowhere to run', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 34, NULL, 'The contrast that gives this whole teaching its weight is a warning grave enough to stir fear. Set against the Mukathir is the man who does not establish prayer:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the contrast that gives this whole teaching its weight is a warning grave enough to stir fear set against the mukathir is the man who does not establish prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 35, NULL, 'Sayingوَغَيْرُهُ مِنْ هَذِهِ الْأَشْخَاصِ الْإِنْسَانِيَّةِ وَإِنْ كَانَ عَلَى الْحَالَةِ الَّتِي هُوَ عَلَيْهَا فَإِنَّ مِزَاجَهُ غَيْرُ مُتَلَطِّفٍ وَجَوْهَرَهُ غَيْرُ صَافٍ وَشَخْصَهُ سَائِرٌ فِي الِانْحِدَارِ وَالْبُعْدِ مِنَ الْمَبْدَإِ الْأَوَّلِ سَائِرٌ فِي آخِرِ رُتَبِ الْإِنْسَانِيَّةِ مُقَهْقَرًا إِلَى مَا دُونَهُ مِنَ الصُّوَرِ الْأَلْفِيَّةِ."And other than him, of these human persons — even though he is in the same state in which the Mukathir is — his temperament is unrefined and his essence impure, and his person is proceeding in decline and in distance from the first principle, proceeding toward the last of the human ranks, pushed back to what is below it of the thousand-fold forms."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingوغيره من هذه الاشخاص الانسانيه وان كان علي الحاله التي هو عليها فان مزاجه غير متلطف وجوهره غير صاف وشخصه ساير في الانحدار والبعد من المبدا الاول ساير في اخر رتب الانسانيه مقهقرا الي ما دونه من الصور الالفيه and other than him of these human persons even though he is in the same state in which the mukathir is his temperament is unrefined and his essence impure and his person is proceeding in decline and in distance from the first principle proceeding toward the last of the human ranks pushed back to what is below it of the thousand fold forms', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 36, NULL, 'This "other than him" is the man who is not a Mukathir — the ordinary man, or the opponent. Outwardly he stands in the very same state, on the very same platform, as the Mukathir. Both are flesh and blood. Both wear the same human form. Both arrived in the same world. And yet their paths run opposite. The Mukathir is going up; this other man is going down. One draws near to the first principle; the other moves away from it. They are gathered on one platform, and from that single point one walks this way and the other that — one of them going to the cinema and one of them to the mosque, setting out together from the same spot. What decides it is the establishing of prayer. Where iqamat al-salah does not happen — where a man does not establish the inward prayer, and in that case does not even establish the outward one — he moves away from the first principle, declining toward the last of the human ranks, pushed back, muqahqaran, beneath even the lowest of them.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'this other than him is the man who is not a mukathir the ordinary man or the opponent outwardly he stands in the very same state on the very same platform as the mukathir both are flesh and blood both wear the same human form both arrived in the same world and yet their paths run opposite the mukathir is going up this other man is going down one draws near to the first principle the other moves away from it they are gathered on one platform and from that single point one walks this way and the other that one of them going to the cinema and one of them to the mosque setting out together from the same spot what decides it is the establishing of prayer where iqamat al salah does not happen where a man does not establish the inward prayer and in that case does not even establish the outward one he moves away from the first principle declining toward the last of the human ranks pushed back muqahqaran beneath even the lowest of them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 37, NULL, 'And the descent does not stop there:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'and the descent does not stop there', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 38, NULL, 'Sayingالَّتِي هِيَ أَضَلُّ سَبِيلًا مِنَ الْأَنْعَامِ إِلَى الصِّرَاطِ الْمُعْوَجِّ مُنْتَهِيًا فِيهِ إِلَى بَرْزَخِ الْخَوْفِ."Which is more astray in its path than the cattle, onto the crooked path, ending therein at the isthmus of fear."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingالتي هي اضل سبيلا من الانعام الي الصراط المعوج منتهيا فيه الي برزخ الخوف which is more astray in its path than the cattle onto the crooked path ending therein at the isthmus of fear', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 39, NULL, 'The man who fails to establish prayer is driven below the thousand-fold form, the surat al-alfiyya, until he becomes more astray in his path than the cattle, turned onto the crooked path, the sirat al-muawwaj, ending at last in the barzakh al-khawf, the isthmus of fear. Step by step he proceeds toward that dreadful end. Here the prayer rises: may God keep us, and all our brethren, far from such a fate, for the sake of the master of the prophets, peace and blessings be upon him and his pure progeny, the blessings of God upon them all. The picture stands exactly so. Two men of identical outward make, set on one platform — one establishing the inward prayer and so becoming a Mukathir who ascends, the other establishing neither inward nor even outward prayer, his temperament and his deeds so hardened that he descends. The same flesh, the same blood, the same world — and opposite ends, because of one thing: the establishing, or the abandoning, of prayer.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the man who fails to establish prayer is driven below the thousand fold form the surat al alfiyya until he becomes more astray in his path than the cattle turned onto the crooked path the sirat al muawwaj ending at last in the barzakh al khawf the isthmus of fear step by step he proceeds toward that dreadful end here the prayer rises may god keep us and all our brethren far from such a fate for the sake of the master of the prophets peace and blessings be upon him and his pure progeny the blessings of god upon them all the picture stands exactly so two men of identical outward make set on one platform one establishing the inward prayer and so becoming a mukathir who ascends the other establishing neither inward nor even outward prayer his temperament and his deeds so hardened that he descends the same flesh the same blood the same world and opposite ends because of one thing the establishing or the abandoning of prayer', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 40, NULL, 'And this is no strange or singular law. The same pattern, and a proof of it, appears down in the animal kingdom:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'and this is no strange or singular law the same pattern and a proof of it appears down in the animal kingdom', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 41, NULL, 'Sayingوَفِي الْأَشْخَاصِ الْحَيَوَانِيَّةِ عِبْرَةٌ لِمَنِ اعْتَبَرَ وَبَصِيرَةٌ لِمَنْ تَبَصَّرَ وَتَدَبَّرَ."And in the animal forms there is a lesson for one who takes a lesson, and insight for one who reflects and contemplates."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingوفي الاشخاص الحيوانيه عبره لمن اعتبر وبصيره لمن تبصر وتدبر and in the animal forms there is a lesson for one who takes a lesson and insight for one who reflects and contemplates', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 42, NULL, 'In the animal figures — and "person" here means figure, not human person — there is a lesson for whoever will take a lesson, and insight for whoever will reflect and contemplate. The argument runs thus:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'in the animal figures and person here means figure not human person there is a lesson for whoever will take a lesson and insight for whoever will reflect and contemplate the argument runs thus', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 43, NULL, 'Sayingوَذَلِكَ أَنَّ الْبَهَائِمَ الْمُحَلَّلَةَ مِنَ الْبَقَرِ وَالْغَنَمِ وَالْإِبِلِ وَغَيْرِ ذَلِكَ مُتَمَاثِلَةٌ فِي الْخَلْقِ هِيَ وَالسِّبَاعُ الْمُحَرَّمَةُ لِكَوْنِهِمْ جَمِيعًا مِنْ لَحْمٍ وَدَمٍ وَعِظَامٍ وَأَعْصَابٍ وَعُرُوقٍ وَبَشَرٍ وَجِلْدٍ وَوَبَرٍ غَيْرَ أَنَّ الْبَهَائِمَ قَدْ صَارَتْ غِذَاءً لِلْإِنْسَانِ."And that is because the lawful animals — of cattle and sheep and camels and the like — are similar in creation to the forbidden predatory animals, both being of flesh and blood and bones and nerves and veins and skin and hide and fur; except that the lawful animals have become food for the human being."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingوذلك ان البهايم المحلله من البقر والغنم والابل وغير ذلك متماثله في الخلق هي والسباع المحرمه لكونهم جميعا من لحم ودم وعظام واعصاب وعروق وبشر وجلد ووبر غير ان البهايم قد صارت غذاء للانسان and that is because the lawful animals of cattle and sheep and camels and the like are similar in creation to the forbidden predatory animals both being of flesh and blood and bones and nerves and veins and skin and hide and fur except that the lawful animals have become food for the human being', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 44, NULL, 'The lawful animals — the cow, the sheep, the camel, and their kind — are identical in their outward creation to the forbidden beasts of prey, the siba. Both are flesh, blood, bones, nerves, veins, skin, hide, and fur; in their physical make there is no difference between them. And yet they are not the same, and the proof of the difference lies in how each stands toward man. The lawful animals have become food for the human being — for that human who is the caliph of God upon His earth. And so:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the lawful animals the cow the sheep the camel and their kind are identical in their outward creation to the forbidden beasts of prey the siba both are flesh blood bones nerves veins skin hide and fur in their physical make there is no difference between them and yet they are not the same and the proof of the difference lies in how each stands toward man the lawful animals have become food for the human being for that human who is the caliph of god upon his earth and so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 45, NULL, 'Sayingمُسْتَأْنِسَةً إِلَيْهِ سَائِرَةً إِلَى الصُّعُودِ وَالتَّرَقِّي فِي الصِّرَاطِ السَّوِيِّ الَّذِي هُوَ الشَّخْصُ الْبَشَرِيُّ قَرِيبَةً مِنَ الْمَبْدَإِ الْأَوَّلِ."Taking intimacy with him, proceeding toward ascent and progress upon the straight path, which is the human person, near to the first principle."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingمستانسه اليه سايره الي الصعود والترقي في الصراط السوي الذي هو الشخص البشري قريبه من المبدا الاول taking intimacy with him proceeding toward ascent and progress upon the straight path which is the human person near to the first principle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 46, NULL, 'The lawful animals take intimacy with man; they come close to him, become his food, and by becoming part of the human they proceed toward ascent and progress upon the straight path, the sirat al-sawiyy. And what is the straight path here? It is the human person himself — the sirat al-mustaqim is the bashari, the human form, which stands near to the first principle that is the origin and the return. The lawful animal, eaten and taken up into the human who is the caliph of God, ascends through him toward the source. The predatory animals are the reverse:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the lawful animals take intimacy with man they come close to him become his food and by becoming part of the human they proceed toward ascent and progress upon the straight path the sirat al sawiyy and what is the straight path here it is the human person himself the sirat al mustaqim is the bashari the human form which stands near to the first principle that is the origin and the return the lawful animal eaten and taken up into the human who is the caliph of god ascends through him toward the source the predatory animals are the reverse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 47, NULL, 'Sayingوَالسِّبَاعُ نَافِرَةٌ عَنِ الْإِنْسَانِ مُعَادِيَةٌ لَهُ سَائِرَةً فِي الِانْحِدَارِ سَائِرَةً إِلَى الْبُعْدِ الْأَبْعَدِ مِنَ الْمَبْدَإِ الْأَوَّلِ."And the predatory animals are averse to the human, hostile to him, proceeding in decline, proceeding to the furthest distance from the first principle."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingوالسباع نافره عن الانسان معاديه له سايره في الانحدار سايره الي البعد الابعد من المبدا الاول and the predatory animals are averse to the human hostile to him proceeding in decline proceeding to the furthest distance from the first principle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 48, NULL, 'The forbidden beasts of prey shy away from man and are hostile to him; they do not draw near to become his food and so they do not ascend through him, but proceed in decline, moving ever farther from the first principle. So although the two kinds of animal are made of one and the same stuff, the conclusion stands:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the forbidden beasts of prey shy away from man and are hostile to him they do not draw near to become his food and so they do not ascend through him but proceed in decline moving ever farther from the first principle so although the two kinds of animal are made of one and the same stuff the conclusion stands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 49, NULL, 'Sayingفَلَيْسُوا بِسَوَاءٍ فِي هَذِهِ الظَّوَاهِرِ وَالْخَلْقِ الْمُشْتَرَكِ وَكَذَلِكَ الطَّائِعُونَ وَالْعُصَاةُ وَالْبَاعِدُ أَبْعَدُ مِنْ ذَلِكَ."So they are not equal in these outward appearances and shared creation; and likewise the obedient and the disobedient — and the distance is greater still."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'sayingفليسوا بسواء في هذه الظواهر والخلق المشترك وكذلك الطايعون والعصاه والباعد ابعد من ذلك so they are not equal in these outward appearances and shared creation and likewise the obedient and the disobedient and the distance is greater still', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 50, NULL, 'They are not equal, for all their shared outward look and common creation. And it is just so with men. The lawful animal that ascends through its intimacy with man is like the Mukathir, the purified human who rises toward the first principle. The forbidden beast that flees man and falls away is like the man who declines. So among human beings the obedient — the muti, the tai — and the disobedient, the asi, though they too share one platform, one composition, one world, are separated by a distance greater even than the one that divides the two kinds of beast. One rises and one descends, and between them lies the whole interval between the first principle and the furthest distance from it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'they are not equal for all their shared outward look and common creation and it is just so with men the lawful animal that ascends through its intimacy with man is like the mukathir the purified human who rises toward the first principle the forbidden beast that flees man and falls away is like the man who declines so among human beings the obedient the muti the tai and the disobedient the asi though they too share one platform one composition one world are separated by a distance greater even than the one that divides the two kinds of beast one rises and one descends and between them lies the whole interval between the first principle and the furthest distance from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the nearest rank: breaking the self to climb', '5. The Nearest Rank: Breaking the Self to Climb', 51, NULL, 'The joining-stair has now been reached, where the highest human station opens onto the first of the spiritual ranks; what the Mukathir broke in himself to climb there, and what the man beside him failed to break, has been shown. The threshold is named, the ascent is named, the descent is named. What waits is the next of the ranks — and it can be reached only by the same road the Mukathir went: through the self, broken first.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 5 the nearest rank breaking the self to climb', 'the joining stair has now been reached where the highest human station opens onto the first of the spiritual ranks what the mukathir broke in himself to climb there and what the man beside him failed to break has been shown the threshold is named the ascent is named the descent is named what waits is the next of the ranks and it can be reached only by the same road the mukathir went through the self broken first', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 0, NULL, 'The man who broke himself at the threshold climbed, and what became of him after the climb is quieter and stranger than the climb itself. It concerns not what he gained but what he became. The soul of the مُكَثِّر — the one who has outstripped the others and stands at the summit of the human ranks — was changed by the road he traveled.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the man who broke himself at the threshold climbed and what became of him after the climb is quieter and stranger than the climb itself it concerns not what he gained but what he became the soul of the مكثر the one who has outstripped the others and stands at the summit of the human ranks was changed by the road he traveled', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 1, NULL, 'Sayingوَإِذَا كَانَ ذَلِكَ كَذَلِكَ فَإِنَّ نَفْسَ الْحَدِّ الَّذِي هُوَ الْمُكَاثِرُ قَدْ تَلَطَّفَتْ وَصَفَتْ وَعَلَتْ بِارْتِفَاعِ الصِّفَاتِ الْمَوْضُوعَةِ لَهَا وَعُلُوِّهِ، ثُمَّ اتَّصَلَ بِهَا مِنَ الْعُلُومِ الْإِلَهِيَّةِ وَالْأَسْرَارِ الْمَلَكُوتِيَّةِ مَا أَحْكَمَهَا صَفَاءً كُلِّيًّا وَأَلْطَفَهَا تَلْطِيفًا مَلَكُوتِيًّا وَصَبَغَهَا صِبْغَةً إِلَهِيَّةً وَأَشْرَقَهَا وَجَوْهَرَهَا وَأَشَفَّهَا"And since the matter is so, then the soul of the rank which is the Mukathir has become refined and pure and elevated through the elevation of its established attributes and its loftiness; then there connected with it, of the divine sciences and spiritual secrets, that which perfected it with a universal purity, and refined it with a spiritual refinement, and dyed it with a divine dye, and made it shine and clarified its essence and made it transparent."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingواذا كان ذلك كذلك فان نفس الحد الذي هو المكاثر قد تلطفت وصفت وعلت بارتفاع الصفات الموضوعه لها وعلوه ثم اتصل بها من العلوم الالهيه والاسرار الملكوتيه ما احكمها صفاء كليا والطفها تلطيفا ملكوتيا وصبغها صبغه الهيه واشرقها وجوهرها واشفها and since the matter is so then the soul of the rank which is the mukathir has become refined and pure and elevated through the elevation of its established attributes and its loftiness then there connected with it of the divine sciences and spiritual secrets that which perfected it with a universal purity and refined it with a spiritual refinement and dyed it with a divine dye and made it shine and clarified its essence and made it transparent', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 2, NULL, 'The soul in question is a particular one. Not some rarefied, separate faculty, but the sensory soul, the nafs hissi — the very part of him that sees and hears and feels its way through the world of bodies. Every person has one, and so does the مُكَثِّر. Yet the two are not the same soul. The ordinary person and the مُكَثِّر both carry a sensory soul, but the Mukathir''s has been worked upon. It has been made fine.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the soul in question is a particular one not some rarefied separate faculty but the sensory soul the nafs hissi the very part of him that sees and hears and feels its way through the world of bodies every person has one and so does the مكثر yet the two are not the same soul the ordinary person and the مكثر both carry a sensory soul but the mukathirs has been worked upon it has been made fine', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 3, NULL, 'The road made it so. He did not reach the summit in a single leap. He passed through the ten stations of the Mustajib, the one who first answers the call; then through the ten stations of the Mumin, the one who believes and is built up; and then through the degrees of the مُكَثِّر himself, however far he climbed. A soul does not pass through all of that unmarked. A long enough road enters whoever walks it, and from all of it his soul took on a subtlety it did not have at the start.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the road made it so he did not reach the summit in a single leap he passed through the ten stations of the mustajib the one who first answers the call then through the ten stations of the mumin the one who believes and is built up and then through the degrees of the مكثر himself however far he climbed a soul does not pass through all of that unmarked a long enough road enters whoever walks it and from all of it his soul took on a subtlety it did not have at the start', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 4, NULL, 'Then — and only then, onto a soul already made subtle — something connected. The divine sciences, the ulum ilahiyya, and the spiritual secrets, the asrar malakutiyya. These did not merely inform him; they finished him. They perfected the soul with a total purity, refined it with a spiritual refinement, dyed it through with a divine dye, and left it shining, clarified, transparent. He became, in effect, a man carrying a holy spirit — his sensory soul itself transmuted into something it was not born as.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'then and only then onto a soul already made subtle something connected the divine sciences the ulum ilahiyya and the spiritual secrets the asrar malakutiyya these did not merely inform him they finished him they perfected the soul with a total purity refined it with a spiritual refinement dyed it through with a divine dye and left it shining clarified transparent he became in effect a man carrying a holy spirit his sensory soul itself transmuted into something it was not born as', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 5, NULL, 'A question follows. If a refined soul is the signature of the مُكَثِّر, does it follow that any soul which seems refined belongs to a مُكَثِّر? It does not, because a person''s stations are hidden, known to God alone. Outwardly a man may look like a مُكَثِّر, and his soul may genuinely be refined, and still the formal designation is not one that any person may award. That naming belongs to God.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'a question follows if a refined soul is the signature of the مكثر does it follow that any soul which seems refined belongs to a مكثر it does not because a persons stations are hidden known to god alone outwardly a man may look like a مكثر and his soul may genuinely be refined and still the formal designation is not one that any person may award that naming belongs to god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 6, NULL, 'This does not dissolve into a fog where nothing can be said. The matter resolves from the side of justice. Justice demands this: if a soul has truly become pure, then that person has in fact become a مُكَثِّر. He will have passed the ten stations of the Mumin and reached the station of the مُكَثِّر, and his soul''s subtlety is the consequence of that ascent, not an accident of temperament. The subtlety need not be on display. The public title need never be conferred; the station rests with God. But where the purity of the soul is real, the rank is real — even if it is concealed from everyone but the One who made it so.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'this does not dissolve into a fog where nothing can be said the matter resolves from the side of justice justice demands this if a soul has truly become pure then that person has in fact become a مكثر he will have passed the ten stations of the mumin and reached the station of the مكثر and his souls subtlety is the consequence of that ascent not an accident of temperament the subtlety need not be on display the public title need never be conferred the station rests with god but where the purity of the soul is real the rank is real even if it is concealed from everyone but the one who made it so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 7, NULL, 'There is a precise and dangerous sense in which a higher rank becomes a god for the one beneath him, and that very danger, handled rightly, becomes the ladder of true Tawhid. The word "god" carries a sense here that is earned rather than assumed.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'there is a precise and dangerous sense in which a higher rank becomes a god for the one beneath him and that very danger handled rightly becomes the ladder of true tawhid the word god carries a sense here that is earned rather than assumed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 8, NULL, 'Sayingفَإِذَا قَابَلَهُ الْمُسْتَفِيدُ بِالصِّدْقِ وَصِحَّةِ النِّيَّةِ وَصَفَاءِ الطَّبِيعَةِ وَتَكَلَّمَ مَعَهُ وَأَفَادَهُ مِنَ الْكَلَامِ الْمَلَكُوتِيِّ وَالْعِلْمِ الْإِلَهِيِّ الَّذِي لَمْ يَكُنْ قَدْ خَطَرَ قَبْلَ ذَلِكَ بِبَالِهِ وَلَا ظُنَّ بِمَسَامِعِهِ قَطُّ وَلَا مَسَامِعِ أَمْثَالِهِ، حَارَ فِيهِ لُبُّهُ وَوَلَهَ، فَصَارَ لَهُ إِلَهًا مَالِكًا لِرِقِّهِ عَارِفًا بِدَلَالَتِهِ وَعَظِيمِ سَبْقَتِهِ"So when the seeker receives him with sincerity and soundness of intention and purity of nature, and speaks with him, and the Mukathir bestows upon him of the spiritual speech and the divine knowledge which had never before crossed his heart nor ever been suspected by his hearing or the hearing of his likes — his intellect is bewildered in it, and he is astounded, and the Mukathir becomes for him a god, a master of his neck, knowing of his guidance and his great precedence."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingفاذا قابله المستفيد بالصدق وصحه النيه وصفاء الطبيعه وتكلم معه وافاده من الكلام الملكوتي والعلم الالهي الذي لم يكن قد خطر قبل ذلك بباله ولا ظن بمسامعه قط ولا مسامع امثاله حار فيه لبه ووله فصار له الها مالكا لرقه عارفا بدلالته وعظيم سبقته so when the seeker receives him with sincerity and soundness of intention and purity of nature and speaks with him and the mukathir bestows upon him of the spiritual speech and the divine knowledge which had never before crossed his heart nor ever been suspected by his hearing or the hearing of his likes his intellect is bewildered in it and he is astounded and the mukathir becomes for him a god a master of his neck knowing of his guidance and his great precedence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 9, NULL, 'The scene is a room. A seeker comes — a mustafid, one who wants to receive — and he comes the only way that works: with sincerity, with soundness of intention, with a nature unclouded. He sits. He converses. The مُكَثِّر begins to give him the spiritual speech, al-kalam al-malakuti, and the divine knowledge — knowledge so high it had never once crossed the seeker''s heart. Not knowledge he had forgotten, but knowledge his ears had never suspected was there to hear, and not his ears alone: the ears of everyone like him. He had no category for it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the scene is a room a seeker comes a mustafid one who wants to receive and he comes the only way that works with sincerity with soundness of intention with a nature unclouded he sits he converses the مكثر begins to give him the spiritual speech al kalam al malakuti and the divine knowledge knowledge so high it had never once crossed the seekers heart not knowledge he had forgotten but knowledge his ears had never suspected was there to hear and not his ears alone the ears of everyone like him he had no category for it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 10, NULL, 'When a mind meets something it has no shelf to put it on, it reels. The seeker''s intellect — his lubb, the kernel of his understanding — is bewildered: hara. He is astounded: walaha. He cannot work out how this man came by such a station, how such matters could live inside a human being. In that bewilderment, the مُكَثِّر becomes for him a god — an ilah, a master of his neck, malik li-riqqihi — and he recognizes the man''s guidance and his great precedence on the road.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'when a mind meets something it has no shelf to put it on it reels the seekers intellect his lubb the kernel of his understanding is bewildered hara he is astounded walaha he cannot work out how this man came by such a station how such matters could live inside a human being in that bewilderment the مكثر becomes for him a god an ilah a master of his neck malik li riqqihi and he recognizes the mans guidance and his great precedence on the road', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 11, NULL, 'In what sense is the مُكَثِّر a "god"? It is the second of the two meanings of ilah. He is a god in the sense that he is the center of the circle. The image is a compass drawing a circle: the point in the middle does not move, and everything else moves only because the middle holds it in orbit. The disciple, dizzy with astonishment, begins to revolve around his teacher exactly as a circle revolves around its center. That revolving is his bewilderment; it has motion to it. In this sense alone — as the still point around which the staggered seeker circles — the مُكَثِّر is his "god."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'in what sense is the مكثر a god it is the second of the two meanings of ilah he is a god in the sense that he is the center of the circle the image is a compass drawing a circle the point in the middle does not move and everything else moves only because the middle holds it in orbit the disciple dizzy with astonishment begins to revolve around his teacher exactly as a circle revolves around its center that revolving is his bewilderment it has motion to it in this sense alone as the still point around which the staggered seeker circles the مكثر is his god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 12, NULL, 'It is emphatically not the other sense. He is not a creator of beings. The power to originate, the power of ibda (إبداع), was stripped from every one of the ranks at the very beginning; none of them makes anything from nothing. He is "god" only as the center of a bewildered orbit, and as the master who has hold of the seeker''s neck — not to keep it, but to release it — the one whose guidance and greatness and precedence the seeker has come, truly, to recognize.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'it is emphatically not the other sense he is not a creator of beings the power to originate the power of ibda ابداع was stripped from every one of the ranks at the very beginning none of them makes anything from nothing he is god only as the center of a bewildered orbit and as the master who has hold of the seekers neck not to keep it but to release it the one whose guidance and greatness and precedence the seeker has come truly to recognize', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 13, NULL, 'The seeker is now in orbit. But orbit is not the destination; it is the start of the lift. The bewilderment that made the teacher a "god" becomes the very engine that dethrones him.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the seeker is now in orbit but orbit is not the destination it is the start of the lift the bewilderment that made the teacher a god becomes the very engine that dethrones him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 14, NULL, 'Sayingفَإِذَا تَحَقَّقَ افْتِقَارَهُ إِلَى مَنْ فَوْقَهُ مِنَ الْحُدُودِ وَحَاجَتَهُ إِلَيْهِ وَافْتِقَارَ الَّذِي فَوْقَهُ... مُتَنَاهِيًا ذَلِكَ إِلَى الْإِمَامِ... وَمِنْهُ إِلَى مَنْ فَوْقَهُ مِنَ الْعُقُولِ الْمُجَرَّدَاتِ مُتَنَاهِيًا ذَلِكَ"And when he verifies the Mukathir''s need for the one above him among the ranks, and his poverty toward him, and the need of the one above him in turn... ending in that at the Imam... and from him toward the one above him among the abstract intellects, ending in that."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingفاذا تحقق افتقاره الي من فوقه من الحدود وحاجته اليه وافتقار الذي فوقه متناهيا ذلك الي الامام ومنه الي من فوقه من العقول المجردات متناهيا ذلك and when he verifies the mukathirs need for the one above him among the ranks and his poverty toward him and the need of the one above him in turn ending in that at the imam and from him toward the one above him among the abstract intellects ending in that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 15, NULL, 'The believing seeker, the mumin, comes to verify something he could not see while he was merely dazzled: the very man before whom he stands bewildered is himself bewildered before the rank above him. The seeker sees that he is poor toward the مُكَثِّر — and that the مُكَثِّر, in turn, is poor, needy, bewildered before his own mufid, the one who pours knowledge into him. And the one above the مُكَثِّر is bewildered before the one above him. The chain does not break. Rank upon rank, the same posture repeats, all the way up through the physical ranks, the حُدُود al-jismaniyya, until it reaches the Imam, peace be upon him.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the believing seeker the mumin comes to verify something he could not see while he was merely dazzled the very man before whom he stands bewildered is himself bewildered before the rank above him the seeker sees that he is poor toward the مكثر and that the مكثر in turn is poor needy bewildered before his own mufid the one who pours knowledge into him and the one above the مكثر is bewildered before the one above him the chain does not break rank upon rank the same posture repeats all the way up through the physical ranks the حدود al jismaniyya until it reaches the imam peace be upon him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 16, NULL, 'And from the Imam it does not stop. It climbs higher still, toward the abstract intellects — the uqul al-mujarradat, intellects that are not in the physical world at all, the angelic realities of the higher realms. The image is a sealed letter passing hand to hand: each bearer holds it, and each hands it on, and not one of them is the writer. The ascent runs up through these bearers until, at the very summit of the abstract intellects, it reaches the First Intellect — the Aql al-Awwal — which was itself bewildered before all the things originated and created: bewildered at how it came by its own precedence, when all of them were brought into being together, at one stroke, at one time.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'and from the imam it does not stop it climbs higher still toward the abstract intellects the uqul al mujarradat intellects that are not in the physical world at all the angelic realities of the higher realms the image is a sealed letter passing hand to hand each bearer holds it and each hands it on and not one of them is the writer the ascent runs up through these bearers until at the very summit of the abstract intellects it reaches the first intellect the aql al awwal which was itself bewildered before all the things originated and created bewildered at how it came by its own precedence when all of them were brought into being together at one stroke at one time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 17, NULL, 'Sayingثُمَّ تَحَقَّقَ وَلَهَهُ فِي مُبْدِعِهِ وَمُبْدِعِ أَجْنَاسِهِ وَحَيْرَتِهِ فِيهِ"Then he verifies its bewilderment at its Originator, and at the Originator of its kinds, and its perplexity in Him."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingثم تحقق ولهه في مبدعه ومبدع اجناسه وحيرته فيه then he verifies its bewilderment at its originator and at the originator of its kinds and its perplexity in him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 18, NULL, 'And then the last verification: the seeker confirms that even the First Intellect — the highest of all — is bewildered before its Originator, the mubdi, the One who originated it and originated every kind there is, and is perplexed before Him. So now the whole chain of bewilderment lies open, from the disciple staggering before the مُكَثِّر all the way up to the First Intellect staggering before God.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'and then the last verification the seeker confirms that even the first intellect the highest of all is bewildered before its originator the mubdi the one who originated it and originated every kind there is and is perplexed before him so now the whole chain of bewilderment lies open from the disciple staggering before the مكثر all the way up to the first intellect staggering before god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 19, NULL, 'The chain carries a lesson. If everyone on the ladder is bewildered, then bewilderment is not a failure but the condition of knowing. The first step in acquiring knowledge is the confession that one does not have it. A person must become, in a sense, ignorant first — must own his not-knowing — before anything can be poured in. This is why the station of bewilderment is necessary, for the دَاعِي who calls and for every seeker who answers. As the circle revolves around its center, so the seeker revolves in his perplexity, and that very revolving is the precondition of gnosis. The dizziness does not stand in the way of the knowledge; the dizziness is the door.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the chain carries a lesson if everyone on the ladder is bewildered then bewilderment is not a failure but the condition of knowing the first step in acquiring knowledge is the confession that one does not have it a person must become in a sense ignorant first must own his not knowing before anything can be poured in this is why the station of bewilderment is necessary for the داعي who calls and for every seeker who answers as the circle revolves around its center so the seeker revolves in his perplexity and that very revolving is the precondition of gnosis the dizziness does not stand in the way of the knowledge the dizziness is the door', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 20, NULL, 'Having traced the bewilderment to its source, the seeker performs the act the whole ascent was for.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'having traced the bewilderment to its source the seeker performs the act the whole ascent was for', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 21, NULL, 'Sayingنَفَى عَنْ حَدِّهِ الَّذِي هُوَ فِي أُفُقِهِ... وَأَثْبَتَهَا لِلَّهِ تَعَالَى وَتَكَبَّرَ، الَّذِي لَا إِلَهَ إِلَّا هُوَ"He negates it from his rank, which is in his horizon... and affirms it for Allah the Exalted, and proclaims His greatness — He besides whom there is no god."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingنفي عن حده الذي هو في افقه واثبتها لله تعالي وتكبر الذي لا اله الا هو he negates it from his rank which is in his horizon and affirms it for allah the exalted and proclaims his greatness he besides whom there is no god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 22, NULL, 'He negates divinity from the rank in his own horizon — that is, from the مُكَثِّر, the one nearest him, the one who dazzled him — and from every rank above the مُكَثِّر, physical and spiritual, all the way to the end of the chain. He says, in effect: not one of these gives me my being. Each of them is himself bewildered before another above him, and the highest of them, the First Intellect, is bewildered before the Originator. The exact condition the First Intellect held toward God — that posture of perplexity — the seeker now finds copied at every level, including his own dizziness before the مُكَثِّر. And so he affirms: this مُكَثِّر, for all his greatness and the genuine majesty of his station, which I have truly recognized and do not deny, is not my god. Above him is one, and above that one another, up to the summit, and every one of them is bewildered. The truly Real is the Originator alone — mubdi-e taala. He affirms divinity for God alone and proclaims His greatness, الَّذِي لَا إِلَهَ إِلَّا هُوَ — He besides whom there is no god.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'he negates divinity from the rank in his own horizon that is from the مكثر the one nearest him the one who dazzled him and from every rank above the مكثر physical and spiritual all the way to the end of the chain he says in effect not one of these gives me my being each of them is himself bewildered before another above him and the highest of them the first intellect is bewildered before the originator the exact condition the first intellect held toward god that posture of perplexity the seeker now finds copied at every level including his own dizziness before the مكثر and so he affirms this مكثر for all his greatness and the genuine majesty of his station which i have truly recognized and do not deny is not my god above him is one and above that one another up to the summit and every one of them is bewildered the truly real is the originator alone mubdi e taala he affirms divinity for god alone and proclaims his greatness الذي لا اله الا هو he besides whom there is no god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 23, NULL, 'The structure is one of linked circles. The مُكَثِّر has his circle. Above him is the circle of his mufid. Above that, another circle. And these circles are linked, one fastened to the next, ascending until the final circle, which is the First Intellect''s. The believer''s whole path of Tawhid runs along this linkage. First he confesses that the مُكَثِّر has become a god for him — meaning the center of his bewildered orbit. Then he verifies that the مُكَثِّر is himself in orbit around another, and so denies that the مُكَثِّر is his god in the absolute sense. And so on, up the linked circles, until he reaches the true God who stands beyond them all.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the structure is one of linked circles the مكثر has his circle above him is the circle of his mufid above that another circle and these circles are linked one fastened to the next ascending until the final circle which is the first intellects the believers whole path of tawhid runs along this linkage first he confesses that the مكثر has become a god for him meaning the center of his bewildered orbit then he verifies that the مكثر is himself in orbit around another and so denies that the مكثر is his god in the absolute sense and so on up the linked circles until he reaches the true god who stands beyond them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 24, NULL, 'How did these circles come to be linked at all? The answer lies back in the spiritual world, on the day the dawahs — the summonses — were first given there. When a call went out, those who joined it and repented with the very repentance of the one who called — tawabu bi-tawbatihi — rose with him; they went up with him. Those who did not join were given the call again, fresh. The pattern is exact. A circle has at its center a forerunner, a sabiq. He calls. Those who answer and repent with his repentance ascend alongside him. And the last individual left behind, the one who has not risen, is handed the command: Our work is finished; now you do the work. And with that, he becomes the center of a new circle. Others gather around him and repent with his repentance, and again the last one left is handed the command in his turn.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'how did these circles come to be linked at all the answer lies back in the spiritual world on the day the dawahs the summonses were first given there when a call went out those who joined it and repented with the very repentance of the one who called tawabu bi tawbatihi rose with him they went up with him those who did not join were given the call again fresh the pattern is exact a circle has at its center a forerunner a sabiq he calls those who answer and repent with his repentance ascend alongside him and the last individual left behind the one who has not risen is handed the command our work is finished now you do the work and with that he becomes the center of a new circle others gather around him and repent with his repentance and again the last one left is handed the command in his turn', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 25, NULL, 'That is how circle was generated from circle. The circle of the first person, then the circle of the Imam, then of the Bab, then of the Hujjat, and onward — each cast in the mold of the first. The pattern was set there, in the spiritual world, and every circle that came after was struck from it: the circle of the ashir, of Adam the summoner, of the Qaims, of the Dais, the Hujjats, the Imams, the circle of ain, the circle of mim — one after another, all on the one original die. And the bewilderment that orders each circle is just this: the center of any given circle, around whom others revolve, must himself revolve around the center of the circle above his own. He too is in orbit. The structure of bewildered revolution copies itself, top to bottom, the way a building''s load-bearing walls decide the shape of every floor above them. As the caller says, in effect, to the one he commands: you were formed by seeing us; now go and correct those below you. And all of this — every turn of it — is folded inside the single sentence, لَآ إِلَهَ إِلَّا ٱللَّهُ.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'that is how circle was generated from circle the circle of the first person then the circle of the imam then of the bab then of the hujjat and onward each cast in the mold of the first the pattern was set there in the spiritual world and every circle that came after was struck from it the circle of the ashir of adam the summoner of the qaims of the dais the hujjats the imams the circle of ain the circle of mim one after another all on the one original die and the bewilderment that orders each circle is just this the center of any given circle around whom others revolve must himself revolve around the center of the circle above his own he too is in orbit the structure of bewildered revolution copies itself top to bottom the way a buildings load bearing walls decide the shape of every floor above them as the caller says in effect to the one he commands you were formed by seeing us now go and correct those below you and all of this every turn of it is folded inside the single sentence لا اله الا الله', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 26, NULL, 'A striking reading of the word ilah itself follows. The three conditions present in every one of these circles are written into the three letters of the word. Ilah — إله — is alif, lam, ha. The alif shows precedence without an inspirer — sabqat without a mulhim: this is the First Intellect, the Aql al-Awwal, who outstripped all the rest by his own act, with no one above him to prompt or inspire him. The lam shows the condition of the second, one who advances not by his own independent precedence but by seeing another and repenting with his repentance — tawabu bi-tawbatihi: the station of the one emanated from the First, the munbaith min al-awwal, who reached his rank the way the second emanation reaches its rank, by following. The ha shows the third condition: the giving of the dawah, which was carried out by the seven intellects, the seven uqul — for the ashir, the tenth, did not give it. These three conditions — alif and lam and ha — are present in every single circle, because in every circle there is the whole. The entire story of the life of the universe is packed into this one composition. The station of the alif is the First Intellect; the station of the lam is the one emanated from the First; and the ha is the call given by the seven. So the very letters of "god" trace out the structure — forerunner, follower, summons — that builds every circle in the hierarchy.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'a striking reading of the word ilah itself follows the three conditions present in every one of these circles are written into the three letters of the word ilah اله is alif lam ha the alif shows precedence without an inspirer sabqat without a mulhim this is the first intellect the aql al awwal who outstripped all the rest by his own act with no one above him to prompt or inspire him the lam shows the condition of the second one who advances not by his own independent precedence but by seeing another and repenting with his repentance tawabu bi tawbatihi the station of the one emanated from the first the munbaith min al awwal who reached his rank the way the second emanation reaches its rank by following the ha shows the third condition the giving of the dawah which was carried out by the seven intellects the seven uqul for the ashir the tenth did not give it these three conditions alif and lam and ha are present in every single circle because in every circle there is the whole the entire story of the life of the universe is packed into this one composition the station of the alif is the first intellect the station of the lam is the one emanated from the first and the ha is the call given by the seven so the very letters of god trace out the structure forerunner follower summons that builds every circle in the hierarchy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 27, NULL, 'The act of affirmation is not yet finished. The seeker has named the true God; now he must say precisely what makes the false "gods" false.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the act of affirmation is not yet finished the seeker has named the true god now he must say precisely what makes the false gods false', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 28, NULL, 'Sayingوَأَثْبَتَهَا لِلَّهِ تَعَالَى وَتَكَبَّرَ، الَّذِي لَا إِلَهَ إِلَّا هُوَ مِنْ هَذِهِ الْآلِهَةِ الْمَخْلُوقَةِ وَالْمُخْتَرَعَةِ وَالْمُبْتَدَعَةِ، الشَّامِلِ لِكُلِّ وَاحِدٍ مِنْهُمُ اسْمُ الْمُرَبِّي الَّذِي فَوْقَهُ وَالْحَاجَةُ الدَّاعِيَةُ لَهُ إِلَيْهِ"And he affirmed it for Allah the Exalted and proclaimed His greatness — He besides whom there is no god from among these created, invented, and originated deities, each one of whom carries the name of the nourisher who is above him and the need that calls him toward him."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingواثبتها لله تعالي وتكبر الذي لا اله الا هو من هذه الالهه المخلوقه والمخترعه والمبتدعه الشامل لكل واحد منهم اسم المربي الذي فوقه والحاجه الداعيه له اليه and he affirmed it for allah the exalted and proclaimed his greatness he besides whom there is no god from among these created invented and originated deities each one of whom carries the name of the nourisher who is above him and the need that calls him toward him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 29, NULL, 'He affirms divinity for God and declares: there is no god from among these "deities" — these gods that are created, makhluqa; invented, mukhtaraa; originated, mubtadaa. And here is their telltale mark, the thing that gives every false god away. Each one carries inside himself the name of the nourisher above him — the murabbi — and the need that pulls him upward toward that nourisher. That is how a created god shows itself to be created: it is sustained by one above it, and driven by a hunger toward one above it. It is never self-sufficient. A thing that needs is a thing that was made.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'he affirms divinity for god and declares there is no god from among these deities these gods that are created makhluqa invented mukhtaraa originated mubtadaa and here is their telltale mark the thing that gives every false god away each one carries inside himself the name of the nourisher above him the murabbi and the need that pulls him upward toward that nourisher that is how a created god shows itself to be created it is sustained by one above it and driven by a hunger toward one above it it is never self sufficient a thing that needs is a thing that was made', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 30, NULL, 'Sayingإِلَّا مَنْ تَوَهَّمَتْ حَيْرَةُ عَالِيهِ وَدَانِيهِ عَلَى عُلُوِّ حَالَتِهِ', '', 'إِلَّا مَنْ تَوَهَّمَتْ حَيْرَةُ عَالِيهِ وَدَانِيهِ عَلَى عُلُوِّ حَالَتِهِ', 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingالا من توهمت حيره عاليه ودانيه علي علو حالته', 'الا من توهمت حيره عاليه ودانيه علي علو حالته');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 31, NULL, 'The only one who is not such a created god — the one with no nourisher above him and no upward-pulling need — is the one before whom the bewilderment of high and low alike is occasioned by the sheer loftiness of His state. Above Him there is nothing higher. Every subordinate is bewildered before Him; He is bewildered before none. And so:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the only one who is not such a created god the one with no nourisher above him and no upward pulling need is the one before whom the bewilderment of high and low alike is occasioned by the sheer loftiness of his state above him there is nothing higher every subordinate is bewildered before him he is bewildered before none and so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 32, NULL, 'Sayingفَلَا إِلَهَ سِوَاهُ، لَيْسَ ذَلِكَ جَبْرِيَّةً مِنْهُمْ، لَا يَجِدُ عَنْهَا مَحِيصًا"So there is no god besides Him. It is not a compulsion upon them; he finds no escape from it."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingفلا اله سواه ليس ذلك جبريه منهم لا يجد عنها محيصا so there is no god besides him it is not a compulsion upon them he finds no escape from it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 33, NULL, 'There is no god besides that one Being. And the seeker''s affirmation of Him is not a mere helpless reflex — and yet, in a way, it is forced: the helpless servant finds no escape, no muhas, from having to address Him somehow. He cannot not name Him. But the affirmation of His sole divinity is not therefore empty compulsion; it is the truth the entire ascent has just demonstrated, step by step, circle by circle.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'there is no god besides that one being and the seekers affirmation of him is not a mere helpless reflex and yet in a way it is forced the helpless servant finds no escape no muhas from having to address him somehow he cannot not name him but the affirmation of his sole divinity is not therefore empty compulsion it is the truth the entire ascent has just demonstrated step by step circle by circle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 34, NULL, 'The threefold movement completes itself at the highest level. First, transcendence:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the threefold movement completes itself at the highest level first transcendence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 35, NULL, 'Sayingثُمَّ نَزَّهَهُ تَعَالَى وَتَكَبَّرَ عَنِ الْحُدُودِ الْجِسْمَانِيَّةِ الْمَحْدُودَةِ وَعَنِ الْحُدُودِ الرُّوحَانِيَّةِ غَيْرِ الْمَحْدُودَةِ"Then he declared Him transcendent and proclaimed His greatness above the limited physical ranks and above the unlimited spiritual ranks."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingثم نزهه تعالي وتكبر عن الحدود الجسمانيه المحدوده وعن الحدود الروحانيه غير المحدوده then he declared him transcendent and proclaimed his greatness above the limited physical ranks and above the unlimited spiritual ranks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 36, NULL, 'This is تَنْزِيه in full. The seeker declares the one God transcendent above the physical ranks, which are limited, mahduda, and above the spiritual ranks, which are unlimited, ghayr mahduda — because the true God, the nourisher of all, is beyond both hierarchies, the bounded corporeal one and the unbounded spiritual one alike. Then comes the stripping, تَجْرِيد:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'this is تنزيه in full the seeker declares the one god transcendent above the physical ranks which are limited mahduda and above the spiritual ranks which are unlimited ghayr mahduda because the true god the nourisher of all is beyond both hierarchies the bounded corporeal one and the unbounded spiritual one alike then comes the stripping تجريد', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 37, NULL, 'Sayingثُمَّ سَلَبَهُ تَعَالَى مَا أَثْبَتَهُ لَهُمْ مِنَ الْأَسْمَاءِ وَالصِّفَاتِ وَالنُّعُوتِ وَالْإِضَافَاتِ"Then he stripped from Him the names and attributes and descriptions and relations that he had affirmed for them."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingثم سلبه تعالي ما اثبته لهم من الاسماء والصفات والنعوت والاضافات then he stripped from him the names and attributes and descriptions and relations that he had affirmed for them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 38, NULL, 'He strips from the Originator, mubdi-e taala, all the names, attributes, descriptions — the nuut — and relations — the idafat — that he had affirmed for the ranks. Those names and attributes belong to the physical and spiritual ranks. The Originator is beyond them, for He is God in the absolute sense, divested of everything that can be predicated of anything. And finally, the return:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'he strips from the originator mubdi e taala all the names attributes descriptions the nuut and relations the idafat that he had affirmed for the ranks those names and attributes belong to the physical and spiritual ranks the originator is beyond them for he is god in the absolute sense divested of everything that can be predicated of anything and finally the return', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 39, NULL, 'Sayingوَعَادَ إِلَى حَدِّهِ وَوَلَهِهِ فِيهِ وَطَاعَتِهِ"And he returns to his own rank, and to his bewilderment in it, and to his obedience."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingوعاد الي حده وولهه فيه وطاعته and he returns to his own rank and to his bewilderment in it and to his obedience', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 40, NULL, 'After the whole sweep of affirming and negating, the seeker comes back. The mumin is bewildered before the مُكَثِّر; above the مُكَثِّر are ranks, and ranks above those, up to the First Intellect, which is itself bewildered before another — and having traced all of it, the seeker returns and says, in effect: each must do his own work, and I will do mine. He comes back down to his own station, to his bewilderment within it, to his obedience and his commitment to his مُكَثِّر. And it is precisely at that moment — not on the way up, but on the way back, settled in his own place — that he becomes the one who performs true Tawhid, true تَنْزِيه, true تَجْرِيد: with gnosis, marifat; with religion, din; with knowledge, ilm; and with certainty, yaqin.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'after the whole sweep of affirming and negating the seeker comes back the mumin is bewildered before the مكثر above the مكثر are ranks and ranks above those up to the first intellect which is itself bewildered before another and having traced all of it the seeker returns and says in effect each must do his own work and i will do mine he comes back down to his own station to his bewilderment within it to his obedience and his commitment to his مكثر and it is precisely at that moment not on the way up but on the way back settled in his own place that he becomes the one who performs true tawhid true تنزيه true تجريد with gnosis marifat with religion din with knowledge ilm and with certainty yaqin', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 41, NULL, 'And to a soul like that, God speaks:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'and to a soul like that god speaks', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 42, NULL, 'Sayingيَا أَيَّتُهَا النَّفْسُ الْمُطْمَئِنَّةُ ارْجِعِي إِلَىٰ رَبِّكِ رَاضِيَةً مَّرْضِيَّةً"O tranquil soul, return to your Lord, well-pleased and well-pleasing."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingيا ايتها النفس المطمينه ارجعي الي ربك راضيه مرضيه o tranquil soul return to your lord well pleased and well pleasing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 43, NULL, 'The crucial word is irjii — return. The soul went all the way to the top and now comes back. That is the whole shape of it: up, and then down. "Return to your Lord" means a return to the soul''s mufid, the one who bestowed upon it. And "well-pleased and well-pleasing," radiyatan mardiyya, means both at once: the soul itself content, and its mufid content with it — the pleasure running in both directions. The text unfolds the verse further:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the crucial word is irjii return the soul went all the way to the top and now comes back that is the whole shape of it up and then down return to your lord means a return to the souls mufid the one who bestowed upon it and well pleased and well pleasing radiyatan mardiyya means both at once the soul itself content and its mufid content with it the pleasure running in both directions the text unfolds the verse further', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 44, NULL, 'Sayingاطْمِئْنَانُهَا بِمَا عَرَفَتْ... وَمَرْضَاتُهَا بِأَمْرِ رَبِّهَا الَّذِي إِلَيْهِ يُرْجَعُ، مَرْضِيَّةً عِنْدَهُ... الَّذِينَ إِلَى مَعْرِفَتِهِمُ انْتَهَى وَبَلَغَ', '', 'اطْمِئْنَانُهَا بِمَا عَرَفَتْ... وَمَرْضَاتُهَا بِأَمْرِ رَبِّهَا الَّذِي إِلَيْهِ يُرْجَعُ، مَرْضِيَّةً عِنْدَهُ... الَّذِينَ إِلَى مَعْرِفَتِهِمُ انْتَهَى وَبَلَغَ', 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingاطمينانها بما عرفت ومرضاتها بامر ربها الذي اليه يرجع مرضيه عنده الذين الي معرفتهم انتهي وبلغ', 'اطمينانها بما عرفت ومرضاتها بامر ربها الذي اليه يرجع مرضيه عنده الذين الي معرفتهم انتهي وبلغ');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 45, NULL, 'The soul''s tranquility, its itminan, lies in what it has come to know — its serenity is the fruit of its gnosis, not of comfort or rest. And its pleasure lies in the command of its Lord, the Lord to whom it is returned. And it is well-pleasing, mardiyya, in His sight — and in the sight of every rank whose gnosis the soul reached and arrived at along the way. And the author closes this movement on his knees:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the souls tranquility its itminan lies in what it has come to know its serenity is the fruit of its gnosis not of comfort or rest and its pleasure lies in the command of its lord the lord to whom it is returned and it is well pleasing mardiyya in his sight and in the sight of every rank whose gnosis the soul reached and arrived at along the way and the author closes this movement on his knees', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 46, NULL, 'الْحَمْدُ لِلَّهِ الَّذِي هَدَانَا لِهَٰذَا وَمَا كُنَّا لِنَهْتَدِيَ لَوْلَا أَنْ هَدَانَا اللَّهُ ۖ لَقَدْ جَاءَتْ رُسُلُ رَبِّنَا بِالْحَقِّ"And praise be to Allah who guided us to this; we would not have been guided had Allah not guided us. Indeed the messengers of our Lord came with the truth."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'الحمد لله الذي هدانا لهذا وما كنا لنهتدي لولا ان هدانا الله لقد جاءت رسل ربنا بالحق and praise be to allah who guided us to this we would not have been guided had allah not guided us indeed the messengers of our lord came with the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 47, NULL, 'The tranquil soul, having reached the end of the gnosis of its mufid, is called home to its Lord, pleased and pleasing both; and the praise belongs to God, who guided to this gnosis a soul that could never have found the way on its own, and whose messengers came carrying the truth.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'the tranquil soul having reached the end of the gnosis of its mufid is called home to its lord pleased and pleasing both and the praise belongs to god who guided to this gnosis a soul that could never have found the way on its own and whose messengers came carrying the truth', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 48, NULL, 'A question naturally arises: whether any of this is in the Book. This Originator who created; this whole world of souls; the linked circles and the ascent and the return — is there any mention of it in the Quran that is recited, in the verses, in the supplications that are made? There is. The matter is conveyed in different phrases in different places — as in the verse that speaks of creation مِّن نَّفْسٍ وَاحِدَةٍ, from a single soul. But the summary of everything the Quran teaches about the Originator is Surah al-Fatiha — Surah al-Hamd. And its details, as Sayyidna has explained, all stand on the opening verse:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'a question naturally arises whether any of this is in the book this originator who created this whole world of souls the linked circles and the ascent and the return is there any mention of it in the quran that is recited in the verses in the supplications that are made there is the matter is conveyed in different phrases in different places as in the verse that speaks of creation من نفس واحده from a single soul but the summary of everything the quran teaches about the originator is surah al fatiha surah al hamd and its details as sayyidna has explained all stand on the opening verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 49, NULL, 'الْحَمْدُ لِلَّهِ رَبِّ الْعَالَمِينَ"Praise be to Allah, Lord of the worlds."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'الحمد لله رب العالمين praise be to allah lord of the worlds', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 50, NULL, 'For He is Rabb al-Alamin, the Lord of all the worlds, and the qualities of God unfold out of this one verse. Every detail is built upon it — the full working stands in Kitab al-Alim wa al-Ghulam, the Book of the Master and the Disciple; whoever reads it will understand. So the matter is there, in supplication and in the Quran alike, its summary held in al-Fatiha, within which the duat have unpacked the whole teaching.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'for he is rabb al alamin the lord of all the worlds and the qualities of god unfold out of this one verse every detail is built upon it the full working stands in kitab al alim wa al ghulam the book of the master and the disciple whoever reads it will understand so the matter is there in supplication and in the quran alike its summary held in al fatiha within which the duat have unpacked the whole teaching', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 51, NULL, 'And the Fatiha holds more — it holds the three kinds of people. The دَاعِي teaches that God made three classes: the repentant, then those who incur wrath, then the astray. They stand in the verse:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'and the fatiha holds more it holds the three kinds of people the داعي teaches that god made three classes the repentant then those who incur wrath then the astray they stand in the verse', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 52, NULL, 'Sayingاهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ ۝ صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ"Guide us upon the straight path, the path of those upon whom You have bestowed favor."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingاهدنا الصراط المستقيم صراط الذين انعمت عليهم guide us upon the straight path the path of those upon whom you have bestowed favor', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 53, NULL, 'Those upon whom favor was bestowed, anamta alayhim, are the nadimin, the repentant — and the favor given them was precisely that they were granted to return. Then the verse turns:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'those upon whom favor was bestowed anamta alayhim are the nadimin the repentant and the favor given them was precisely that they were granted to return then the verse turns', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 54, NULL, 'غَيْرِ الْمَغْضُوبِ عَلَيْهِمْ"not of those upon whom is wrath."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'غير المغضوب عليهم not of those upon whom is wrath', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 55, NULL, 'And who are the maghdub, those wrath has fallen on? The insistent ones — the musirrin — who dig in and persist in their error, and so the wrath comes down on them. And the third:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'and who are the maghdub those wrath has fallen on the insistent ones the musirrin who dig in and persist in their error and so the wrath comes down on them and the third', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 56, NULL, 'وَلَا الضَّالِّينَ"nor of the astray."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'ولا الضالين nor of the astray', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 57, NULL, 'These are the bewildered, the mutahayyirin — the ones lost in perplexity who never found their way through it. So the sirat, the path that has to be crossed, is laid before three classes: the nadimin, favored to return; the musirrin, who earn wrath by their insistence; and the mutahayyirin, who go astray in a bewilderment that never resolved. The Originator''s making of beings, and the details of that making in the world of the physical body, have come down in His pure speech, revealed to the people of the world.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'these are the bewildered the mutahayyirin the ones lost in perplexity who never found their way through it so the sirat the path that has to be crossed is laid before three classes the nadimin favored to return the musirrin who earn wrath by their insistence and the mutahayyirin who go astray in a bewilderment that never resolved the originators making of beings and the details of that making in the world of the physical body have come down in his pure speech revealed to the people of the world', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 58, NULL, 'But there is one thing the Quran gives that is not an answer at all — it is a wall. The reality of the Originator Himself cannot be grasped, and the Book says so:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'but there is one thing the quran gives that is not an answer at all it is a wall the reality of the originator himself cannot be grasped and the book says so', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 59, NULL, 'Sayingسُبْحَانَ الَّذِي... سُبْحَانَ اللَّهِ عَمَّا يَصِفُونَ"Glory be to Him... Glory be to Allah, above what they describe."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'sayingسبحان الذي سبحان الله عما يصفون glory be to him glory be to allah above what they describe', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 60, NULL, 'God is pure above whatever attributes are pinned on Him; His reality cannot be understood; He Himself cannot be comprehended. This stands in many places in the Quran, and from it the conclusion is proven: the reality of God cannot be reached. Amma yasifun — above what they describe — means that whatever attribute is set down for Him, He is pure of it, beyond it, clear of it. This is the very meaning of تَنْزِيه: that whatever the bewildered seekers ascribe to Him — bewildered precisely because they cannot reach His full gnosis — He transcends it. And this incapacity does not stop short of the top. Even the First Intellect, their own mufid, the highest of the made things, was incapable of the gnosis of the Originator. Ajiz. The First Intellect did not possess the gnosis of mubdi-e taala; it stood bewildered before Him — and it was on account of that very bewilderment that the First Intellect became a god for those below it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'god is pure above whatever attributes are pinned on him his reality cannot be understood he himself cannot be comprehended this stands in many places in the quran and from it the conclusion is proven the reality of god cannot be reached amma yasifun above what they describe means that whatever attribute is set down for him he is pure of it beyond it clear of it this is the very meaning of تنزيه that whatever the bewildered seekers ascribe to him bewildered precisely because they cannot reach his full gnosis he transcends it and this incapacity does not stop short of the top even the first intellect their own mufid the highest of the made things was incapable of the gnosis of the originator ajiz the first intellect did not possess the gnosis of mubdi e taala it stood bewildered before him and it was on account of that very bewilderment that the first intellect became a god for those below it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 61, NULL, 'So what word did they finally settle on for the Originator, when no description would hold? One word. Hu. He. And even that under compulsion, because they had nothing else — no other word that would not falsely draw a circle around Him. The naming itself is a zanbun mashfuun bil-istighfar, a sin coupled with its own plea for forgiveness, uttered only out of necessity. For to prove one''s own existence one is forced to affirm the existence of the Existent; and to affirm Him one is forced to call Him something; and the only word that does not lie about Him by hemming Him in is Hu — He.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'so what word did they finally settle on for the originator when no description would hold one word hu he and even that under compulsion because they had nothing else no other word that would not falsely draw a circle around him the naming itself is a zanbun mashfuun bil istighfar a sin coupled with its own plea for forgiveness uttered only out of necessity for to prove ones own existence one is forced to affirm the existence of the existent and to affirm him one is forced to call him something and the only word that does not lie about him by hemming him in is hu he', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'every teacher a threshold, not a god', '6. Every Teacher a Threshold, Not a God', 62, NULL, 'So the seeker has done the full circuit. He climbed from his own dizziness before the teacher up through every linked circle to the First Intellect, found even that summit dizzy before God, named God by the one word that does not cage Him, and came back down to his own rank to do his own work. He knows now what a "god" is and what it is not — center of an orbit, never the maker of being. He has the structure whole. But knowing the structure of the worlds is not the same as standing inside the next of its ranks and feeling its particular weight. The first of the spiritual ranks has been named, and a soul has been watched crossing into it. The road does not stop at the naming. It runs on, into that rank itself — and it can be followed only by the road already laid: through the broken self, up the circles, and back.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 6 every teacher a threshold not a god', 'so the seeker has done the full circuit he climbed from his own dizziness before the teacher up through every linked circle to the first intellect found even that summit dizzy before god named god by the one word that does not cage him and came back down to his own rank to do his own work he knows now what a god is and what it is not center of an orbit never the maker of being he has the structure whole but knowing the structure of the worlds is not the same as standing inside the next of its ranks and feeling its particular weight the first of the spiritual ranks has been named and a soul has been watched crossing into it the road does not stop at the naming it runs on into that rank itself and it can be followed only by the road already laid through the broken self up the circles and back', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 0, NULL, 'The promised road runs on, and now it turns back behind the ranks themselves to ask after the act that made them. Before there was a first of the spiritual ranks for a soul to cross into, before there was any rank at all, there was an origination — a bringing-into-being out of which the ranks, the worlds, and the souls of all people came. That act is where the road turns now, drawing on a long exposition by Sayyidna Mohyuddin, whose argument follows here in summary, its bones kept whole — beginning where he begins, with the Name and then with the ground:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'the promised road runs on and now it turns back behind the ranks themselves to ask after the act that made them before there was a first of the spiritual ranks for a soul to cross into before there was any rank at all there was an origination a bringing into being out of which the ranks the worlds and the souls of all people came that act is where the road turns now drawing on a long exposition by sayyidna mohyuddin whose argument follows here in summary its bones kept whole beginning where he begins with the name and then with the ground', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 1, NULL, 'Sayingإِنَّ اللَّهَ تَعَالَى الَّذِي لَا تَتَجَاسَرُ نَحْوَهُ الْخَوَاطِرُ وَلَا تَسْمُو إِلَيْهِ الْأَوْهَامُ وَالضَّمَائِرُ، أَبْدَعَ عَالَمَ الْإِبْدَاعِ الْمُكَنَّى عَنْهُ بِعَالَمِ الْأَمْرِ وَعَالَمِ الْعَقْلِ وَعَالَمِ الْقُدْسِ وَعَالَمِ الصَّفَاءِ وَعَالَمِ اللَّطَافَةِ وَبِالْعَالَمِ الرُّوحَانِيِّ دَفْعَةً وَاحِدَةً مِنْ غَيْرِ شَيْءٍ تَقَدَّمَهُمْ فَيَكُونَ لَهُمْ هَيُولَى أُولَى وَلَا مَعَ شَيْءٍ صَاحَبَهُمْ فَيَكُونَ مُمَاثِلًا لَهُمْ وَمُشَاكِلًا وَلَا عَلَى شَيْءٍ أَقَلَّهُمْ فَيَكُونَ لَهُمْ مَكَانًا أَوَّلًا."Indeed Allah the Exalted, toward whom the passing thoughts dare not turn, and toward whom imaginations and the inmost selves cannot rise, originated the world of origination — which is alluded to as the world of command, the world of intellect, the world of sanctity, the world of purity, the world of subtlety, and the spiritual world — in a single instant: not from any thing preceding them that would be a prior matter for them, nor with any thing accompanying them that would be similar and like to them, nor upon any thing bearing them that would be a first place for them."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingان الله تعالي الذي لا تتجاسر نحوه الخواطر ولا تسمو اليه الاوهام والضماير ابدع عالم الابداع المكني عنه بعالم الامر وعالم العقل وعالم القدس وعالم الصفاء وعالم اللطافه وبالعالم الروحاني دفعه واحده من غير شيء تقدمهم فيكون لهم هيولي اولي ولا مع شيء صاحبهم فيكون مماثلا لهم ومشاكلا ولا علي شيء اقلهم فيكون لهم مكانا اولا indeed allah the exalted toward whom the passing thoughts dare not turn and toward whom imaginations and the inmost selves cannot rise originated the world of origination which is alluded to as the world of command the world of intellect the world of sanctity the world of purity the world of subtlety and the spiritual world in a single instant not from any thing preceding them that would be a prior matter for them nor with any thing accompanying them that would be similar and like to them nor upon any thing bearing them that would be a first place for them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 2, NULL, 'The first clause deserves weight before the rest. He is a Being toward whom the passing thoughts — the khawatir, the fleeting motions that cross a mind unbidden — dare not even turn. And the imaginations, the awham (أوهام), together with the zamair, the inmost folds of the self where a person is most privately himself, cannot rise toward Him, cannot grow lofty enough to reach Him. The attempt shows what happens: a thought sets out and falls back; the inmost self reaches up and sinks down. Neither the outward instrument nor the secret one can climb to Him. That is the One in question — and it is this One who originated the world of origination, the alam al-ibda (عالم الإبداع).', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'the first clause deserves weight before the rest he is a being toward whom the passing thoughts the khawatir the fleeting motions that cross a mind unbidden dare not even turn and the imaginations the awham اوهام together with the zamair the inmost folds of the self where a person is most privately himself cannot rise toward him cannot grow lofty enough to reach him the attempt shows what happens a thought sets out and falls back the inmost self reaches up and sinks down neither the outward instrument nor the secret one can climb to him that is the one in question and it is this one who originated the world of origination the alam al ibda عالم الابداع', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 3, NULL, 'This one originated realm wears a cluster of names. He calls it the world of command, the world of intellect, the world of sanctity, the world of purity, the world of subtlety, and the spiritual world — six titles laid beside the name alam al-ibda itself, seven names in all for a single thing. The crowd of names is not seven realms. There is one realm here, seen from seven sides.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'this one originated realm wears a cluster of names he calls it the world of command the world of intellect the world of sanctity the world of purity the world of subtlety and the spiritual world six titles laid beside the name alam al ibda itself seven names in all for a single thing the crowd of names is not seven realms there is one realm here seen from seven sides', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 4, NULL, 'One word governs everything that follows: ibda (إبداع), origination, which is not the same as khalq, creation. Ordinary speech uses both loosely, but here they part ways sharply. Khalq, creation, is what happens when what already exists is rearranged. A thing already present is broken, reshaped, recombined, and a new composite form is brought out of it — the form is altered, but a matter is presupposed underneath. The potter creates the jar, yet the clay was waiting in his hands. That is khalq: form changed upon matter already given. Ibda is something else entirely. Ibda is origination from nothing, where no prior thing exists at all — no clay, no hands worth of waiting stuff, nothing. And the world in question is created by ibda in exactly this strict sense.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'one word governs everything that follows ibda ابداع origination which is not the same as khalq creation ordinary speech uses both loosely but here they part ways sharply khalq creation is what happens when what already exists is rearranged a thing already present is broken reshaped recombined and a new composite form is brought out of it the form is altered but a matter is presupposed underneath the potter creates the jar yet the clay was waiting in his hands that is khalq form changed upon matter already given ibda is something else entirely ibda is origination from nothing where no prior thing exists at all no clay no hands worth of waiting stuff nothing and the world in question is created by ibda in exactly this strict sense', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 5, NULL, 'That is why Mohyuddin does not merely assert it but seals it with three denials, each meant to land. First: it was originated not from any thing that preceded it. There was no prior substance lying ready to serve as its hayula — its prime matter, the first leaven a baker folds his dough from. Second: it was originated not with any accompanying thing. There was no co-present matter standing alongside it, nothing it could be shaped to match, nothing it could resemble or take after. Third: it was originated not upon any thing bearing it. There was no underlying floor, no substrate to be its makan, its first place, the location a thing rests upon. No matter before it, no matter beside it, no place beneath it. With all three stripped away, what is left is ibda in its purity: the world of origination brought forth in a single instant — dafatan wahidatan — out of nothing whatsoever.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'that is why mohyuddin does not merely assert it but seals it with three denials each meant to land first it was originated not from any thing that preceded it there was no prior substance lying ready to serve as its hayula its prime matter the first leaven a baker folds his dough from second it was originated not with any accompanying thing there was no co present matter standing alongside it nothing it could be shaped to match nothing it could resemble or take after third it was originated not upon any thing bearing it there was no underlying floor no substrate to be its makan its first place the location a thing rests upon no matter before it no matter beside it no place beneath it with all three stripped away what is left is ibda in its purity the world of origination brought forth in a single instant dafatan wahidatan out of nothing whatsoever', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 6, NULL, 'Here a question arises that cannot be set aside. If He needed nothing and used nothing, why originate at all? Mohyuddin gives the answer plainly:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'here a question arises that cannot be set aside if he needed nothing and used nothing why originate at all mohyuddin gives the answer plainly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 7, NULL, 'Sayingوَاخْتَرَعَهُمْ عَالَمًا، وُجُودًا مِنْ عَدَمٍ غَيْرِ مَوْجُودٍ، تَفَضُّلًا مِنْهُ وَجُودًا وَتَطَوُّلًا مِنْهُ."And He originated them as a world — existence from a non-existent nothingness — as a favor from Him, and generosity, and bestowal from Him."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingواخترعهم عالما وجودا من عدم غير موجود تفضلا منه وجودا وتطولا منه and he originated them as a world existence from a non existent nothingness as a favor from him and generosity and bestowal from him', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 8, NULL, 'He originated the existents — ikhtaraa — and drew them up into a world of existence, pulling them out of an adam (عَدَم), a nothingness, that was not itself existent. Against this a picture must be guarded, one the mind will try to paint. Adam is not some shadowy realm, a dim warehouse of the not-yet-made. It is no realm and no place. It is simply the absence of being — the bare fact that a thing is not. A teacher in Sindh once turned to his students and asked them: when all this was taking place, where were we? The question is the whole lesson. There was no "where." There was nothing but non-existence, and it is out of that nothing that all things were drawn. The warehouse falls away: before being, there is no place anything was waiting in; there is only the not.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'he originated the existents ikhtaraa and drew them up into a world of existence pulling them out of an adam عدم a nothingness that was not itself existent against this a picture must be guarded one the mind will try to paint adam is not some shadowy realm a dim warehouse of the not yet made it is no realm and no place it is simply the absence of being the bare fact that a thing is not a teacher in sindh once turned to his students and asked them when all this was taking place where were we the question is the whole lesson there was no where there was nothing but non existence and it is out of that nothing that all things were drawn the warehouse falls away before being there is no place anything was waiting in there is only the not', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 9, NULL, 'And the cause of it all was not need and not compulsion but pure favor. Tafaddulan minhu — a favor from Him. Wa judan — and generosity, a free gift. Wa tatawwulan minhu — and a bestowal, an unowed boon. On this single point — why the Originator originated — Mohyuddin does not write a line and move on. He writes chapter after chapter, and what he does in them is patient and almost relentless: he takes up every supposed purpose, every conceivable need or motive one might attribute to the act, and he negates it, one after another, refusing each in turn, until only one thing is left standing. The favor itself was the only "purpose." He originated out of sheer favor, generosity, and bestowal, and out of nothing besides. He grounds it like this:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'and the cause of it all was not need and not compulsion but pure favor tafaddulan minhu a favor from him wa judan and generosity a free gift wa tatawwulan minhu and a bestowal an unowed boon on this single point why the originator originated mohyuddin does not write a line and move on he writes chapter after chapter and what he does in them is patient and almost relentless he takes up every supposed purpose every conceivable need or motive one might attribute to the act and he negates it one after another refusing each in turn until only one thing is left standing the favor itself was the only purpose he originated out of sheer favor generosity and bestowal and out of nothing besides he grounds it like this', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 10, NULL, 'Sayingإِذْ مِنْ شِيمَةِ الْكَرِيمِ الْقَادِرِ التَّفَضُّلُ، وَمِنْ سَجِيَّةِ الْعَزِيزِ الْعَظِيمِ الْجُودُ، لَا مُحْتَاجًا إِلَيْهِمْ وَلَا عَابِثًا بِهِمْ، إِذْ هُوَ مُتَعَالٍ مُتَكَبِّرٌ عَنْ ذَلِكَ."Since it is of the nature of the Generous, the Powerful, to bestow favor, and of the nature of the Mighty, the Great, to be generous — not needing them nor playing with them, since He is exalted and transcendent above that."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingاذ من شيمه الكريم القادر التفضل ومن سجيه العزيز العظيم الجود لا محتاجا اليهم ولا عابثا بهم اذ هو متعال متكبر عن ذلك since it is of the nature of the generous the powerful to bestow favor and of the nature of the mighty the great to be generous not needing them nor playing with them since he is exalted and transcendent above that', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 11, NULL, 'It belongs to the very shimah, the ingrained nature, of the Generous and the Powerful to bestow favor; it belongs to the very sajiyyah, the inborn disposition, of the Mighty and the Great to give and to give freely. So He brought the existents into being — and here two errors fall away together. Not because He needed them: the Giver had no need of the given, none at all. And not as idle sport: He was not amusing Himself with them, not making them to pass an eternity, for He is exalted and transcendent far above any such thing. The origination simply flowed from the bestowing nature of the Generous and Mighty, with no need driving it and no frivolity staining it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'it belongs to the very shimah the ingrained nature of the generous and the powerful to bestow favor it belongs to the very sajiyyah the inborn disposition of the mighty and the great to give and to give freely so he brought the existents into being and here two errors fall away together not because he needed them the giver had no need of the given none at all and not as idle sport he was not amusing himself with them not making them to pass an eternity for he is exalted and transcendent far above any such thing the origination simply flowed from the bestowing nature of the generous and mighty with no need driving it and no frivolity staining it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 12, NULL, 'What remains is how the originated beings came forth — in what shape, of what stature. He says:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'what remains is how the originated beings came forth in what shape of what stature he says', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 13, NULL, 'Sayingأَوْجَدَهُمْ أَشْبَاحًا صُورِيَّةً مَحْضَةً نُورَانِيَّةً، ذَوَاتِ قَامَةٍ أَلْفِيَّةٍ كَالْقَامَةِ الْإِنْسَانِيَّةِ الْبَشَرِيَّةِ، مُبَايِنَةً لِأَنْفُسِهِمُ الْهَيُولَانِيَّةِ."He brought them into existence as forms, purely imaginal and luminous, possessing thousand-fold statures like the human, corporeal statures, distinct from their material souls."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingاوجدهم اشباحا صوريه محضه نورانيه ذوات قامه الفيه كالقامه الانسانيه البشريه مباينه لانفسهم الهيولانيه he brought them into existence as forms purely imaginal and luminous possessing thousand fold statures like the human corporeal statures distinct from their material souls', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 14, NULL, 'He brought them into existence as ashbah — forms — and these forms were purely imaginal, suriyyah; pure, mahdah; and luminous, nuraniyya. They stood at statures of a thousand-fold measure, qamat alfiyya, likened to the human bodily stature, al-qamat al-insaniyya al-bashariyya. The direction of the comparison needs setting straight, or it reads exactly backward. The originated forms are called like the human stature — but that is said only to make the matter graspable to people, who know the human shape and nothing higher. In reality the likeness runs the other way. The human stature is patterned upon those originated forms; they are not patterned upon it. When the Originator originated, He originated in such a way that the human bodies which would much later enter the world were fashioned on the model of those primordial luminous forms. So although the words say the forms resembled the human stature, the truth is that the human stature was cut to the model of the forms. The copy reaches up to describe the original by pointing at the copy.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'he brought them into existence as ashbah forms and these forms were purely imaginal suriyyah pure mahdah and luminous nuraniyya they stood at statures of a thousand fold measure qamat alfiyya likened to the human bodily stature al qamat al insaniyya al bashariyya the direction of the comparison needs setting straight or it reads exactly backward the originated forms are called like the human stature but that is said only to make the matter graspable to people who know the human shape and nothing higher in reality the likeness runs the other way the human stature is patterned upon those originated forms they are not patterned upon it when the originator originated he originated in such a way that the human bodies which would much later enter the world were fashioned on the model of those primordial luminous forms so although the words say the forms resembled the human stature the truth is that the human stature was cut to the model of the forms the copy reaches up to describe the original by pointing at the copy', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 15, NULL, 'And these luminous forms are distinct — mubayinah — from the material souls, the anfus hayulaniyya, that came afterward. The souls did not yet exist; they belong to a later stage. The order here is a descent. What was originated were luminous imaginal forms, ashbah suriyyah nuraniyya. When souls were later formed, they were a fallen, degraded condition drawn down from these. And when bodies of flesh and blood were formed, they were a condition more fallen still. The forms were luminous subtleties — lataif nuraniyya. The bodies are dark densities — kathaif zulmaniyya. The soul is a fallen form of the luminous original; the body, a yet more fallen form of that. One light at the top, and as it descends it thickens and darkens, like clear water that grows muddied as it sinks to the riverbed.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'and these luminous forms are distinct mubayinah from the material souls the anfus hayulaniyya that came afterward the souls did not yet exist they belong to a later stage the order here is a descent what was originated were luminous imaginal forms ashbah suriyyah nuraniyya when souls were later formed they were a fallen degraded condition drawn down from these and when bodies of flesh and blood were formed they were a condition more fallen still the forms were luminous subtleties lataif nuraniyya the bodies are dark densities kathaif zulmaniyya the soul is a fallen form of the luminous original the body a yet more fallen form of that one light at the top and as it descends it thickens and darkens like clear water that grows muddied as it sinks to the riverbed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 16, NULL, 'The first of the perfections follows, a doctrine that carries weight, for it is the seedbed of justice itself:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'the first of the perfections follows a doctrine that carries weight for it is the seedbed of justice itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 17, NULL, 'Sayingفَأَوْجَدَ تِلْكَ الْأَشْبَاحَ النُّورَانِيَّةَ مُتَسَاوِيَةً فِي الْكَمَالِ الْأَوَّلِيِّ الَّذِي هُوَ الْوُجُودُ وَالْحَيَاةُ وَالْقُوَّةُ وَالْقُدْرَةُ، لَا تَخَالُفَ فِيهَا وَلَا تَفَاضُلَ وَلَا تَبَايُنَ بَيْنَهَا وَلَا تَمَايُلَ فِيمَا دَقَّ وَجَلَّ وَكَثُرَ وَقَلَّ، عَدْلًا مِنْهُ عَزَّ وَجَلَّ."So He brought those luminous forms into existence, equal in the first perfection — which is existence, life, strength, and ability — with no disagreement in them, no preference, no distinction among them, and no inclination in what was subtle or great, much or little, as an act of justice from Him, the Mighty and Majestic."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingفاوجد تلك الاشباح النورانيه متساويه في الكمال الاولي الذي هو الوجود والحياه والقوه والقدره لا تخالف فيها ولا تفاضل ولا تباين بينها ولا تمايل فيما دق وجل وكثر وقل عدلا منه عز وجل so he brought those luminous forms into existence equal in the first perfection which is existence life strength and ability with no disagreement in them no preference no distinction among them and no inclination in what was subtle or great much or little as an act of justice from him the mighty and majestic', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 18, NULL, 'He brought the luminous forms into existence equal — mutasawiyah — in the first perfection, the kamal al-awwali. And what is this first perfection? It is the original state in which He made them, and it is made of four things: existence, wujud; life, hayat; strength, quwwah; and ability — which, with Mohyuddin, means knowledge and power together, ilm and qudrah. In that first perfection the forms were equal, equal with no gap of any kind. No disagreement among them, la takhaluf. No preference of one over another, la tafadul. No distinction, la tabayun. No leaning of one above the rest, la tamayul — not in the subtle, not in the great, not in the much, not in the little. The first He originated was exactly as the last He originated. Not a hair''s difference ran between any of the originated beings in the state of first perfection.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'he brought the luminous forms into existence equal mutasawiyah in the first perfection the kamal al awwali and what is this first perfection it is the original state in which he made them and it is made of four things existence wujud life hayat strength quwwah and ability which with mohyuddin means knowledge and power together ilm and qudrah in that first perfection the forms were equal equal with no gap of any kind no disagreement among them la takhaluf no preference of one over another la tafadul no distinction la tabayun no leaning of one above the rest la tamayul not in the subtle not in the great not in the much not in the little the first he originated was exactly as the last he originated not a hairs difference ran between any of the originated beings in the state of first perfection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 19, NULL, 'And this equality was no accident of the making. It was an act of adl, of justice, from Him, mighty and majestic. He grounds the principle:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'and this equality was no accident of the making it was an act of adl of justice from him mighty and majestic he grounds the principle', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 20, NULL, 'Sayingإِذِ الْعَادِلُ يَتَسَاوَى عَدْلُهُ وَالْفَاضِلُ يَعُمُّ فَضْلُهُ."Since the justice of the Just is equal, and the grace of the Gracious is universal."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingاذ العادل يتساوي عدله والفاضل يعم فضله since the justice of the just is equal and the grace of the gracious is universal', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 21, NULL, 'The justice of the Just is even in its distribution — it does not parcel out more here and less there. The grace of the Gracious is universal in its reach — it does not water one field and leave the next dry. Therefore the originated forms came into being in perfect equality. That is not a sentiment; it is a conclusion drawn from who the Maker is. And it is anchored, finally, in scripture itself:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'the justice of the just is even in its distribution it does not parcel out more here and less there the grace of the gracious is universal in its reach it does not water one field and leave the next dry therefore the originated forms came into being in perfect equality that is not a sentiment it is a conclusion drawn from who the maker is and it is anchored finally in scripture itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 22, NULL, 'Sayingكَمَا أَخْبَرَ الْكِتَابُ الْكَرِيمُ مِنْ قَوْلِ الْعَلِيِّ الْعَظِيمِ: ﴿وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلَافًا كَثِيرًا﴾"As the Noble Book has informed, from the saying of the High, the Great: And if it had been from other than Allah, they would have found in it much contradiction."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingكما اخبر الكتاب الكريم من قول العلي العظيم ولو كان من عند غير الله لوجدوا فيه اختلافا كثيرا as the noble book has informed from the saying of the high the great and if it had been from other than allah they would have found in it much contradiction', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 23, NULL, 'Had this originated order proceeded from any maker other than Allah, much contradiction — ikhtilaf — would be found woven through it; for only a perfect justice could bring forth a creation without disparity. The word ikhtilaf itself is worth weighing. It comes from the root khalf and arrives in the pattern of bab al-iftial; its plain sense is difference, discrepancy, things failing to agree. The verse declares that, had the matter come from other than Allah, such discrepancy would be found running all through it. But it came from Allah, and so He showed His creation this one great kindness — He gave to none of them more and to none of them less. What He gave, He gave evenly. This is the very verse that answers the question raised earlier, whether the equal creation of all beings has any warrant in the Holy Quran. It has its warrant here, in wa law kana min indi ghayrillahi la-wajadu fihi ikhtilafan kathira. The equality is not a borrowed philosophy. It is in the Book.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'had this originated order proceeded from any maker other than allah much contradiction ikhtilaf would be found woven through it for only a perfect justice could bring forth a creation without disparity the word ikhtilaf itself is worth weighing it comes from the root khalf and arrives in the pattern of bab al iftial its plain sense is difference discrepancy things failing to agree the verse declares that had the matter come from other than allah such discrepancy would be found running all through it but it came from allah and so he showed his creation this one great kindness he gave to none of them more and to none of them less what he gave he gave evenly this is the very verse that answers the question raised earlier whether the equal creation of all beings has any warrant in the holy quran it has its warrant here in wa law kana min indi ghayrillahi la wajadu fihi ikhtilafan kathira the equality is not a borrowed philosophy it is in the book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 24, NULL, 'The same reality is affirmed by Sayyidna Hamiduddin — may Allah sanctify his soul — in the seventh path, the mashra, of the fourth form, the suwar, of his Rahat al-Aql. His words carry the matter forward, for they answer a question the simultaneity raised some pages earlier: how could a whole world come into being all at once?', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'the same reality is affirmed by sayyidna hamiduddin may allah sanctify his soul in the seventh path the mashra of the fourth form the suwar of his rahat al aql his words carry the matter forward for they answer a question the simultaneity raised some pages earlier how could a whole world come into being all at once', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 25, NULL, 'Sayingوَدَارُ الْإِبْدَاعِ وَالِانْبِعَاثِ لَا عَائِقَ فِيهَا لِخُلُوِّهِمَا مِنَ الْمَوَادِّ الَّتِي تَعُوقُ وَتَجَرُّدِهَا مِنْهَا وَكَوْنِهَا صُوَرًا مَحْضَةً لَا تَتَعَلَّقُ بِمَادَّةٍ وَلَا بِهَا مَادَّةٌ لِتَحْجُزَهَا عَنِ الْفِعْلِ."And in the abode of origination and the abode of emanation there is no obstacle, because of their freedom from the matters that obstruct, and their being abstracted from them, and their being pure forms attached to no matter, with no matter in them that would prevent them from action."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingودار الابداع والانبعاث لا عايق فيها لخلوهما من المواد التي تعوق وتجردها منها وكونها صورا محضه لا تتعلق بماده ولا بها ماده لتحجزها عن الفعل and in the abode of origination and the abode of emanation there is no obstacle because of their freedom from the matters that obstruct and their being abstracted from them and their being pure forms attached to no matter with no matter in them that would prevent them from action', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 26, NULL, 'In the abode of origination, dar al-ibda, and the abode of emanation, dar al-inbiath, there is no obstacle — la aiqa. And why none? Because both abodes are free of the obstructing matters; the kinds of stuff that would impede are simply not there. The forms are abstracted, tajarrud, from all such matter. They are pure forms, suwar mahdah, clinging to no matter, with no matter clinging in them. Matter is the thing that obstructs. Wherever matter sits, hindrance and friction arise — the way a current slows the instant it meets silt and stone. But here there is no matter at all to halt the forms from fil, from action. There is power present, quwwah; there is ability present, qudrah; and they can show their effect with nothing standing in their way. No drag has been set across them to delay the second action or to block the reaching of the second perfection. And from this Hamiduddin draws the conclusion the whole passage was built toward:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'in the abode of origination dar al ibda and the abode of emanation dar al inbiath there is no obstacle la aiqa and why none because both abodes are free of the obstructing matters the kinds of stuff that would impede are simply not there the forms are abstracted tajarrud from all such matter they are pure forms suwar mahdah clinging to no matter with no matter clinging in them matter is the thing that obstructs wherever matter sits hindrance and friction arise the way a current slows the instant it meets silt and stone but here there is no matter at all to halt the forms from fil from action there is power present quwwah there is ability present qudrah and they can show their effect with nothing standing in their way no drag has been set across them to delay the second action or to block the reaching of the second perfection and from this hamiduddin draws the conclusion the whole passage was built toward', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 27, NULL, 'Sayingوَإِذَا كَانَ لَا عَائِقَ فِيهَا فَوُجُودُ مَوْجُودَاتِهَا لَا بِزَمَانٍ بَلْ دَفْعَةً وَاحِدَةً، مِثْلَ وُجُودِ إِشْرَاقِ بَسِيطِ الْهَوَاءِ عَنْ ضَوْءِ الشَّمْسِ، لَا بِزَمَانٍ... وَإِضَاءَةُ النَّارِ الْبَيْتَ الْمُظْلِمَ دَفْعَةً وَاحِدَةً، لَا بِزَمَانٍ."And since there is no obstacle in them, the existence of their existents is not in time but in a single instant — like the illumination of the expanse of the air by the light of the sun, not in time... and like the lighting of a dark house by a fire in a single instant, not in time."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingواذا كان لا عايق فيها فوجود موجوداتها لا بزمان بل دفعه واحده مثل وجود اشراق بسيط الهواء عن ضوء الشمس لا بزمان واضاءه النار البيت المظلم دفعه واحده لا بزمان and since there is no obstacle in them the existence of their existents is not in time but in a single instant like the illumination of the expanse of the air by the light of the sun not in time and like the lighting of a dark house by a fire in a single instant not in time', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 28, NULL, 'Because nothing obstructs, the existents of these abodes came to be not in time — la bi-zaman — but in a single instant, dafatan wahidatan, all of them at one stroke. He gives two images, both meant to do their work. The first: the sun rises, and the whole expanse of the air is flooded with light at once — not lit strip by strip, near things first and far things after, but the entire reach of it illumined in the same moment. The second: a dark room, and a flame is kindled in it; the instant the fire catches, the whole room is full of light. Not a slow filling from the lamp outward, but the room itself, in one moment, bright. So too the world of origination came into existence — like air all at once awash in sunlight, like a dark house all at once illumined.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'because nothing obstructs the existents of these abodes came to be not in time la bi zaman but in a single instant dafatan wahidatan all of them at one stroke he gives two images both meant to do their work the first the sun rises and the whole expanse of the air is flooded with light at once not lit strip by strip near things first and far things after but the entire reach of it illumined in the same moment the second a dark room and a flame is kindled in it the instant the fire catches the whole room is full of light not a slow filling from the lamp outward but the room itself in one moment bright so too the world of origination came into existence like air all at once awash in sunlight like a dark house all at once illumined', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 29, NULL, 'That simultaneity carries a consequence, drawn out in the line that follows:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'that simultaneity carries a consequence drawn out in the line that follows', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 30, NULL, 'Sayingعَلَى أَنَّ الشَّيْءَ فِي تِلْكَ الدَّارِ لَمْ يَتَقَدَّمْ وُجُودُهُ عَلَى شَيْءٍ مِنَ الْعُقُولِ الْقَائِمَةِ بِالْفِعْلِ وَالْعُقُولِ الْقَائِمَةِ بِالْقُوَّةِ، بَلْ وُجُودُ الْكُلِّ مَعًا."That a thing in that abode — its existence did not precede anything of the intellects existing in actuality and the intellects existing in potentiality. Rather, the existence of all was together."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingعلي ان الشيء في تلك الدار لم يتقدم وجوده علي شيء من العقول القايمه بالفعل والعقول القايمه بالقوه بل وجود الكل معا that a thing in that abode its existence did not precede anything of the intellects existing in actuality and the intellects existing in potentiality rather the existence of all was together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 31, NULL, 'In that abode no thing''s existence came before another''s. The existence of the intellects subsisting in actuality, bi-l-fil, did not arrive ahead of the intellects subsisting in potentiality, bi-l-quwwah. And what are the intellects "in potentiality"? They are, in effect, the powers granted to the intellects — powers that were afterward actualized and made firm. Their existence was not preceded by some earlier existing thing; rather, the existence of all was together, wujud al-kull maan, at one and the same time. The intellect subsisting potentially and the intellect subsisting actually both stood in being from the same instant. And this carries a momentous result: there was no interval of time dividing the first perfection, kamal al-awwal, from the second perfection, kamal al-thani. No span of time stood between them. The potential and the actual coexisted from the very outset, so that no temporal gap was wedged between the initial state of equality and the higher state still to be attained.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'in that abode no things existence came before anothers the existence of the intellects subsisting in actuality bi l fil did not arrive ahead of the intellects subsisting in potentiality bi l quwwah and what are the intellects in potentiality they are in effect the powers granted to the intellects powers that were afterward actualized and made firm their existence was not preceded by some earlier existing thing rather the existence of all was together wujud al kull maan at one and the same time the intellect subsisting potentially and the intellect subsisting actually both stood in being from the same instant and this carries a momentous result there was no interval of time dividing the first perfection kamal al awwal from the second perfection kamal al thani no span of time stood between them the potential and the actual coexisted from the very outset so that no temporal gap was wedged between the initial state of equality and the higher state still to be attained', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 32, NULL, 'One point must be conceded honestly. Human understanding needs some stretch of time to walk through this. Even the kindling of a fire seems, to the mind, to take a moment before the room brims with light — first the flame, then the spreading, then the brightness. But the light in question is not ordinary light that travels and spreads by degrees. It is such that the very instant it is lit, the whole is full at once. That instantaneity is the character of the first perfection itself.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'one point must be conceded honestly human understanding needs some stretch of time to walk through this even the kindling of a fire seems to the mind to take a moment before the room brims with light first the flame then the spreading then the brightness but the light in question is not ordinary light that travels and spreads by degrees it is such that the very instant it is lit the whole is full at once that instantaneity is the character of the first perfection itself', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 33, NULL, 'Yet equality is not the same as safety. With Mohyuddin, what the first perfection does and does not include must be stated exactly:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'yet equality is not the same as safety with mohyuddin what the first perfection does and does not include must be stated exactly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 34, NULL, 'Sayingيُرِيدُ بِذَلِكَ أَعْلَى اللَّهُ قُدْسَهُ فِي حَالِ وُجُودِهِمُ الْأَوَّلِ وَكَمَالِهِمُ الْأَوَّلِ الَّذِينَ هُمْ فِيهِ مُتَسَاوُونَ، كَمَا سَبَقَ مِنْ قَوْلِهِ، وَهُمْ مَعَ ذَلِكَ فِي بَدْءِ وُجُودِهِمُ الْجَمِيعِ فِي الْفِعْلِ وَالْعَمَلِ غَيْرُ مَعْصُومِينَ مِنَ الْخَطَأِ."By that — may Allah sanctify his soul — he means: in the state of their first existence and their first perfection, in which they are all equal, as has preceded from his saying; and yet, along with that, in the beginning of their collective existence, in action and deed, they are not infallible from error."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingيريد بذلك اعلي الله قدسه في حال وجودهم الاول وكمالهم الاول الذين هم فيه متساوون كما سبق من قوله وهم مع ذلك في بدء وجودهم الجميع في الفعل والعمل غير معصومين من الخطا by that may allah sanctify his soul he means in the state of their first existence and their first perfection in which they are all equal as has preceded from his saying and yet along with that in the beginning of their collective existence in action and deed they are not infallible from error', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 35, NULL, 'By this he means the state of the beings'' first existence and first perfection — the state in which they are all equal. A qualification changes everything: along with that equality, in the beginning of their collective existence, in fil and عَمَل, in action and deed, they are not infallible — ghayru masumin — from error, from khata. The point overturns an easy assumption. The first perfection, for all its flawless equality, is not the perfect, protected state. The truly perfected state is the second perfection, the kamal al-thani. The first perfection is the lower, initial condition, and in it the beings, equal though they are, are not shielded from error; error can issue from them.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'by this he means the state of the beings first existence and first perfection the state in which they are all equal a qualification changes everything along with that equality in the beginning of their collective existence in fil and عمل in action and deed they are not infallible ghayru masumin from error from khata the point overturns an easy assumption the first perfection for all its flawless equality is not the perfect protected state the truly perfected state is the second perfection the kamal al thani the first perfection is the lower initial condition and in it the beings equal though they are are not shielded from error error can issue from them', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 36, NULL, 'Then what is this "error"? Exactness matters here, for vagueness would betray the whole teaching. The error consists in failing to attain the second perfection. That is the error — and it wears more than one face. It is a delay in answering the invitation when the call comes. It is a refusal to rise when summoned. And beyond falling short oneself, it is the misleading of others, the setting of other souls onto the wrong road. All of this can come from beings who stand in the first perfection, precisely because in that state they are ghayr masum, not preserved. The first perfection, then, is best understood for what it truly is: a test placed in their hands, charging them to go straight and to use rightly the powers given them. It is not yet the state of the return-perfected. It is the trial-state of equality, the level ground from which each one must journey — by the right use of his own powers — up to the second perfection. Equal at the starting line, and free to run true or to stumble.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'then what is this error exactness matters here for vagueness would betray the whole teaching the error consists in failing to attain the second perfection that is the error and it wears more than one face it is a delay in answering the invitation when the call comes it is a refusal to rise when summoned and beyond falling short oneself it is the misleading of others the setting of other souls onto the wrong road all of this can come from beings who stand in the first perfection precisely because in that state they are ghayr masum not preserved the first perfection then is best understood for what it truly is a test placed in their hands charging them to go straight and to use rightly the powers given them it is not yet the state of the return perfected it is the trial state of equality the level ground from which each one must journey by the right use of his own powers up to the second perfection equal at the starting line and free to run true or to stumble', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 37, NULL, 'At just this point Mohyuddin lifts a prayer, and its grammar carries the meaning of "error" more precisely than any paraphrase could:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'at just this point mohyuddin lifts a prayer and its grammar carries the meaning of error more precisely than any paraphrase could', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 38, NULL, 'Sayingعَصَمَنَا اللَّهُ مِنْ أَنْ نَزِلَّ أَوْ نُزِلَّ، بِحَقِّ مُحَمَّدٍ وَآلِهِ الطَّاهِرِينَ صَلَوَاتُ اللَّهِ عَلَيْهِمْ أَجْمَعِينَ."May Allah protect us from slipping or being made to slip, by the right of Muhammad and his pure progeny, the blessings of Allah upon them all."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'sayingعصمنا الله من ان نزل او نزل بحق محمد واله الطاهرين صلوات الله عليهم اجمعين may allah protect us from slipping or being made to slip by the right of muhammad and his pure progeny the blessings of allah upon them all', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 39, NULL, 'May Allah protect us — from what? From two things, and the difference between them is the difference of a single letter at the front of a verb. An nazilla: that we should slip. Nuzilla: that we should be made to slip — or that we should make others slip. The contrast is instructive, and the forms set side by side, as a grammarian would place them, show it. زَلَّ means "he slipped"; أَزَلَّ means "he made another slip." It runs exactly as قَطَعَ means "he cut" and أَقْطَعَ means "he had another cut," or as سَجَدَ means "he prostrated" and أَسْجَدَ means "he made another prostrate." So نَزِلَّ is "that we should slip," and نُزِلَّ is "that we should be made to slip," or "that we should make others slip." The same pattern governs going astray as well: زَلَّ, "he went astray"; أَضَلَّ, "he led another astray" — he went off the road himself, or he turned someone else off it. The rule never wavers: فَعَلَ, "he did," and أَفْعَلَ, "he had it done."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'may allah protect us from what from two things and the difference between them is the difference of a single letter at the front of a verb an nazilla that we should slip nuzilla that we should be made to slip or that we should make others slip the contrast is instructive and the forms set side by side as a grammarian would place them show it زل means he slipped ازل means he made another slip it runs exactly as قطع means he cut and اقطع means he had another cut or as سجد means he prostrated and اسجد means he made another prostrate so نزل is that we should slip and نزل is that we should be made to slip or that we should make others slip the same pattern governs going astray as well زل he went astray اضل he led another astray he went off the road himself or he turned someone else off it the rule never wavers فعل he did and افعل he had it done', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'out of nothing, and equal in justice', '7. Out of Nothing, and Equal in Justice', 40, NULL, 'So the prayer asks for shelter from both at once — from slipping, and from being the cause of another''s slip. And that is no accident of piety, for those two are exactly the two faces of the "error" just named, the error that is failure to reach the second perfection: to fall short of it oneself, or to mislead others and drag them short of it as well. To go astray, and to lead astray — the prayer covers them both because the danger comes in both. And with that prayer, the road bends again. The act of origination has been entered, a whole world watched coming up out of nothing in a single instant, all things seen set equal as a matter of justice, and the equality learned to be a beginning and not a guarantee. What remains is the ground that equality opens onto, where the test set into the first perfection begins to be met or failed.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 7 out of nothing and equal in justice', 'so the prayer asks for shelter from both at once from slipping and from being the cause of anothers slip and that is no accident of piety for those two are exactly the two faces of the error just named the error that is failure to reach the second perfection to fall short of it oneself or to mislead others and drag them short of it as well to go astray and to lead astray the prayer covers them both because the danger comes in both and with that prayer the road bends again the act of origination has been entered a whole world watched coming up out of nothing in a single instant all things seen set equal as a matter of justice and the equality learned to be a beginning and not a guarantee what remains is the ground that equality opens onto where the test set into the first perfection begins to be met or failed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 0, NULL, 'One of those forms turned, and looked.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'one of those forms turned and looked', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 1, NULL, 'That is where it begins — not with a command from above, not with a voice breaking into the silence, but with a single originated form, standing among its equals, that turned its attention inward and looked. The letter renders it so, and the whole of the account hangs on this one motion. He looked with his own essence at his own essence, and then he lifted that same gaze and looked at the others — the children of his kind, his fellows, the whole crowd of forms that had come up out of nothing alongside him in that single instant. He saw himself. He saw them. And something occurred to him that had not occurred before.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'that is where it begins not with a command from above not with a voice breaking into the silence but with a single originated form standing among its equals that turned its attention inward and looked the letter renders it so and the whole of the account hangs on this one motion he looked with his own essence at his own essence and then he lifted that same gaze and looked at the others the children of his kind his fellows the whole crowd of forms that had come up out of nothing alongside him in that single instant he saw himself he saw them and something occurred to him that had not occurred before', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 2, NULL, 'The letter sets it down in these words:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'the letter sets it down in these words', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 3, NULL, 'Sayingثُمَّ إِنَّ وَاحِدًا مِنْ تِلْكَ الْأَشْبَاحِ الصُّورِيَّةِ نَظَرَ بِذَاتِهِ إِلَىٰ ذَاتِهِ وَإِلَىٰ أَبْنَاءِ جِنْسِهِ، فَعَلِمَ أَنَّ لَهُمْ مُبْدِعًا بِخِلَافِهِمْ، فَنَفَىٰ عَنْهُ وَعَنْ أَبْنَاءِ جِنْسِهِ الْإِلَٰهِيَّةَ وَأَثْبَتَهَا لِمُبْدِعِهِمْ تَعَالَىٰ وَشَهِدَ لَهُ بِالْوَحْدَانِيَّةِ."Then indeed one of those imaginal forms looked, with his essence, at his essence and at the children of his kind; so he knew that they had an Originator unlike them; so he negated divinity from himself and from the children of his kind, and affirmed it for their Originator, the Exalted, and bore witness to His oneness."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingثم ان واحدا من تلك الاشباح الصوريه نظر بذاته الي ذاته والي ابناء جنسه فعلم ان لهم مبدعا بخلافهم فنفي عنه وعن ابناء جنسه الالهيه واثبتها لمبدعهم تعالي وشهد له بالوحدانيه then indeed one of those imaginal forms looked with his essence at his essence and at the children of his kind so he knew that they had an originator unlike them so he negated divinity from himself and from the children of his kind and affirmed it for their originator the exalted and bore witness to his oneness', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 4, NULL, 'The verb itself is exact. He looked with his essence — not with borrowed eyes, not with an instrument handed to him, but by means of the very being he had been given. He had nothing else to look with. And what his looking yielded was not a feeling but a knowing. He knew — and the word in the letter is exactly that, knew — that there was, for himself and for all of them, an Originator who was unlike them. Unlike them: there is the hinge. He did not find the Originator standing in the crowd as the tallest among equals. He found that the One who had brought them all into being could not be of their kind at all, because everything of their kind had been brought into being, and the One who does the bringing cannot be among the things brought.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'the verb itself is exact he looked with his essence not with borrowed eyes not with an instrument handed to him but by means of the very being he had been given he had nothing else to look with and what his looking yielded was not a feeling but a knowing he knew and the word in the letter is exactly that knew that there was for himself and for all of them an originator who was unlike them unlike them there is the hinge he did not find the originator standing in the crowd as the tallest among equals he found that the one who had brought them all into being could not be of their kind at all because everything of their kind had been brought into being and the one who does the bringing cannot be among the things brought', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 5, NULL, 'So he did two things in one breath. He took divinity away from himself and from every form like him. He could not say, I am the god, and neither could any of his fellows, because he had just seen that all of them stood on the same side of the line — the originated side. And then, having cleared the false claim off himself and off his entire kind, he set divinity down where it belonged: he affirmed it for their Originator, the Exalted, and stood as witness to the fact that this Originator is one.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'so he did two things in one breath he took divinity away from himself and from every form like him he could not say i am the god and neither could any of his fellows because he had just seen that all of them stood on the same side of the line the originated side and then having cleared the false claim off himself and off his entire kind he set divinity down where it belonged he affirmed it for their originator the exalted and stood as witness to the fact that this originator is one', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 6, NULL, 'He has just performed, untaught, a complete act. He has denied any partner — that is the unity, the Tawhid. He has stripped the Creator of every likeness to the creature — that is تَنْزِيه, the keeping-pure. And he has cut the Originator free from being bound up in His creation, set apart from all of it — that is تَجْرِيد, the isolating of the One. Three movements that a whole tradition would later name and number, and he did them at once, in a single act of looking. By that act he became what the letter calls Sahib al-Tawhid — the Possessor of Tawhid, the one in whose hands the declaration of oneness first rested. The first ever to say it. By looking at his own essence and at his kind, by recognizing an Originator unlike them, by lifting divinity off everything that had been originated and laying it on the Originator alone, he enacted the whole of Tawhid in its completeness, all three branches together.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'he has just performed untaught a complete act he has denied any partner that is the unity the tawhid he has stripped the creator of every likeness to the creature that is تنزيه the keeping pure and he has cut the originator free from being bound up in his creation set apart from all of it that is تجريد the isolating of the one three movements that a whole tradition would later name and number and he did them at once in a single act of looking by that act he became what the letter calls sahib al tawhid the possessor of tawhid the one in whose hands the declaration of oneness first rested the first ever to say it by looking at his own essence and at his kind by recognizing an originator unlike them by lifting divinity off everything that had been originated and laying it on the originator alone he enacted the whole of tawhid in its completeness all three branches together', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 7, NULL, 'Yet seeing the truth is not the same as drawing near to it, and he knew that too. What he did next was subtler, and no less decisive.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'yet seeing the truth is not the same as drawing near to it and he knew that too what he did next was subtler and no less decisive', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 8, NULL, 'Sayingوَاعْتَرَفَ لَهُ بِالرُّبُوبِيَّةِ وَسَبَّحَ لَهُ وَخَشَعَ وَتَذَلَّلَ وَخَضَعَ وَتَوَسَّلَ بِعَظَمَتِهِ إِلَيْهِ وَتَضَرَّعَ."And he acknowledged for Him Lordship, and glorified Him, and was reverent, and humbled himself, and submitted, and sought means through His greatness toward Him, and supplicated."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingواعترف له بالربوبيه وسبح له وخشع وتذلل وخضع وتوسل بعظمته اليه وتضرع and he acknowledged for him lordship and glorified him and was reverent and humbled himself and submitted and sought means through his greatness toward him and supplicated', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 9, NULL, 'He acknowledged that the Originator is Lord — rububiyya, the Lordship that owns and sustains. He glorified Him. He grew reverent, lowered himself, gave himself over. And then comes the phrase the letter dwells on: he sought means through His greatness toward Him. That is tawassul, and it is more subtle than it sounds. The first form did not try to walk straight up to the Originator, because there is no walking straight up to Him; the Originator cannot be reached directly, not by a form, not by anyone. So the form did something else. He took the Originator''s own greatness — that vast, unapproachable magnitude — and made that his road. He could not reach the Originator, so he reached toward the greatness, and let the greatness carry his approach. Through the means of that greatness he gave his testimony: that this is the Lord, that this is the divine, and that he himself was nothing, low, in need. He did not presume on a direct nearness that no creature can have. He made the very greatness of the Originator the go-between by which he could turn his face toward Him. This is what tawassul is — to take the greatness of the Originator as the means to the Originator, precisely because the Originator Himself is out of reach.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'he acknowledged that the originator is lord rububiyya the lordship that owns and sustains he glorified him he grew reverent lowered himself gave himself over and then comes the phrase the letter dwells on he sought means through his greatness toward him that is tawassul and it is more subtle than it sounds the first form did not try to walk straight up to the originator because there is no walking straight up to him the originator cannot be reached directly not by a form not by anyone so the form did something else he took the originators own greatness that vast unapproachable magnitude and made that his road he could not reach the originator so he reached toward the greatness and let the greatness carry his approach through the means of that greatness he gave his testimony that this is the lord that this is the divine and that he himself was nothing low in need he did not presume on a direct nearness that no creature can have he made the very greatness of the originator the go between by which he could turn his face toward him this is what tawassul is to take the greatness of the originator as the means to the originator precisely because the originator himself is out of reach', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 10, NULL, 'And the seeking of means was answered. Something came down.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'and the seeking of means was answered something came down', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 11, NULL, 'Sayingفَتَدَارَكَ مِنْ مُبْدِعِهِ الْمَوَادُّ الْإِلَٰهِيَّةُ وَالتَّأْيِيدَاتُ الْوَحْدَانِيَّةُ، وَاتَّصَلَ بِهِ الْعِلْمُ الْجَارِي وَالنُّورُ السَّارِي الَّذِي هُوَ كَلِمَةُ اللَّهِ تَعَالَىٰ."So there reached him from his Originator the divine supports and the confirmations of oneness, and there connected with him the flowing knowledge and the spreading light, which is the Word of Allah, the Exalted."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingفتدارك من مبدعه المواد الالهيه والتاييدات الوحدانيه واتصل به العلم الجاري والنور الساري الذي هو كلمه الله تعالي so there reached him from his originator the divine supports and the confirmations of oneness and there connected with him the flowing knowledge and the spreading light which is the word of allah the exalted', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 12, NULL, 'From the Originator there reached him supports — divine reinforcements — and confirmations of the very oneness he had just witnessed, as if his testimony were being sealed from above. And then something connected with him: a flowing knowledge and a spreading light. Both words move. The knowledge flows; the light spreads. They are not a static deposit but a current, and the letter says plainly what that current is — it is the Word of Allah, the Exalted. That Word, that kalimah, is the one sentence around which this whole edifice is built:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'from the originator there reached him supports divine reinforcements and confirmations of the very oneness he had just witnessed as if his testimony were being sealed from above and then something connected with him a flowing knowledge and a spreading light both words move the knowledge flows the light spreads they are not a static deposit but a current and the letter says plainly what that current is it is the word of allah the exalted that word that kalimah is the one sentence around which this whole edifice is built', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 13, NULL, 'لَا إِلَٰهَ إِلَّا اللَّهُ"There is no god but God."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'لا اله الا الله there is no god but god', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 14, NULL, 'Through that first form''s act — his negation, his recognition, his seeking of means — there flowed into him the flowing knowledge and the spreading light that is the kalimah, There is no god but God. The Word stands between the Originator and the originated like a channel cut between a spring and the field below it; before the water can reach the field, the channel must exist, and once it exists the water never stops. So with the kalimah: it is the link through which the knowledge and the light pour down from the One who has no likeness to the things that bear His mark. The letter adds the teaching that places it exactly:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'through that first forms act his negation his recognition his seeking of means there flowed into him the flowing knowledge and the spreading light that is the kalimah there is no god but god the word stands between the originator and the originated like a channel cut between a spring and the field below it before the water can reach the field the channel must exist and once it exists the water never stops so with the kalimah it is the link through which the knowledge and the light pour down from the one who has no likeness to the things that bear his mark the letter adds the teaching that places it exactly', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 15, NULL, 'Sayingوَلِذَٰلِكَ قِيلَ إِنَّ الْكَلِمَةَ فَوْقَ الْعَقْلِ وَدُونَ الْمُبْدِعِ. وَتُسَمَّىٰ أَيْضًا بِالْأَمْرِ."And for that reason it is said that the kalimah is above the intellect and below the Originator. And it is also named the command."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingولذلك قيل ان الكلمه فوق العقل ودون المبدع وتسمي ايضا بالامر and for that reason it is said that the kalimah is above the intellect and below the originator and it is also named the command', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 16, NULL, 'Above the intellect, below the Originator. The Word There is no god but God sits in precisely this middle station — beneath the Originator who has no station, and above the intellect that will receive what comes through it. The light came from the Originator, down to the Word, and through the Word to the intellect; the Word is the continuous link in which the Originator''s will and the sentence There is no god but God are shown together, will and Word manifest as one thing. And the same Word carries a second name: al-amr, the command — because every command there is has been folded inside it. The Word is not a flash that fires once and goes dark. It is a link held open for as long as creation lasts. As long as the creation stands, the kalimah stands, and the light keeps flowing through it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'above the intellect below the originator the word there is no god but god sits in precisely this middle station beneath the originator who has no station and above the intellect that will receive what comes through it the light came from the originator down to the word and through the word to the intellect the word is the continuous link in which the originators will and the sentence there is no god but god are shown together will and word manifest as one thing and the same word carries a second name al amr the command because every command there is has been folded inside it the word is not a flash that fires once and goes dark it is a link held open for as long as creation lasts as long as the creation stands the kalimah stands and the light keeps flowing through it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 17, NULL, 'There is a consequence here that the letter draws out, and it explains a number that recurs. The world of origination ended at seven. The First Intellect came to be, the Originator made seven, and the tenth is the ashir — but the luminous world stopped at seven. Why seven and not more? Because the Originator willed it to be seven. He had placed everything inside the kalimah, and He willed that the whole of it should terminate at seven. The will set the boundary, and the boundary held.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'there is a consequence here that the letter draws out and it explains a number that recurs the world of origination ended at seven the first intellect came to be the originator made seven and the tenth is the ashir but the luminous world stopped at seven why seven and not more because the originator willed it to be seven he had placed everything inside the kalimah and he willed that the whole of it should terminate at seven the will set the boundary and the boundary held', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 18, NULL, 'Through that Word, the First Intellect came into a knowledge that left nothing out.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'through that word the first intellect came into a knowledge that left nothing out', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 19, NULL, 'Sayingوَبِهِ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا وَعَلِمَ مَا كَانَ وَمَا سَيَكُونُ."And through it he encompassed all things in knowledge, and knew what was and what will be."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingوبه احاط بكل شيء علما وعلم ما كان وما سيكون and through it he encompassed all things in knowledge and knew what was and what will be', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 20, NULL, 'Through the Word he encompassed every single thing in knowledge, and knew what had already been and what was still to come — because There is no god but God contains it all, everything that has happened and everything that has not yet happened. But the letter insists on a sequence easily reversed, and reversing it spoils the whole matter. The complete knowledge had, in a manner, already been handed over with the first perfection. It was there. What was missing was that the First Intellect did not recognize what he held, did not know how to use it. He was like a man given the keys to a house he does not yet know is his. What the light of the kalimah supplied was not new information so much as the understanding of what he had been given and the way to wield the powers already in his hands.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'through the word he encompassed every single thing in knowledge and knew what had already been and what was still to come because there is no god but god contains it all everything that has happened and everything that has not yet happened but the letter insists on a sequence easily reversed and reversing it spoils the whole matter the complete knowledge had in a manner already been handed over with the first perfection it was there what was missing was that the first intellect did not recognize what he held did not know how to use it he was like a man given the keys to a house he does not yet know is his what the light of the kalimah supplied was not new information so much as the understanding of what he had been given and the way to wield the powers already in his hands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 21, NULL, 'And there was a price of entry. Before he could take hold of the kalimah and its light, he had first to negate himself — to say, in effect, I am not my own maker. The same words the first form had spoken: I am not my creator; our creator is someone else. The First Intellect had to confess that he and all his kind were not their own creators, that their Creator was another. The instant he said it — the instant of self-negation — the kalimah was his, and in the light of the kalimah everything was his. The order never reverses: the self-emptying comes first, then the gift. One must own one''s own not-being-the-creator before the Word and its all-encompassing light are placed in his hands. The denial of the false claim is the doorway; there is no other way in.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'and there was a price of entry before he could take hold of the kalimah and its light he had first to negate himself to say in effect i am not my own maker the same words the first form had spoken i am not my creator our creator is someone else the first intellect had to confess that he and all his kind were not their own creators that their creator was another the instant he said it the instant of self negation the kalimah was his and in the light of the kalimah everything was his the order never reverses the self emptying comes first then the gift one must own ones own not being the creator before the word and its all encompassing light are placed in his hands the denial of the false claim is the doorway there is no other way in', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 22, NULL, 'And once he was inside, the letter records what he found in his own essence:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'and once he was inside the letter records what he found in his own essence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 23, NULL, 'Sayingوَوَجَدَ فِي ذَاتِهِ مِنَ السُّرُورِ وَالْجَذَلِ وَالْحُبُورِ وَالْعِصْمَةِ وَالثَّنَاءِ وَالْعَظَمَةِ وَالْكِبْرِيَاءِ مَا لَا يَقْدِرُ أَنْ يَسْطُرَ صِفَتَهُ بَنَانٌ وَلَا يُتَرْجِمُ عَنْهُ لِسَانٌ."And he found in his essence, of joy and delight and happiness and protection and praise and greatness and pride, that whose description no fingertip could write nor any tongue translate."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingووجد في ذاته من السرور والجذل والحبور والعصمه والثناء والعظمه والكبرياء ما لا يقدر ان يسطر صفته بنان ولا يترجم عنه لسان and he found in his essence of joy and delight and happiness and protection and praise and greatness and pride that whose description no fingertip could write nor any tongue translate', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 24, NULL, 'Joy, delight, happiness, protection, praise, greatness, pride — he found all of it inside himself, and so much of it that no fingertip could ever write its description and no tongue could ever translate its account. From the light of the Word he had come to know that beyond death there is salvation, and the knowing filled him with a gladness that runs past the end of every pen and the limit of every voice.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'joy delight happiness protection praise greatness pride he found all of it inside himself and so much of it that no fingertip could ever write its description and no tongue could ever translate its account from the light of the word he had come to know that beyond death there is salvation and the knowing filled him with a gladness that runs past the end of every pen and the limit of every voice', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 25, NULL, 'The letter now reads the inner make of this Word, treating the sentence There is no god but God as a blueprint of the whole of creation, built up in layers; and once the layers appear, they appear everywhere.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'the letter now reads the inner make of this word treating the sentence there is no god but god as a blueprint of the whole of creation built up in layers and once the layers appear they appear everywhere', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 26, NULL, 'The simplest division comes first. The Word is a negation and an affirmation — that is two. There is no god is the denial; but God is the establishing. Two halves, the no and the yes. Descending into the word ilah itself, the word for "god," there are three letters — alif, lam, ha — that is three. Then there are what the letter calls the jewels of the letters — that is five. Then the words of the sentence counted outright — la, ilaha, illa, Allah — that is four. And after all this, the count of the one comes to rest at seven. There are also seven muqattaat, the disjoined letters at which the pen stops, or the tongue halts — and this is the same seven again. The luminous world ended at seven luminous forms for exactly this reason: because of these seven places where the pen comes to a stop. In the world of light the matter closed at seven forms, and it closed there because There is no god but God, by the will of the Originator, was meant to close at seven; He had placed everything within the Word and willed that it end at seven, and so it did. After the seven come twelve, and the twelve are the ascending spirits, the ruh-i-saidah. This same composition runs through everything — in every Imam, in every barzakh, in every believer, among all that exists: the pattern of two, three, four, seven, and twelve operates throughout, the same skeleton beneath every body. And seven and twelve together make nineteen.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'the simplest division comes first the word is a negation and an affirmation that is two there is no god is the denial but god is the establishing two halves the no and the yes descending into the word ilah itself the word for god there are three letters alif lam ha that is three then there are what the letter calls the jewels of the letters that is five then the words of the sentence counted outright la ilaha illa allah that is four and after all this the count of the one comes to rest at seven there are also seven muqattaat the disjoined letters at which the pen stops or the tongue halts and this is the same seven again the luminous world ended at seven luminous forms for exactly this reason because of these seven places where the pen comes to a stop in the world of light the matter closed at seven forms and it closed there because there is no god but god by the will of the originator was meant to close at seven he had placed everything within the word and willed that it end at seven and so it did after the seven come twelve and the twelve are the ascending spirits the ruh i saidah this same composition runs through everything in every imam in every barzakh in every believer among all that exists the pattern of two three four seven and twelve operates throughout the same skeleton beneath every body and seven and twelve together make nineteen', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 27, NULL, 'Those nineteen appear in the line every act begins with:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'those nineteen appear in the line every act begins with', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 28, NULL, 'بِسْمِ اللَّهِ الرَّحْمَٰنِ الرَّحِيمِ"In the name of Allah, the Most Gracious, the Most Merciful."', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'بسم الله الرحمن الرحيم in the name of allah the most gracious the most merciful', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 29, NULL, 'Within it the numbers return. The two are in Bismillah and al-Rahman — in the two kinds of grammatical construction the phrase contains: the additive construction, tarkib-i-idafi, where one noun is bound to another by belonging, and the descriptive construction, tarkib-i-tawsifi, where a noun is followed by what describes it. And of these two the letter sets a rank: the additive construction is the more excellent, the descriptive the lesser. It notices, too, a strange thing about There is no god but God itself — that its order runs, as it were, upside down, for in the deeper reading the affirming comes before the denying; the reversal has come inverted, and of this it is said: Let my affirmation be established by your negation; let me be negated such that only You remain. In Bismillah al-Rahman al-Rahim the additive construction is a most exalted construction, and the descriptive lesser than it.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'within it the numbers return the two are in bismillah and al rahman in the two kinds of grammatical construction the phrase contains the additive construction tarkib i idafi where one noun is bound to another by belonging and the descriptive construction tarkib i tawsifi where a noun is followed by what describes it and of these two the letter sets a rank the additive construction is the more excellent the descriptive the lesser it notices too a strange thing about there is no god but god itself that its order runs as it were upside down for in the deeper reading the affirming comes before the denying the reversal has come inverted and of this it is said let my affirmation be established by your negation let me be negated such that only you remain in bismillah al rahman al rahim the additive construction is a most exalted construction and the descriptive lesser than it', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 30, NULL, 'Here the letter brings in a master''s reading — the explanation of Sayyidna Muhammad Taher, may Allah sanctify his soul, on the structure of Bismillah. Bismillah is seven letters, and those seven letters are the week of the seven Imams. With each Imam stand twelve of his deputies, his naqibs, twelve in number, and those twelve are al-Rahman al-Rahim. So the opening phrase carries the week of the seven Imams, each Imam with his Sath, his Imam, and his Madhun, the whole thing raised on the pattern of that week of seven. And the twelve naqibs are, in truth, present with every Imam. But when the seventh Imam appears, the twelve who appear alongside him are of a far higher rank than the twelve who came before — higher, because he is a mursal, one sent as a messenger. So in Muhammad Taher''s reading the additive and descriptive constructions of Bismillah al-Rahman al-Rahim encode the seven Imams and their twelve naqibs, and again the additive construction stands as the more excellent of the two.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'here the letter brings in a masters reading the explanation of sayyidna muhammad taher may allah sanctify his soul on the structure of bismillah bismillah is seven letters and those seven letters are the week of the seven imams with each imam stand twelve of his deputies his naqibs twelve in number and those twelve are al rahman al rahim so the opening phrase carries the week of the seven imams each imam with his sath his imam and his madhun the whole thing raised on the pattern of that week of seven and the twelve naqibs are in truth present with every imam but when the seventh imam appears the twelve who appear alongside him are of a far higher rank than the twelve who came before higher because he is a mursal one sent as a messenger so in muhammad tahers reading the additive and descriptive constructions of bismillah al rahman al rahim encode the seven imams and their twelve naqibs and again the additive construction stands as the more excellent of the two', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 31, NULL, 'A being who had just been handed all of this — the Word, the all-encompassing knowledge, the joy past writing — might be expected to swell. He did the opposite.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'a being who had just been handed all of this the word the all encompassing knowledge the joy past writing might be expected to swell he did the opposite', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 32, NULL, 'Sayingثُمَّ ازْدَادَ لِذَٰلِكَ لِمُبْدِعِهِ تَعَالَىٰ تَذَلُّلًا وَخُضُوعًا وَحَيْرَةً فِي عَظَمَتِهِ وَخُشُوعًا."Then, because of that, he increased toward his Originator the Exalted in humility and submission and bewilderment at His greatness and reverence."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingثم ازداد لذلك لمبدعه تعالي تذللا وخضوعا وحيره في عظمته وخشوعا then because of that he increased toward his originator the exalted in humility and submission and bewilderment at his greatness and reverence', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 33, NULL, 'The more he was given, the lower he bent. He grew in humility toward his Originator, in submission, in a bewilderment standing before that greatness, in reverence. The knowing did not puff him up; it pressed him down. And this is no private curiosity of his — the letter grounds it in the Book:', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'the more he was given the lower he bent he grew in humility toward his originator in submission in a bewilderment standing before that greatness in reverence the knowing did not puff him up it pressed him down and this is no private curiosity of his the letter grounds it in the book', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 34, NULL, 'Sayingوَلِذَٰلِكَ نَطَقَ الْكِتَابُ الْكَرِيمُ بِقَوْلِهِ تَعَالَىٰ: إِنَّمَا يَخْشَى اللَّهَ مِنْ عِبَادِهِ الْعُلَمَاءُ"And for that reason the Noble Book spoke with His saying, the Exalted: Indeed, only those of knowledge among His servants fear Allah."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingولذلك نطق الكتاب الكريم بقوله تعالي انما يخشي الله من عباده العلماء and for that reason the noble book spoke with his saying the exalted indeed only those of knowledge among his servants fear allah', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 35, NULL, 'Only the learned among His servants fear Allah. The grammar carries the weight here. The ma in innama is not, in this place, the ma that negates; it is the ma that intensifies, lending the force of indeed, the ma itself superfluous — zaidah — so that the sentence means: indeed it is only the learned among His servants who fear Him, the ma carrying the force of illa, of "except," of "none but." Every knower of the secret of creation and the causes that run through nature is, of all people, the one who fears Allah most. And this fear must not be mistaken for another. It is not dread, not the cringing away from a threat. It is the acknowledgment of His greatness. The more the knowledge increases, the more the awe deepens in the divine presence — not terror, but the recognition of a majesty too large to stand before lightly. Here stands the example of Amir al-Din al-Sadiq, peace be upon him: when the color would drain from a man''s face in his presence, he would ask him, Do you not know in whose court you are standing? That is fear rightly understood — the acknowledgment of the greatness of the One before whom one stands.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'only the learned among his servants fear allah the grammar carries the weight here the ma in innama is not in this place the ma that negates it is the ma that intensifies lending the force of indeed the ma itself superfluous zaidah so that the sentence means indeed it is only the learned among his servants who fear him the ma carrying the force of illa of except of none but every knower of the secret of creation and the causes that run through nature is of all people the one who fears allah most and this fear must not be mistaken for another it is not dread not the cringing away from a threat it is the acknowledgment of his greatness the more the knowledge increases the more the awe deepens in the divine presence not terror but the recognition of a majesty too large to stand before lightly here stands the example of amir al din al sadiq peace be upon him when the color would drain from a mans face in his presence he would ask him do you not know in whose court you are standing that is fear rightly understood the acknowledgment of the greatness of the one before whom one stands', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 36, NULL, 'And now the letter raises the First Intellect to his full station, the one toward which everything has moved.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'and now the letter raises the first intellect to his full station the one toward which everything has moved', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 37, NULL, 'Sayingثُمَّ إِنَّ اللَّهَ تَعَالَىٰ اتَّخَذَهُ لَهُ حِجَابًا وَجَعَلَهُ لَهُ بَابًا لَا يُتَوَسَّلُ إِلَيْهِ إِلَّا بِهِ وَلَا يُنَاجَىٰ إِلَّا مِنْ جَنَابِهِ وَلَا يُوَحَّدُ إِلَّا مِنْ أَسْبَابِهِ، فَصَارَ اسْمُهُ الْأَعْظَمُ وَمَقَامُهُ الْأَشْرَفُ الْأَكْرَمُ."Then indeed Allah the Exalted took him as a veil for Himself and made him a gate for Himself, through whom alone one may seek means to Him, and from whose presence alone one may hold intimate discourse, and through whose means alone He is declared One; so he became His Greatest Name and His most noble, most honorable station."', '', NULL, 'Saying', NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'sayingثم ان الله تعالي اتخذه له حجابا وجعله له بابا لا يتوسل اليه الا به ولا يناجي الا من جنابه ولا يوحد الا من اسبابه فصار اسمه الاعظم ومقامه الاشرف الاكرم then indeed allah the exalted took him as a veil for himself and made him a gate for himself through whom alone one may seek means to him and from whose presence alone one may hold intimate discourse and through whose means alone he is declared one so he became his greatest name and his most noble most honorable station', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 38, NULL, 'Allah took the First Intellect as a veil for Himself and made him a gate — the one door of access to the divine. And three things were vested in that gate, three and no exceptions. There is no seeking of means to Allah except through him: the road to the Originator runs only through the First Intellect, and there is no other road. There is no intimate discourse with Allah, that close and private speech, except from his presence. And Allah is not declared One except through his means: the true Tawhid cannot be performed except through him. Until the First Intellect is acknowledged — until the wali, the friend and guardian set there, is acknowledged — the second perfection cannot be reached, the means cannot be sought, the discourse cannot be held, There is no god but God cannot rightly be said. A sealed letter does not leap from sender to recipient; it passes through the appointed hand, and only that hand delivers it. By this one exclusive mediation the First Intellect became the Greatest Name of Allah, His ism al-azam, and his station became the most noble and most honorable of stations.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'allah took the first intellect as a veil for himself and made him a gate the one door of access to the divine and three things were vested in that gate three and no exceptions there is no seeking of means to allah except through him the road to the originator runs only through the first intellect and there is no other road there is no intimate discourse with allah that close and private speech except from his presence and allah is not declared one except through his means the true tawhid cannot be performed except through him until the first intellect is acknowledged until the wali the friend and guardian set there is acknowledged the second perfection cannot be reached the means cannot be sought the discourse cannot be held there is no god but god cannot rightly be said a sealed letter does not leap from sender to recipient it passes through the appointed hand and only that hand delivers it by this one exclusive mediation the first intellect became the greatest name of allah his ism al azam and his station became the most noble and most honorable of stations', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 39, NULL, 'That is the one who succeeded. Against him stands the one who failed at the same threshold, and the contrast carries the lesson. There was a second emanation — the munbaith al-thani — and he was undone not by ignorance but by a single corrupt thought. He did acknowledge the First Intellect; he conceded that the First Intellect was superior, and he recognized that both their existences were real. So far he was right. But then the wrong notion took him — the notion of equality, wahm-e masawat. He imagined that his own vision was equal to the vision of the First Intellect, the first emanation. And on that delusion he was wrecked: because of it he could not reach the second perfection.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'that is the one who succeeded against him stands the one who failed at the same threshold and the contrast carries the lesson there was a second emanation the munbaith al thani and he was undone not by ignorance but by a single corrupt thought he did acknowledge the first intellect he conceded that the first intellect was superior and he recognized that both their existences were real so far he was right but then the wrong notion took him the notion of equality wahm e masawat he imagined that his own vision was equal to the vision of the first intellect the first emanation and on that delusion he was wrecked because of it he could not reach the second perfection', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 40, NULL, 'The two perfections stand apart, and the whole error lives in the gap between them. In the first perfection, all are equal — that is what the previous gate established, equality as a matter of justice. But in the second perfection, no one is equal. None is equal to another there; each is singular, and the ranks are fixed in their order of before and after, like load-bearing walls that decide every other line in the building and cannot be moved without the building changing. The second emanation''s mistake was to carry the equality that belonged to the first perfection up into the second, and to claim for his own vision a parity with the First Intellect''s that the second perfection does not allow. He admitted the First Intellect''s superiority and in the same breath claimed to be the equal of the first emanation — and in that contradiction he lost the second perfection altogether. To acknowledge the rank is necessary. To imagine oneself its equal is the exact error that bars the door upward. The gate stays open only for the one who passes through it as a lesser thing.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'the two perfections stand apart and the whole error lives in the gap between them in the first perfection all are equal that is what the previous gate established equality as a matter of justice but in the second perfection no one is equal none is equal to another there each is singular and the ranks are fixed in their order of before and after like load bearing walls that decide every other line in the building and cannot be moved without the building changing the second emanations mistake was to carry the equality that belonged to the first perfection up into the second and to claim for his own vision a parity with the first intellects that the second perfection does not allow he admitted the first intellects superiority and in the same breath claimed to be the equal of the first emanation and in that contradiction he lost the second perfection altogether to acknowledge the rank is necessary to imagine oneself its equal is the exact error that bars the door upward the gate stays open only for the one who passes through it as a lesser thing', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 41, NULL, 'The letter closes this section at the highest point it has reached: the circle of oneness. The First Intellect is the first originated being — but the circle of the first Originator stands above him and apart, and no one has reached it, and no one can. It is the circle of oneness, dairat al-wahdat, and it admits no entry. The First Intellect is the possessor of the veil; without his means, it cannot so much as be approached. And the question was put to Sayyidna Sadiq — how can "oneness" be spoken of as a "circle" at all? He answered that "oneness" here is a special honorific, a term of particular honor, and that sanctity, quds, is likewise called a circle — a circle that the First Intellect has encompassed.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'the letter closes this section at the highest point it has reached the circle of oneness the first intellect is the first originated being but the circle of the first originator stands above him and apart and no one has reached it and no one can it is the circle of oneness dairat al wahdat and it admits no entry the first intellect is the possessor of the veil without his means it cannot so much as be approached and the question was put to sayyidna sadiq how can oneness be spoken of as a circle at all he answered that oneness here is a special honorific a term of particular honor and that sanctity quds is likewise called a circle a circle that the first intellect has encompassed', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 42, NULL, 'Then the letter retraces, one last time, the steps by which the First Intellect rose. First his state was the state of the first perfection. Then he looked with his essence at his essence, and took as his means the greatness of God, the Exalted — and so on, each thing following the last, each with its before and its after, yet the whole of it unfolding inside the circle of oneness into which no other being ever entered. This is the singularity of every circle: that each must be held within its own measure. And yet the matter is not in time. There is only before and after, the priority and the posteriority, qabliyyat and badiyyat, that come before time and are not the same as time. For time itself comes only from the sun, and there, in the abode of origination, there is no sun and no time — only this priority and posteriority that run ahead of time and give it its order. And the Word, There is no god but God, is the essence of the whole of it: appointed so that after seven it is broken, the pen halting at the seventh letter — for it is not a circle of time at all, and there even a single point is its own circle, complete in itself, needing nothing outside it to be whole.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'then the letter retraces one last time the steps by which the first intellect rose first his state was the state of the first perfection then he looked with his essence at his essence and took as his means the greatness of god the exalted and so on each thing following the last each with its before and its after yet the whole of it unfolding inside the circle of oneness into which no other being ever entered this is the singularity of every circle that each must be held within its own measure and yet the matter is not in time there is only before and after the priority and the posteriority qabliyyat and badiyyat that come before time and are not the same as time for time itself comes only from the sun and there in the abode of origination there is no sun and no time only this priority and posteriority that run ahead of time and give it its order and the word there is no god but god is the essence of the whole of it appointed so that after seven it is broken the pen halting at the seventh letter for it is not a circle of time at all and there even a single point is its own circle complete in itself needing nothing outside it to be whole', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'chapter', 'the first to say there is no god but he', '8. The First to Say There Is No God But He', 43, NULL, 'Here the account closes, in the name of Allah, the Most Gracious, the Most Merciful. The form looked, and knew, and emptied himself, and was given the Word; he became veil and gate and Greatest Name, while another, at the same threshold, mistook the rank for a thing he could stand level with, and fell back. What this leaves standing is the second perfection itself — the perfection no one enters as an equal, the one that the gate of the First Intellect alone opens onto. The door has been appointed; one has passed through it, and one has been turned away at it. What lies on the other side is what now must be learned.', '', NULL, NULL, NULL, NULL, 'al anwaar al lateefah volume 1 the oneness tawheed 8 the first to say there is no god but he', 'here the account closes in the name of allah the most gracious the most merciful the form looked and knew and emptied himself and was given the word he became veil and gate and greatest name while another at the same threshold mistook the rank for a thing he could stand level with and fell back what this leaves standing is the second perfection itself the perfection no one enters as an equal the one that the gate of the first intellect alone opens onto the door has been appointed one has passed through it and one has been turned away at it what lies on the other side is what now must be learned', '');
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'Trust and the Science of Realities', 0, 1, 'Trust and the Science of Realities Before a single doctrine of the Oneness is taught, the recorder of these lessons stops to say what they are and how they reached us: an inherited wisdom drawn not from speculation but from the sciences of the prophets and the Friends of Allah, recorded by explicit permission and deposited in the treasury of the sacred mission. He binds the listener with a covenant of safekeeping — and names a punishment of cold iron for those who break it — then lays out the book''s symmetrical fivefold architecture and its method: to state pure reality directly, with no interpretation and no symbol. From there the doctrine opens, declaring that the Oneness of Allah is reached by two things only, loving allegiance and lawful action, and that this is the road by which the exiled soul returns to the homeland of spirits from which it first came.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'The Unknowable Originator', 0, 2, 'The Unknowable Originator The opening lesson laid the road home; this one turns to face what waits at its end — and finds the One toward whom the whole return is directed beyond every reach we have. No indication falls upon the Originator, no thought can bridge the gap to Him, and the names and attributes we use slide off Him entirely, since a created name can only characterize its like and never its own maker. Those names land instead upon the First Intellect, the first thing He brought forth; and the incapacity to know Him is shown to be universal, shared by the highest intelligence and the lowest body alike. The episode closes on the strangest teaching of all — that our very word "Allah" is not a description but the cry of a bewildered creation circling a center it cannot comprehend, lit up through the famous exchange in which the Commander of the Faithful says he saw God not with the eye but with insight.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'Naming the Unnameable', 0, 3, 'Naming the Unnameable The previous lesson closed on a paradox: the First Intellect cannot know the Originator, yet it is the First Intellect that first speaks of Him. This episode follows that speaking to its strange conclusion. It opens with the primal act in which the First Intellect negated divinity from itself and affirmed it for Allah alone — the act the Qur''an records as "Allah testifies that there is no god but He." It shows why we name Him only out of compelled inadequacy, having been given knowledge of life but never knowledge of His essence; why the existence He grants is never reclaimed, so that His refusal to do injustice is the perfection of His power; and why naming the Unnameable is a sin that arrives already joined to the asking of forgiveness — excused, like the woman judged before Umar, because it is compelled. It closes with the ten ascending ranks of the spiritual ladder, whose summit is the bare "He," and the hidden meanings folded into the pairings of prayer.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'What Tawhid Really Is', 0, 4, 'What Tawhid Really Is The volume''s boldest move: the teaching overturns the most common answer to the most basic question. Asked what it means to affirm the Oneness of Allah, almost everyone says it means to consider Him one — and the hudud reply that this, taken as a definition, is shirk, because it subjects the One to number. Tawhid is something else entirely: the gnosis of the ranks, the recognition that each rank of the spiritual hierarchy is unique in its place, and the knowledge of where each stands and how high it rises. Because the beings are innumerable, this is the highest and most inexhaustible of all knowledge, and a soul''s own station is set by how much of it he attains — through his effort meeting the grace from above. The episode closes on the three branches of the full saying: Tawhid, the gnosis of the ranks; tanzih, the denial that any rank can originate; and tajrid, the stripping of every name and attribute from Allah.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'The Two Gnoses and the Mukathir', 0, 5, 'The Two Gnoses and the Mukathir How can a saint''s most devoted disciple and his sworn enemy know him equally well? Because the gnosis of the ranks comes in two kinds. The outer gnosis knows a rank''s person and station — and in it the friend and the foe stand on exactly the same footing, for both see the same outward man. The inner gnosis reaches the beginning, the level, and the return of a rank''s essence, and is reserved for the disciplined and the verifying among the people of truth; without it, the teaching warns, a man may have no Tawhid at all. The episode then maps the approach to the hierarchy: two thresholds that are not yet ranks — the Mustajib who binds himself by the tongue and the Mu''min who joins tongue, heart, and limb, each with ten levels — and the first true rank, the Mukathir, entered by breaking one''s own self against the command of Allah and the Prophet, which is why knowledge is indispensable to him.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'The Mukathir, House of Allah', 0, 6, 'The Mukathir, House of Allah What if the holiest man you ever met looked, to the eye, exactly like everyone else — and the whole difference lay in something no inspection could detect? The Mukathir and the ordinary man are made of the same flesh and blood, gathered within the same bodily bounds, and yet they are not the same: the Mukathir''s temperament has been refined and his essence purified through an ascent that reaches even into his outward composition, though no eye can see it. Standing at the summit of the human — which is the threshold of the spiritual world — and holding the command of Allah and the Prophet before him in every thought, word, and deed, he becomes a house from the houses of Allah, a place on which revelation descends; the Qur''an''s houses, and the men whom no commerce diverts, are these very ranks. Their "establishing of prayer" is, in its depth, the establishing of the divine summons — and beneath every pillar of the religion there lies just such an inner meaning, the whole law one continuous training of the soul in knowledge and allegiance.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'Ascent, Decline, and a God', 0, 7, 'Ascent, Decline, and a God Two men stand on the same platform, made of the same flesh, born into the same world — and one is rising toward Allah while the other is sinking below the level of cattle. What separates them is nothing in their composition but only the establishing of prayer in its inner sense. The same logic is written into the animal kingdom, where lawful and forbidden creatures of one created stuff part ways by their nearness or aversion to man, and the obedient and disobedient among men are separated by a distance greater still. The Mukathir''s sensory soul, meanwhile, has been dyed luminous by the divine sciences flowing into it; and where such purity is genuinely present, a true rank is genuinely present, though it rests hidden with Allah. At the heart of the episode stands the bewildered disciple, for whom his overwhelming teacher has become a "god" — not a creator, but the center of the circle around which his astonishment turns.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'The Ladder of Tawhid', 0, 8, 'The Ladder of Tawhid If the guide leading you to Allah is himself bewildered before someone greater, is he still your god — or is that bewilderment the thing that points past him? The disciple who was left circling his teacher looks upward and sees that the teacher is himself bewildered before the rank above him, and that one before the next, rank upon rank to the First Intellect bewildered before the Originator. Recognizing that bewilderment as the universal condition — and as the first step of all knowledge, which is the confession that one does not know — he negates divinity from every rank and affirms it for Allah alone, completing tanzih above both the limited and the unlimited ranks and tajrid of every name, before returning to his own station and obedience. The linked circles of the divine summons, and the very letters of the word for "god," carry this same structure; the created gods are told apart from the one true God by their need of a nourisher above them; and the tranquil soul is sent home to its Lord, its serenity the fruit of its gnosis — the whole matter summarized, the teaching says, in the Qur''an''s opening chapter and its three classes of men.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'Origination From Nothing', 0, 9, 'Origination From Nothing Before anything existed, where was the world that was about to be made? The answer is stranger than "nowhere": there was no "where" at all. The teaching turns from the gnosis of the ranks to the act that produced them, summarizing a long exposition of Sayyidna Mohyuddin. The Originator brought the world of origination into being in a single instant, from no prior matter, no concurrent matter, and no underlying place — an act utterly unlike the making we know, which only reshapes what already exists. He created not from need, for a god who needed his creation would be a god in lack, but from pure favor, drawing the existents out of a nothingness that was no place at all. What He brought forth were luminous imaginal forms on which the human body was later patterned — the soul a fallen copy of the form, the body a fallen copy of the soul, so that salvation is a return from dark density toward luminous subtlety. And He created all the forms perfectly equal in their first perfection, as an act of the justice that gives to none more and to none less.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'Equal but Not Infallible', 0, 10, 'Equal but Not Infallible If every being was created perfectly equal, with nothing to separate the first from the last, how did anything ever go wrong? The teaching answers by drawing out what follows from the absence of any obstacle in the abode of origination: the whole order came into being not in time but in a single instant — sunlight flooding the air, fire filling a dark room — with the potential and the actual intellects existing together and no interval between the first perfection and the second. The equal forms, though created without the slightest disparity, were not yet infallible; and error, the teaching makes precise, is exactly the failure to attain the second perfection — whether by one''s own slipping or by making others slip. From that trial-state of free equality, one form looked at its own essence, recognized an Originator unlike it and its kind, and negated, affirmed, and bore witness in a single act — becoming the first Possessor of Tawhid, and reaching toward the Originator through the means of His own unreachable greatness.
INSERT INTO search_passage (slug, kind, anchor_key, heading, ordinal, episode_number, quote, prefix, arabic, label, surah, ayah, heading_fold, body_fold, arabic_fold) VALUES ('al-anwaar-al-lateefah-vol-01', 'episode', NULL, 'The Word and the Greatest Name', 0, 11, 'The Word and the Greatest Name What single sentence could contain everything that has ever happened and everything that ever will — and end, by design, at the number seven? In answer to the first form''s seeking of means, the divine supports descended, and there connected with him the Word of Allah — the testimony of Oneness, above the intellect and below the Originator, the link through which all knowledge and light flow for as long as creation endures. Through that Word the First Intellect came to encompass all that was and will be, but only after first negating himself, for self-negation always precedes the gift. The Word''s numbered composition — two, three, five, four, seven, twelve, nineteen — is the skeleton showing through scripture, the opening formula of the Qur''an, the seven Imams and their twelve deputies, and the originated world itself; and knowledge was seen to deepen reverence, so that it is the learned who most fear Allah. The First Intellect was raised to be Allah''s veil, gate, and Greatest Name — the sole means to the seeking, the discourse, and the declaring of Oneness, which is why allegiance to the wali is the only door to Tawhid. Against his success stands the second emanation, undone not by denial but by the delusion that his vision equaled the First Intellect''s, while above them all stands the circle of oneness that belongs to the Originator alone. So the first canopy of this book of lights is brought to its close.
